SELECT 'moj-all-verified-judgments-review-002-chunk-151' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"3a67be2f-d09a-55c2-8377-0644990cf7c4","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مختلس -اختاس مبلغ مالي عن طريق خيانة األمانة - اختاس عن طريق عملية إلكترونية -شهادة الشهود -اختصاص- إثبات الدفع بالبراءة -مين على نفي الدعوى -احلكم برد الدعوى","document_number":"3414283","case_number":"3314349","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بأبها","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/17","year":"1434","subject":"رد مختلس -اختاس مبلغ مالي عن طريق خيانة األمانة - اختاس عن طريق عملية إلكترونية -شهادة الشهود -اختصاص- إثبات الدفع بالبراءة -مين على نفي الدعوى -احلكم برد الدعوى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/1/17 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3414283 :‬‬\n                         ‫َر ْق ُم الدعوى‪3314349 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34313675‬تاريخه‪1434/9/7:‬هـ‬\n\n\n      ‫رد مختلــس ‪ -‬اختــاس مبلــغ مالــي عــن طريــق خيانــة األمانــة ‪-‬‬\n      ‫اختــاس عــن طريــق عمليــة إلكترونيــة ‪ -‬شــهادة الشــهود ‪ -‬اختصــاص‪-‬‬\n      ‫إثبــات الدفــع بالبــراءة ‪ -‬ميــن علــى نفــي الدعــوى‪ -‬احلكــم بــرد الدعــوى‬\n                                                              ‫‪ -‬حكــم حضــوري ‪.‬‬\n\n\n\n\n      ‫مــا أســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                               ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل الشــركة املدعيــة علــى املدعــى عليهمــا بــأن األول َّإبــان‬\n      ‫عملــه لــدى موكلتــه كمنــدوب مبيعــات أصــدر أمــر شــراء بضاعــة‬\n      ‫مــن مســتودعاتها ثــم باعهــا بنفــس الرقــم الســري اخلــاص بــه ولــم يقــم‬\n      ‫بإيــداع قيمــة البضاعــة لصالــح الشــركة وبعــد مواجهــة احملاســب لــه‬\n      ‫بهــذا االختــاس أنكــره وذكــر أن املدعــى عليــه الثانــي هــو مــن قــام‬\n      ‫بذلــك فأنكــر الثانــي أيض ـ ًا عالقتــه بعمليــة االختــاس‪ ،‬ولــذا فقــد‬\n      ‫طلــب إلزامهمــا بتســليم موكلتــه املبلــغ الــذي مت اختالســه‪ -‬أنكــر‬\n      ‫املدعــى عليهمــا مــا جــاء يف الدعــوى ودفــع األول بأنــه أثنــاء حصــول‬\n      ‫عمليــة الشــراء والبيــع لــم يكــن موجــود ًا يف مقــر الشــركة ولديــه شــهود‬\n\n‫‪303‬‬\n\f‫يشــهدون بذلــك كمــا دفــع بــأن مــن عادة الشــركة إعداد محضر تســلم‬\n‫البضاعــة‪ -‬قــررت احملكمــة ســماع شــهادة الشــهود علــى إثبــات مــا دفــع‬\n‫بــه األول فشــهدوا مبــا يثبــت ذلــك‪ ،‬كمــا قــررت توجيــه اليمــن إليه على‬\n‫نفــي الدعــوى فأداهــا طبــق مــا طلــب منــه‪ -‬املدعــى عليــه الثانــي أقــر بــأن‬\n‫اجلهــاز الــذي متــت مــن خاللــه عمليــة االختــاس يقــع يف مقــر عملــه الدائــم‬\n‫كمــا أنــه تناقــض يف أقوالــه أمــام احملكمــة‪ -‬لذلــك قضــت احملكمــة‬\n‫بإلــزام املدعــى عليــه الثانــي بتســليم الشــركة املدعيــة املبلــغ املدعــى‬\n‫بــه كمــا قضــت بصــرف النظــر عــن دعــوى املدعــي ضــد املدعــى عليــه‬\n‫األول ‪ -‬عــارض املدعــي وكالــة واملدعــى عليــه الثانــي علــى احلكــم‪-‬‬\n                         ‫قــررت محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد فلــدي‬\n‫أنــا‪ ........./‬القاضــي يف احملكمــة العامــة بأبهــا وبنــاء علــى املعاملــة‬\n‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بأبهــا املســاعد برقــم‬\n‫‪ 3314349‬وتاريخ ‪1433/01/05‬هـ املقيدة باحملكمة برقم ‪3335893‬‬\n‫وتاريــخ ‪1433/01/05‬ه ـ ففــي يــوم االثنــن املوافــق ‪ 1433/02/29‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 12 : 11‬وفيهــا حضــر‪ ........... /‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬بصفتــه وكيــا عــن الشــركة‬\n‫املدعيــة شــركة ‪ ...‬مبوجــب صــك الوكالــة الصــادر مــن كتابــة العــدل‬\n‫الثانيــة بجنــوب جــدة برقــم ‪ 3059‬وتاريــخ ‪1432/1/23‬ه ـ وبســؤال‬\n‫املدعــي وكالــة عــن دعــواه أجــاب قائــا ان املدعــى عليــه هــذا احلاضــر‬\n‫هنــدي اجلنســية مبوجــب اإلقامــة رقــم يعمــل لــدى شــركة ‪ ...‬لالتصــاالت‬\n\n                                                                                       ‫‪304‬‬\n\f      ‫موكلتــي بوظيفــة منــدوب مبيعــات مهمــة عملــه التســوق للشــركة ببيــع‬\n      ‫بطاقــات الشــحن وشــرائح ومــن طبيعــة عمــل الشــركة أن كل موظــف‬\n      ‫لــه رقــم ســري خــاص بــه يســتطيع مــن خاللــه إصــدار أمــر شــراء مــن‬\n      ‫مســتودع الشــركة وكذلــك تســلم البضائــع مــن املســتودع وبنــاء علــى‬\n      ‫ذلــك فقــد قــام املدعــى عليــه بإصــدار أمــر شــراء بضاعــة بطاقــات شــحن‬\n      ‫مــن مســتودع الشــركة مببلــغ وقــدره مائتــان وســبعة وعشــرون ألــف ريال‬\n      ‫قــام بتســليمها بنفــس الرقــم الســري اخلــاص بــه وبــاع البضاعــة يف الســوق‬\n      ‫بنفــس مبلــغ الشــراء ولــم يقــم بإيــداع لهــذا املبلغ لدى الشــركة موكلتي‬\n      ‫وقــام محاســب الشــركة بالتدقيــق وســأل املدعــى عليــه عــن ذلــك‬\n      ‫فأجابــه بأنــه لــم يقــرر أمــر شــراء وال تســلم وإمنــا كان ذلــك عــن طريــق‬\n      ‫زميلــه يف العمــل يف نفــس املكتــب بتواجــده ويدعــى مينــي اجلنســية وقــد‬\n      ‫أنكــر ‪ ...‬املذكــور أمــام احملاســب لذلــك أطــب احلكــم علــى املدعــى‬\n      ‫عليهمــا بإلزامهمــا بتســليمي مبلــغ وقــدره مائتــان وســبعة وعشــرون ألــف‬\n      ‫ريــال هــذه دعــواي وبســؤال املدعــى عليــه عــن دعــوى املدعــي وكالــة‬\n      ‫أجــاب قائــا مــا ذكــره املدعــي وكالــة كلــه غيــر صحيــح مــا عــدا‬\n      ‫مســألة طبيعــة عمــل الشــركة فصحيــح والــذي قــام بهــذه العمليــة هــو‬\n      ‫عامــل لــدى الشــركة هــو هكــذا أجــاب ثــم جــرى رفــع اجللســة إلحضــار‬\n      ‫ويف جلســة أخــرى يــوم الســبت املوافق‪1433/05/22‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 11 : 50‬وفيهــا حضــر الطرفــان وحضــر حلضورهمــا مينــي‬\n      ‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم وبســؤال احلاضــر عمــا ذكــره‬\n      ‫املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــى عليــه يف جوابــه علــى‬\n      ‫الدعــوى كلــه صحيــح مــا عــدا مســألة إصــدار أمــر الشــراء والتســلم‬\n      ‫فغيــر صحيــح علمــا أن هــذا املكتــب هــو عبــارة عــن غرفــة بهــا مكتــب‬\n\n\n‫‪305‬‬\n\f‫واحــد عليــه جهــاز حاســب آلــي يتنــاوب اســتخدامه أنــا واملدعــى عليــه إال‬\n‫أننــي مســتقر فيــه دائمــا بينمــا املدعــى عليــه ميــر بــه ألجــل إصــدار أمــر‬\n‫شــراء وتســلم وعندمــا وقعــت هــذه القضيــة يف ‪2010/1/8‬م أصــدر‬\n‫املدعــى عليــه أمــر شــراء وتســلم بضاعــة بطاقــة شــحن وقــد تســلمت أمــر‬\n‫تســليم البضاعــة بنــاء علــى أمــر املركــز الرئيســي للشــركة يف جــدة‬\n‫وقمــت ببيعهــا هكــذا أجــاب ثــم أضــاف قائــا إننــي لــم أبعهــا وإمنــا قمــت‬\n‫بتســليم البضاعــة إلــى املدعــى عليــه عــن طريــق اجلهــاز هكــذا أجــاب‬\n‫وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا الصحيــح مــا ذكــرت‬\n‫علمــا أن مــن عــادة الشــركة هــو إعــداد محضــر تســلم البضاعــة ولــدي‬\n‫شــاهدان علــى أنــه ليــس لــي عالقــة باملدعــى بــه هكــذا قــرر ورفعــت‬\n‫اجللســة مــن أجــل ذلــك ويف جلســة أخــرى يــوم األربعــاء‬\n‫املوافق‪1433/06/18‬ه ـ افتتحــت اجللســة الســاعة ‪ 12 : 58‬وفيهــا حضــر‬\n‫املدعــى عليــه وحضــر حلضــوره هنــدي اجلنســية مبوجــب رخصــة اإلقامــة‬\n‫بصفتــه شــاهدا يف هــذه القضيــة وبســؤاله عمــا لديــه مــن شــهادة أجــاب‬\n‫قائال كنت أعمل يف شركة ‪ ....‬فرع أبها وقد كنت يوم ‪2010/1/8‬م‬\n‫كنــت مــع املدعــى عليــه مــن الســاعة الثالثــة والنصــف عصــرا وقــد‬\n‫ذهبنــا يف ســيارة املدعــى عليــه بعــد صــاة العصــر لتوزيــع بطاقــات‬\n‫اتصــاالت وحتصيــل مبالــغ إلــى صــاة املغــرب وصلينــا املغرب يف مســجد‬\n‫احلواشــي وقــد ذهبنــا بعــد الصــاة إلــى حــي اخلالديــة لتحصيــل مبلــغ مــن‬\n‫محــل جــواالت إلــى أذان العشــاء وبعــد ذلــك رجعنــا ألخــذ ابنائنــا مــن‬\n‫املدرســة ثــم قــام املدعــى عليــه بتوصيلــي إلــى بيتــي وأخبرنــي بأنــه‬\n‫ســيذهب إلــى أبهــا وبعــد ذلــك قمــت بالذهــاب إلى أبها بســيارة الشــركة‬\n‫إلجــراء صيانــة يف مدينــة أبهــا وقــد قابلــت املدعــى عليــه عنــد ســوق‬\n\n\n                                                                                       ‫‪306‬‬\n\f      ‫الســمك الســاعة الثامنــة والنصــف تقريبــا وكان الغــرض لذهابــي‬\n      ‫لســوق الســمك أخــذ زميلــي الفنــي الــذي يعمــل يف الشــركة هكــذا‬\n      ‫شــهد وقــد مت رفــع اجللســة لســماع أقــوال الشــاهد الثانــي ويف جلســة‬\n      ‫أخــرى يــوم االثنــن املوافــق ‪1433/07/07‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫الثانيــة عشــرة ظهــرا وفيهــا حضــر أطــراف الدعــوى وقــد طلــب مــن‬\n      ‫املدعــي وكالــة إحضــار وكالــة أخــرى غيــر الوكالــة الســابقة فأحضر‬\n      ‫صــك وكالــة صــادر مــن كتابــة العــدل الثانيــة بجنــوب جــدة برقــم‬\n      ‫‪ 28433‬وتاريــخ ‪1433/7/1‬ه ـ وبســؤال املدعــى عليــه ‪ ....‬عــن البينــة التي‬\n      ‫وعــد بإحضارهــا فأجــاب قائــا بان بينتي هو هذا الشــاهد احلاضر‪....../‬‬\n      ‫ســوداني اجلنســية مبوجــب رخصــة اإلقامــة رقــم وأطلــب ســماع مــا لــدى‬\n      ‫هــذا الشــاهد هكــذا قــرر وبســؤال الشــاهد احلاضــر عــن ســنه ومهنتــه‬\n      ‫ومحــل إقامتــه وعالقتــه باملدعــى عليــه أجــاب قائــا إننــي مــن مواليــد‬\n      ‫عــام ‪1978‬م ومهنتــي مهنــدس إلكترونــي وإقامتــي يف محافظــة خميــس‬\n      ‫مشــيط وال توجــد لــي عالقــة باملدعــى عليــه وبســؤاله عمــا لديــه مــن‬\n      ‫شــهادة قــال أشــهد هلل تعالــى أن وقــت صــاة العشــاء يف ‪2010/4/1‬م‬\n      ‫قــام بشــحن ماكينــة ‪ ...‬اخلاصــة ببطاقــات شــحن ‪ ...‬مببلــغ وقــدره ألــف‬\n      ‫ريــال يف محــل ‪ ...‬يف حــي ‪ ......‬بخميــس مشــيط هكــذا شــهد وبعــرض‬\n      ‫الشــاهد وشــهادته علــى املدعــى عليــه قــال أمــا الشــاهد فــا أعلــم عــن‬\n      ‫حالــه شــيئا وأمــا الشــهادة فغيــر صحيحــة هكــذا قــرر ثــم جــرى ســؤال‬\n      ‫املدعــي وكالــة عمــا لديــه بخصــوص هــذه الشــهادة أجــاب قائــا ال علــم‬\n      ‫لــي بذلــك وإمنــا الــذي أعلــم عنــه أن عمليــة الطلــب متــت يف ‪2010/4/1‬م‬\n      ‫الســاعة الســابعة وثمــان وعشــرين دقيقــة مســاء وعمليــة التحويــل متــت يف‬\n      ‫يــوم ‪2010/4/1‬م الســاعة الســابعة والنصــف مســاء وعمليــة التســلم متــت‬\n\n\n‫‪307‬‬\n\f‫يف يــوم ‪2010/4/1‬م الســاعة الســابعة وواحــد وثالثــن دقيقــة مســاء‬\n‫واملســافة بــن شــركة ‪ ...‬ومحــل ‪ ...‬ربــع ســاعة ثــم أبــرز املدعــي وكالــة‬\n‫ورقــة العمليــات التــي ذكرهــا بأوقاتهــا وجــرى االطــاع عليهــا فوجدتهــا‬\n‫مطابقــة ملــا ذكــر كمــا أبــرز الشــاهد ورقــة تتضمــن التأكيــد لصحــة‬\n‫مــا ذكــر ورفعــت اجللســة إلحضــار البينــة علــى عدالــة الشــهود ويف‬\n‫جلســة أخــرى يــوم االثنــن بتاريخ‪1433/12/20‬ه ـ افتتحــت اجللســة‬\n‫الســاعة الثامنــة صباحــا وفيهــا حضــر املدعــي وكالــة وحضــر حلضــوره‬\n‫املدعــى عليــه وبســؤال املدعــى عليــه عــن املزكيــة للشــهود أحضــر كل‬\n‫مــن ‪......‬ســوداني اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪......‬و ‪ ......‬هنــدي‬\n‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ .....‬وقــد جــرى ســؤالهم عمــا‬\n‫لديهــم مــن تزكيــة فأجــاب كل واحــد منهمــا قائــا أشــهد هلل تعالــى‬\n‫بــأن املدعــو هــذا احلاضــر عــدل ثقــة هكــذا شــهدا فبنــاء علــى مــا تقــدم‬\n‫فقــد جــرى طلــب اليمــن مــن املدعــى عليــه احلاضــر علــى نفــي أخــذه املبلغ‬\n‫املدعــى بــه بنــاء علــى قاعــدة الشــاهد واليمــن لكــون التزكيــة وردت‬\n‫علــى شــاهد واحــد فاســتعد ببذلهــا وجــرى تخويفــه بخطــر اليمــن‬\n‫الغمــوس ثــم طلــب منــه اليمــن فحلــف وفــق مــا طلــب منــه بــاهلل تعالــى‬\n‫قائــا واهلل العظيــم الــذي ال إلــه إال هــو أننــي لــم آخــذ املبلــغ املدعــى بــه‬\n‫ومقــداره مائتــان وســبعة وعشــرون ألــف ريــال وال شــيء منــه واهلل العظيم‬\n‫هكــذا حلــف فبنــاء علــى مــا تقــدم من الدعــوى واإلجابة ونظــرا إلنكار‬\n‫املدعــى عليــه صحــة الدعــوى وإلقــرار املدعــى عليــه بــأن املــكان الــذي‬\n‫هــو مقــر املبلــغ املدعــى بــه هــو املقــر الدائــم لعملــه وأن املدعــى عليــه‬\n‫يأتيــه أحيانــا ممــا يقــوي معــه توجــه التهمــة إلــى بأخــذه املبلــغ وإلقامــة‬\n‫املدعــى عليــه الشــاهد املعــدل شــرعا علــى نفــي تواجــد املدعــى عليــه‬\n\n\n                                                                                          ‫‪308‬‬\n\f      ‫وقــت أخــذ املبلــغ املدعــى بــه يف احملــل ولتناقــض إجابــة املدعــى عليــه يف‬\n      ‫مســألة تســلم البضاعــة وبيعهــا ممــا يقــوي معــه جانــب التهمــة يف أخــذ‬\n      ‫املبلــغ املدعــى بــه فقــد قــررت اآلتــي أوال صــرف النظر عن دعــوى املدعي‬\n      ‫ضــد املدعــى عليــه ‪ ...‬هنــدي اجلنســية مبوجــب رخصــة اإلقامــة رقــم ثانيــا‬\n      ‫إلــزام املدعــى عليــه مينــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم بدفــع‬\n      ‫مبلــغ وقــدره مائتــان وســبعة وعشــرون ألــف ريــال ومبــا تقــدم حكمــت‬\n      ‫ويعــد هــذا احلكــم حضوريــا وبعــرض احلكــم علــى املدعــي وكالــة قــرر‬\n      ‫عــدم القناعــة وطلــب االســتئناف بــدون تقــدمي الئحــة اعتراضيــة وســوف‬\n      ‫يجــري بــإذن اهلل بعــث نســخة مــن احلكــم إلــى املدعــى عليــه لتقــدمي‬\n      ‫اعتراضــه عليــه خــال ثالثــن يومــا مــن تاريــخ التســلم إذا لــم يقــدم‬\n      ‫اعتراضــه خاللهــا يســقط حقــه يف االعتــراض وبــاهلل التوفيــق وصلــى‬\n      ‫اهلل على نبينا محمد وعلى آله وصحبه وسلم حرر يف ‪1433/12/20‬هـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد ففــي‬\n      ‫هــذا اليــوم الثالثــاء بتاريــخ ‪1434/2/26‬ه ـ الســاعة العاشــرة وخمــس‬\n      ‫وأربعــون دقيقــة صباحــا افتتحــت اجللســة وقــد جــرى منــا بعــث نســخة مــن‬\n      ‫احلكــم عــن طريــق قســم اإلحضــار بهــذه احملكمــة للمدعــى عليــه‬\n      ‫لتقــدمي اعتراضــه علــى احلكــم باخلطــاب رقــم ‪ 34/204844‬وتاريــخ‬\n      ‫‪1434/1/25‬ه ـ فوردنــا الــرد مــن قســم اإلحضــار واملتضمــن « نفيدكــم‬\n      ‫بأنــه مت الذهــاب إلــى مجمــع األســواق قــرب مســجد النملــة ولــم جنــد‬\n      ‫أحــدا بهــذا االســم كمــا أن األرقــام املوضحــة بعاليــه ال يــرد عيهــا أحــد‬\n      ‫لــذا تعــذر علينــا تســليم صــورة صــك احلكــم « ولكــون احلــال مــا ذكــر‬\n      ‫فقــد قــررت بعــث كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق‬\n      ‫احلكــم ورفعــت اجللســة لذلــك حتــى ورود املعاملــة وبــاهلل التوفيــق وصلــى‬\n\n\n‫‪309‬‬\n\f‫اهلل علــى نبينــا محمــد وعلــى آلــه وصبــه وســلم حــرر يف ‪1434/2/26‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد ففــي‬\n‫هــذا اليــوم األحــد بتأريــخ ‪1434/5/26‬ه ـ الســاعة احلاديــة عشــرة‬\n‫والنصــف صباحــا افتتحــت اجللســة وقــد عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة برقــم ‪ 34783138‬وتاريــخ‬\n‫‪1434/5/15‬ه ـ برفقهــا قــرار املالحظــة الصــادر مــن الدائــرة اجلزائيــة‬\n‫الثالثــة برقــم ‪ 34210977‬وتاريــخ ‪1434/5/12‬ه ـ واملتضمــن « وبدراســة‬\n‫املعاملــة تقــرر باألكثريــة أن هــذه القضيــة مــن اختصــاص محكمــة‬\n‫االســتئناف مبنطقــة عســير ومــا أشــير إليــه بقرارهــم املرفــق رقــم‬\n‫‪ 3463967‬يف ‪1434/3/16‬ه ـ محــل نظــر حيــث لــم يطــرأ علــى احلكــم‬\n‫الســابق أي إشــكال بــل جــاء احلكــم جديــدا يف احلــق اخلــاص فــا واليــة‬\n‫حملكمــة االســتئناف مبكــة املكرمــة واحلــال مــا ذكــر ملالحظــة ذلــك‬\n‫واهلل املوفــق « وعليــه فقــد أمــرت بإحلــاق مــا تقــدم بالصــك وســجله ثــم‬\n‫بعــث كامــل أوراق املعاملــة إلــى محكمــة االســتئناف مبنطقــة عســير‬\n‫إلكمــال الــازم ورفعــت اجللســة لذلــك حتــى ورود املعاملــة وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n‫‪1434/5/26‬ه ـ احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي‬\n‫بعــده أمــا بعــد ففــي هــذا اليــوم األحــد بتأريــخ ‪1434/08/07‬ه ـ الســاعة‬\n‫العاشــرة صباحــا افتتحــت اجللســة وقــد عــادت املعاملــة مــن محكمــة‬\n‫االستئناف مبنطقة عسير برقم ‪ 341435142‬وتأريخ ‪1434/07/09‬هـ‬\n‫برفقهــا قــرار املالحظــة الصــادر مــن الدائــرة اجلزائيــة الرابعــة برقــم‬\n‫‪ 34254372‬وتأريــخ ‪1434/06/28‬ه ـ واملتضمــن « وبدراســة الصــك‬\n‫وصــورة ضبطــه وأوراق املعاملــة تقــرر إعادتهــا لفضيلــة حاكمهــا‬\n\n\n                                                                                    ‫‪310‬‬\n\f      ‫ملالحظــة مــا يلــي أوال أن فضيلتــه قــد أصــدر احلكــم بحــق املدعــى عليــه‬\n      ‫حضوريــا مــع أنــه لــم يبلــغ باحلكــم فيراعــى ذلــك وفــق النظــام ثانيــا‬\n      ‫حكــم فضيلتــه علــى املدعــى عليــه بدفــع مبلــغ مائتــن وســبعة وعشــرين‬\n      ‫ألفــا ولــم يبــن اجلهــة احملكــوم لهــا فيبــن ذلــك وعلــى فضيلتــه مالحظــة‬\n      ‫مــا ذكــر وإكمــال الــازم واهلل املوفــق « عليــه أجيــب أصحــاب الفضيلة‬\n      ‫باآلتــي بالنســبة إلــى الفقــرة أوال فقــد جــرى منــا تبليــغ املدعــى عليــه‬\n      ‫للحضــور إلــى هــذه احملكمــة عــن طريــق قســم اإلحضــار لتزويــده‬\n      ‫بنســخة مــن احلكــم لتقــدمي اعتراضــه عليــه خــال املــدة النظاميــة‬\n      ‫وبالنســبة للفقــرة ثانيــا فــإن املبلــغ احملكــوم بــه ومقــداره مائتــان وســبعة‬\n      ‫وعشــرون ألــف ريــال يســلم إلــى شــركة ‪ ...‬لالتصــاالت هــذا مــا لــدي‬\n      ‫وأمــرت بإحلــاق مــا تقــدم بالصــك وســجله وســوف يجــري بــإذن اهلل تعالــى‬\n      ‫إعــادة كامــل أوراق املعاملــة إلــى محكمــة االســتئناف إلكمــال الــازم‬\n      ‫ورفعــت اجللســة لذلــك حتــى ورود اجلــواب وبــاهلل التوفيــق وصلــى اهلل‬\n              ‫على نبينا محمد وعلى آله وصحبه وسلم حرر يف ‪1434/8/7‬هـ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد‬\n      ‫ففــي هــذا اليــوم الثالثــاء بتاريــخ ‪1434/9/22‬ه ـ حســب تقــومي أم‬\n      ‫القــرى الســاعة الثانيــة ظهــرا افتتحــت اجللســة وقــد عــادت املعاملــة‬\n      ‫مــن محكمــة االســتئناف مبنطقــة عســير برقــم ‪ 341435142‬وتاريــخ‬\n      ‫‪1434/09/17‬ه ـ برفقهــا قــرار املصادقــة الصــادر مــن الدائــرة اجلزائيــة‬\n      ‫الرابعــة برقــم ‪ 34313675‬وتاريــخ ‪1434/9/7‬ه ـ واملتضمــن « وحيــث‬\n      ‫ســبق دراســة الصــك وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى‬\n      ‫مــا أجــاب بــه فضيلتــه وأحلقــه بالضبــط والصــك وســجله بنــاء علــى‬\n      ‫قرارنــا رقــم ‪ 34254372‬وتاريــخ ‪1434/06/28‬ه ـ تقــررت املوافقــة‬\n\n\n‫‪311‬‬\n\f‫علــى احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق « وحتــى ال يخفــى جــرى‬\n‫التهميــش مبوجبــه وأمــرت بإحلــاق مــا تقــدم بالصــك وســجله وبــاهلل تعالى‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                          ‫‪1434/09/22‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                  ‫‪312‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":303,"source_page_end":312,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"80bfb613577072ea9765ab10f348904184ba2e19cc65cf5e780b065d41096882","normalized_text_hash":"37031939fdc392b2d93c4761ea951378bd4da39888273e449e76c7d160857b02","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p303-3414283"},{"id":"be0d7b07-cbdc-5267-b60d-c5a889b7be94","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مختلس -اختاس مبلغ مالي عن طريق خيانة األمانة -عجز عن إثبات الدفع -قرائن إدانه -أقوال املتهم تخالف املألوف واملعمول به -ثبوت الدعوى -احلكم باإللزام برد املبلغ .","document_number":"34167155","case_number":"32308699","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/21","year":"1434","subject":"رد مختلس -اختاس مبلغ مالي عن طريق خيانة األمانة -عجز عن إثبات الدفع -قرائن إدانه -أقوال املتهم تخالف املألوف واملعمول به -ثبوت الدعوى -احلكم باإللزام برد املبلغ .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/3/21 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34167155 :‬‬\n                         ‫َر ْق ُم الدعوى‪32308699 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34343519‬تاريخه‪1434/1/11 :‬هـ‬\n\n\n      ‫رد مختلــس ‪ -‬اختــاس مبلــغ مالــي عــن طريــق خيانــة األمانــة ‪ -‬عجــز‬\n      ‫عــن إثبــات الدفــع ‪ -‬قرائــن إدانــه ‪ -‬أقــوال املتهــم تخالــف املألــوف‬\n              ‫واملعمــول بــه ‪ -‬ثبــوت الدعــوى ‪ -‬احلكــم باإللــزام بــرد املبلــغ ‪.‬‬\n\n\n\n\n      ‫ق ــول ال ــنبي صلــى اهلل عليــه وســلم ‪ ( :‬عـ ــلى الـي ــد مــا أخــذت حتــى‬\n                                                                       ‫ت ــؤديـ ــه ) ‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل الشــركة املدعيــة بــأن املدعــى عليــه احلاضــر َّإبــان عملــه‬\n      ‫لديهــا كقائــد طاقــم نقــل أمــوال خاصــة باملصــارف اســتلم مــن موكلتــه‬\n      ‫ثمانيــة أكيــاس بهــا مبالــغ ماليــة لكــي يقــوم بتوصيلهــا إلــى أحــد‬\n      ‫املصــارف‪ ،‬وقــد قــام بتســليم املصــرف ســبعة أكيــاس أمــا الكيــس‬\n      ‫الثامــن ومــا فيــه مــن مبلــغ مالــي فقــد ادعــى أنــه ســلمه للمصــرف وتبــن‬\n      ‫كذبــه مــن خــال التحقيقــات اجلنائيــة‪ ،‬ولــذا فقــد طلــب إلزامــه بإعــادة‬\n      ‫املبلــغ املختلــس إلــى الشــركة موكلتــه‪ -‬أقــر املدعــى عليــه باســتالم‬\n      ‫األكيــاس الثمانيــة احملتويــة علــى األمــوال ودفــع بأنــه ســلمها ملوظــف‬\n      ‫بخزينــة املصــرف مبــا فيهــا الكيــس الثامــن احملتــوي علــى املبلــغ املالــي‬\n      ‫محــل الدعــوى إال أن املوظــف املذكــور لــم يســلمه ســندا باســتالمه‬\n\n‫‪313‬‬\n\f‫ولذلــك فهــو غيــر مســتعد بتســليم املدعيــة أي شــيء مــن املبلــغ املدعــى‬\n‫بــه ‪ -‬طلبــت احملكمــة مــن املدعــى عليــه تقــدمي بينــة علــى مــا دفــع بــه مــن‬\n‫تســليم الكيــس الثامــن مبــا فيــه مــن مبلــغ مالــي إلــى املصــرف فعجز عن‬\n‫إثبــات ذلــك الدفــع ‪ -‬املدعــى عليــه أقــر باســتالم املبالــغ املاليــة ودخولهــا‬\n‫يف عهدتــه وعجــز عــن إثبــات تســليم املبلــغ محــل الدعــوى إلــى املصــرف‪-‬‬\n‫قضــت احملكمــة بإلــزام املدعــى عليــه بتســليم الشــركة املدعيــة املبلــغ‬\n‫املدعــى بــه‪ -‬قنــع وكيــل املدعيــة باحلكــم وعــارض عليــه املدعــى عليــه‪-‬‬\n                      ‫قــررت محكمــة االســتئناف املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي‪ ...‬يف احملكمــة العامــة‬\n‫بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالدمــام برقــم ‪ 32308699‬وتاريــخ ‪ 1432/07/25‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 32944147‬وتاريــخ ‪ 1432/07/25‬ه ـ ففــي يــوم‬\n‫االثنــن املوافــق‪ 1433/01/17‬ه ـ حضــر‪ ...‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم بالوكالــة الصــادرة مــن كتابــة عــدل اخلبــر الثانيــة‬\n‫برقــم ‪ 19367‬يف ‪1432/6/11‬ه ـ جلــد ‪ 2843‬عــن‪ ...‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم بصفتــه شــريكا يف شــركة ‪ ...‬ملعــدات‬\n‫األمــن والســامة والتجــارة احملــدودة وبصفتــه وكيــا عــن شــريكه‬\n‫‪ ...‬وحضــر حلضــوره‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫ويف هــذه اجللســة قــال محــررا دعــواه لقــد كان املدعــى عليــه يعمــل يف‬\n‫شــركة موكلــي قائــد طاقــم نقــل أمــوال خاصــة بالبنــوك ويف تاريــخ‬\n‫‪1428/12/23‬ه ـ كلــف ومعــه زميلــن همــا الســائق وناقــل األكيــاس‬\n\n                                                                                         ‫‪314‬‬\n\f      ‫بنقــل ثمانيــة أكيــاس ســلمت بعهــدة املدعــى عليــه إليصالهــا إلــى‬\n      ‫اخلزينــة الرئيســية ملصــرف ‪ ...‬بالدمــام وقــد قــام املدعــى عليــه وزمــاءه‬\n      ‫وســلموا ســبعة أكيــاس كاملــه وادعــى املدعــى عليــه أنــه ســلم الكيس‬\n      ‫الثامــن للموظــف ويعمــل يف اخلزينــة الرئيســية ملصــرف ‪ ...‬وأنــه جحــده‬\n      ‫وقــد كان يف هــذا الكيــس ثالثــة ماليــن وثالثمائــة وخمســون ألــف‬\n      ‫ريــال ( ‪ ) 3.350.000‬كمــا يدعــي املدعــى عليــه أن قبــض منــه هــذا‬\n      ‫املبلــغ ورفــض تســليمه ســندا بذلــك وقــد حقــق يف هــذا األمــر بتحقيــق‬\n      ‫جنائــي ثبــت مــن خاللــه كــذب املدعــى عليــه وأن املبلــغ املفقــود حتــت‬\n      ‫مســؤوليته وال يــزال يف عهدتــه وقــد ســجن بســبب هــذه القضيــة أكثــر‬\n      ‫مــن أربــع ســنوات وال يــزال فيــه وألن شــركة موكلــي مؤمتنــه علــى هــذا‬\n      ‫املبلــغ وقــد غرمتــه ملصــرف ‪ ...‬وســددته لهــا فإنــا نطلــب إلــزام املدعــى‬\n      ‫عليــه بتســليم ثالثــة ماليــن وثالثمائــة وخمســن ألــف ريــال دون تأخيــر‬\n      ‫هــذه دعــواي وبســؤال املدعــى عليــه عــن هــذه الدعــوى قــال مــا ذكــره‬\n      ‫املدعــي مــن أنــي أعمــل يف شــركة موكليــه قائــد طقــم نقــل أمــوال وأن‬\n      ‫معــي الزميلــن املذكوريــن واســتلمنا ثمانيــة أكيــاس نقــود مــن فــروع‬\n      ‫مصــرف ‪ ...‬لتســليمها إلــى اخلزينــة الرئيســية فصحيــح ولقــد ســلمناها‬\n      ‫كاملــة إال أن القائمــن علــى اخلزينــة أعطونــا مــا يثبــت اســتالم ســبعة‬\n      ‫أكيــاس أمــا الكيــس الثامــن واحملتــوي علــى ثالثــة ماليــن وثالثمائــة‬\n      ‫وخمســن ألف ريال فقد اســتلموه وســألوني عن ســنده فذكرت أنه يف‬\n      ‫ســيارة نقــل األمــوال وبعــد إحضــار الســند أنكــروا اســتالمهم للكيــس‬\n      ‫الثامــن املذكــور وأنهــم فتحــوه ولــذا علــى املدعــي مطالبتــه املســؤولني‬\n      ‫عــن اخلزانــة وقــد بلغنــا الســلطات وكان املتعــن علــى ‪ ...‬مســؤول اخلزينــة‬\n      ‫أن ال يتــرك املوقــع حتــى يتحقــق منــه ولعلــه اســتولى علــى املبالــغ التــي‬\n\n\n‫‪315‬‬\n\f‫يف الكيــس الثامــن وتصــرف فيهــا ولذلــك ال أوافــق علــى طلــب املدعــي‬\n‫ألنــي لــم أفــرط وأنــا ســجني بســبب هــذه القضيــة مــدة أربــع ســنوات هــذه‬\n‫إجابتــي ثــم يف جلســة ثانيــة ســألت املدعــى عليــه عمــا ذكــره املدعــي مــن‬\n‫أن الشــركة التــي ميثلهــا ســلمت املبلــغ محــل الدعــوى لشــركة ‪ ...‬وهــل‬\n‫كان مؤمنــا عليــه مــن إحــدى شــركات التأمــن فقــال ال أعلــم عــن ذلــك‬\n‫شــيئا وأطلــب التأكــد مــن اجلهــة املختصــة أمــا املدعــي وكالــة فقــال‬\n‫لقــد حســم هــذا املبلــغ محــل الدعــوى مــن مســتحقاتنا التــي لــدى شــركة‬\n‫‪ ...‬وهنــاك بوليصــة تأمــن مــن الشــركة ‪ .....‬للتأمــن ‪ ....‬علــى األمــوال‬\n‫التــي ننقلهــا ولــم نســتلم مــن الشــركة املذكــورة شــيئا عــن املبلــغ محــل‬\n‫الدعــوى ألســباب تتعلــق بحجــم املطالبــة الســنوية التــي تضمــن بحدودهــا‬\n‫الشــركة املذكــورة هكــذا أفــاد الطرفــان ثــم يف جلســة ثالثــة ســألت‬\n‫املدعــي إن كانــت الشــركة التــي ميثلهــا قــد اســتلمت أي تعويــض مــن‬\n‫شــركة التأمــن عــن املبالــغ املختلســة فقــال لــم نســتلم أي تعويــض ال‬\n‫مــن شــركة التأمــن وال مــن غيرهــا ونطلــب احلكــم علــى املدعــى عليــه‬\n‫مكتفــن مبــا يف املعاملــة مــن بينــات وليــس لدينــا إضافــة هكــذا قــرر‬\n‫املدعــي وكالــة أمــا املدعــى عليــه فقــال أطلــب كــف املدعــي عنــي فأنــا‬\n‫ســجني مظلــوم ولــم أســرق أو اختلــس شــيئا هكــذا أجــاب املدعــى عليــه‬\n‫ثــم يف يــوم األربعــاء ‪1434 /3 /18‬ه ـ حضــر املدعــي وكالــه الســعودي‬\n‫بالســجل املدنــي رقــم بالوكالــة الصــادرة مــن كتابــة عــدل اخلبــر الثانيــة‬\n‫برقــم ‪ 35070‬يف ‪1432 /11 /4‬ه ـ جلــد ‪ 3000‬عــن ‪.....‬بصفتــه شــريك‬\n‫يف شــركة ‪ ...‬ملعــدات األمــن والســامة والتجــارة وبصفتــه وكيــا عــن‬\n‫شــريكه وحضــر حلضــوره املدعــى عليــه فتــم االطــاع ســعادة وكيــل‬\n‫أمــارة املنطقــة الشــرقية رقــم ‪ 28755‬يف ‪1433 /6 /14‬ه ـ ويتضمــن أن‬\n\n\n                                                                                    ‫‪316‬‬\n\f      ‫شــركة التأمــن لــم تعــوض الشــركة املدعيــة بــأي تعويــض ألنهــم لــم‬\n      ‫يتقدمــوا بــأي مطالبــة بهــذا الشــأن انتهــى وبتأمــل اوراق املعاملــة وجــد‬\n      ‫منهــا القــرار الصــادر مــن احملكمــة اجلزئيــة بالدمــام برقــم ‪ /3 /1‬يف‬\n      ‫‪1430 /1 /3‬ه ـ ومضمونــه احلكــم بتوجيــه التهمــة يف حــق املدعــى عليــه‬\n      ‫يف التفريــط بحفــظ األمانــة املوكلــة إليــه واالكتفــاء مبــا أمضــاه مــن‬\n      ‫مــدة إيقــاف بســبب هــذه القضيــة وهــي ســنتان وتســعة أشــهر وســبعه‬\n      ‫وعشــرون يومــا للحــق العــام وقــد قنــع املدعــى عليــه بهــذا احلكــم وكان‬\n      ‫ممــا جــاء يف احلكــم أن كاميــرات التصويــر يف اخلزانــة لــم ترصد ســوى‬\n      ‫ســبعة أكيــاس كمــا جــاء فيــه شــهادات للعاملــن تبــن اختــاف إفــادة‬\n      ‫املدعــى عليــه وزميليــه وبعــرض ذلــك علــى املدعــى عليــه قــال الظاهــر‬\n      ‫أن العاملــن يف اخلزينــة الرئيســية حرفــوا يف الكاميــرات لتوريطــي‬\n      ‫وأمــا اتهــام زميلــي لــي بســبب وعــد احملقــق لهمــا بإطــاق ســراحهما‬\n      ‫إذا شــهدا ضــدي فطلبــت مــن املدعــى عليــه تقــدمي بينــة علــى أنــه ســلم‬\n      ‫الكيــس الثامــن مبــا فيــه مــن مبالــغ مذكــورة يف الدعــوى إلــى اخلزينــة‬\n      ‫الرئيســية فقــال النظــام مينــع أن يدخــل معــي اخلزينــة أحــد حتــى زمالئــي‬\n      ‫بــل أدخــل أنــا قائــد الطاقــم ومعــي األمــوال واســلمها واســتلم وصــا بهــا‬\n      ‫وقــد ســلمت جميــع األكيــاس مبــا فيهــا الكيــس الثامــن ولــم يســلم‬\n      ‫لــي إال ســندا باســتالم ســبعة أكيــاس فقــط وليــس لــدي بينــة علــى‬\n      ‫ذلــك وبتأمــل مــا ســبق ضبطــه تبــن أن املدعــى عليــه أقــر مبــا جــاء يف‬\n      ‫الدعــوى مــن أنــه يعمــل يف شــركة ‪ ...‬وأنــه قائــد طقــم نقــل األمــوال‬\n      ‫وأنــه اســتلم ومعــه زميلــن لــه ثمانيــة أكيــاس نقــود مــن فــرع مصــرف‬\n      ‫‪ ...‬لتســليمها إلــى اخلزينــة الرئيســية وأنــه ســلم األكيــاس للقائمــن علــى‬\n      ‫اخلزينــة وأنهــم لــم يســلموه إال ســند اســتالم ســبعة أكيــاس كمــا أقــر‬\n\n\n‫‪317‬‬\n\f‫بــأن الكيــس الثامــن الــذي لــم يســتلم مــن القائمــن ســندا باســتالمه‬\n‫كان يحتــوي علــى ثالثــة ماليــن وثالثمائــة وخمســن ألــف ريــال وقــد‬\n‫قــرر املدعــى عليــه صراحــة أنــه اســتلم هــذا الكيــس مبــا فيــه مــن مبالــغ‬\n‫مــن مصــرف ‪ ...‬وســلمه للخزينــة الرئيســية ولــم يســتلم ســندا بذلــك وألن‬\n‫تصرفــه هــذا وهــو قائــد الطاقــم مخالــف ملــا جــرى عليــه العمــل يف عــدم‬\n‫تســليم النقــود ولــو كانــت قليلــة إال بســند اســتالم ولقــول النبــي صلــى‬\n‫اهلل عليــه وســلم ( علــى اليــد مــا أخــذت حتــى تؤديــه ) وألن املتعــن علــى‬\n‫املدعــى عليــه أن يســلم جميــع املبالــغ التــي اســتلمها إلــى مــن طلــب منــه‬\n‫تســليمها إليــه ويحصــل علــى مــا يثبــت ذلــك ولذلــك ثبــت لــدي بإقــرار‬\n‫املدعــى عليــه اســتالمه للكيــس الثامــن احملتــوي علــى ثالثــة ماليــن‬\n‫وثالثمائــة وخمســن ألــف ريــال مــن فــرع مصــرف ‪ ...‬ولــم يثبــت لــي أنــه‬\n‫ســلمه للخزينــة الرئيســية وحكمــت عليــه أن يســلم للشــركة املدعيــة‬\n‫ثالثــة ماليــن وثالثمائــة وخمســن ألــف ريــال وبعــرض احلكــم علــى‬\n‫الطرفــن قنــع بــه املدعــي واعتــرض عليــه املدعــى عليــه فأفهــم بأنــه‬\n‫سيســلم صــورة مــن احلكــم وميكــن مــن االعتــراض عليــه وان مــدة‬\n‫االعتــراض ثالثــون يومــا ســتبدأ بعــد تســلمه لصــورة احلكــم وأن عليــه‬\n‫أن يقــدم الئحتــه االعتراضيــة خــال تلــك املــدة وأنــه ان مضــت دون أن‬\n‫يقــدم الئحتــه االعتراضيــة فــإن حقــه يف االســتئناف والتمييــز يســقط‬\n‫ويصبــح احلكــم قطعيــا يف حقــه دون متييــز ففهــم ذلــك وصلــى اهلل علــى‬\n   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434 /03 /18‬ه ـ ‪.‬‬\n\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34343519‬وتاريــخ‬\n                                                ‫‪1434/1/11‬هـ‪.‬‬\n\n\n                                                                                     ‫‪318‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":313,"source_page_end":318,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0ae26d635d989bbace3448446b84a8c09dd9e16614d82da9f6e3dc840ad23d7b","normalized_text_hash":"cf68e21e379f55e8219f89406da83f17630f218a410e7618955bc4b375b29e9b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p313-34167155"},{"id":"dd89a9c7-84c8-507b-8aa0-438fff82826c","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مختلس -مطالبة برد مختلس -اختاس مبلغ مالي عن طريق خيانة األمانة -جواز وقف خدمات املدعى عليه لعدم احلضور للمحكمة -عدم قبول الرجوع عن اإلقرار بحق آلدمي -ثبوت","document_number":"34260802","case_number":"32385413","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/5","year":"1434","subject":"رد مختلس -مطالبة برد مختلس -اختاس مبلغ مالي عن طريق خيانة األمانة -جواز وقف خدمات املدعى عليه لعدم احلضور للمحكمة -عدم قبول الرجوع عن اإلقرار بحق آلدمي -ثبوت","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/7/5 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34260802 :‬‬\n                         ‫َر ْق ُم الدعوى‪32385413 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34307628‬تاريخه‪1434/8/28:‬هـ‬\n\n\n      ‫رد مختلــس ‪ -‬مطالبــة بــرد مختلــس‪ -‬اختــاس مبلــغ مالــي عــن طريــق‬\n      ‫خيانــة األمانــة ‪ -‬جــواز وقــف خدمــات املدعــى عليــه لعــدم احلضــور‬\n      ‫للمحكمــة ‪ -‬عــدم قبــول الرجــوع عــن اإلقــرار بحــق آلدمــي ‪ -‬ثبــوت‬\n                                                                    ‫الدعــوى ‪.‬‬\n\n\n\n      ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعد العدالة يف تســبيب‬\n                                                                          ‫حكمه ‪.‬‬\n\n\n\n      ‫ادعــى وكيــل املدعيــة بــأن املدعــى عليــه األول قــام بالتعــاون مــع الثانــي‬\n      ‫والثالــث باختــاس مبالــغ ماليــة من موكلته َّإبان عمله لديها كمندوب‬\n      ‫مبيعــات ؛ وطلــب إلزامهــم بدفــع املبالــغ املختلســة إلــى موكلتــه ‪ -‬أنكــر‬\n      ‫املدعــى عليهــم الدعــوى جملــة وتفصيــا ‪ -‬إال أن املدعــى عليــه األول لــه‬\n      ‫إقــرار بثبــوت املبلــغ املدعــى بــه يف ذمتــه وقــد أقــر بصــدوره منــه إال أنــه‬\n      ‫رجــع عنــه أمــام احملكمــة بدعــوى اإلكــراه ‪ -‬قضــت احملكمــة بإلــزام‬\n      ‫املدعــى عليــه األول بتســليم املدعيــة املبلــغ املدعــى بــه وصرفــت النظــر‬\n      ‫عــن باقــي طلبــات املدعيــة ‪ -‬قنعــت املدعيــة واملدعــى عليهمــا الثانــي‬\n      ‫والثالــث باحلكــم وعــارض عليــه املدعــى عليــه األول ‪ -‬قــررت محكمــة‬\n                                                  ‫االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n‫‪319‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضي يف احملكمــة العامة مبحافظة‬\n‫جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫مبحافظة جدة‪ ... /‬املساعد برقم ‪ 32385413‬وتاريخ ‪1432/08/30‬هـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 321104744‬وتاريــخ ‪1432/08/25‬ه ـ ففــي‬\n‫يــوم االثنــن ‪1433/11/08‬ه ـ افتتحــت اجللســة يف الســاعة احلادية عشــرة‬\n‫والنصــف وفيهــا حضــر‪ ........./‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪.....‬بصفتــه وكيــا عــن ‪ ...‬بصــك الوكالــة ذي الرقــم ‪61968‬‬\n‫والتاريــخ ‪1432/07/05‬ه ـ اجللــد ‪10811‬الصــادر مــن كتابــة العــدل‬\n‫الثانيــة شــمال محافظــة جــدة كمــا حضــر حلضــوره ‪.....‬مصــري اجلنســية‬\n‫مســلم الديانــة مبوجــب رخصــة اإلقامــة رقــم‪ .....‬كمــا حضــر ‪.....‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم‪ .....‬بصفتــه وكيــا عــن‪ .....‬بصــك‬\n‫الوكالــة ذي الرقــم ‪ 33359134‬والتاريــخ ‪1433/11/08‬ه ـ الصادر من‬\n‫كتابــة العــدل الثانيــة شــمال محافظــة جــدة كمــا حضــر ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم وقــد حــرر املدعــي دعــواه وقدمهــا‬\n‫مــن ثــاث ورقــات وهــي حتتــاج إلــى رصــد وأرفقــت باملعاملــة وبعرضــه‬\n‫علــى املدعــى عليهــم أجابــوا قائلــن نطلــب اإلمهــال إلحضــار إجابتنــا لــذا‬\n‫أجيبــوا لطلبهــم وأمهلــوا واختتمــت اجللســة ثــم يف يــوم األحــد‬\n‫‪1433/12/26‬ه ـ افتتحــت اجللســة يف الســاعة التاســعة والربــع فيهــا‬\n‫حضــر املدعــي وكالــة املثبتــة هويتــه ووكالتــه كمــا حضــر حلضــوره‬\n‫املدعــى عليــه أصالــة املثبتــة هويتــه ســابقا كمــا حضــر ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم بصفتــه وكيــا عــن بصــك الوكالــة ذي‬\n\n                                                                                        ‫‪320‬‬\n\f      ‫الرقــم ‪ 33356766‬والتاريــخ ‪1433/11/03‬ه ـ الصــادر مــن كتابــة‬\n      ‫العــدل الثانيــة شــمال محافظــة جــدة ولــم يحضــر املدعــى عليــه الثانــي‬\n      ‫ونــص دعــوى املدعــي ‪ ( :‬اقــدم دعــواي هــذه ضــد التاليــة أســماءهم‬\n      ‫مجتمعــن ومنفرديــن وهــم ‪ /1:‬املدعــى عليــه األول ‪ /2‬املدعــى عليــه‬\n      ‫الثانــي ‪ /3‬املدعــى عليــه الثالــث وموضــوع الدعــوى بتفصيــل مــا يلــي ‪:‬‬\n      ‫ســبق وان عمــل املدعــى عليــه األول ‪ ....‬لــدى مؤسســة موكلــي مطابــع ‪....‬‬\n      ‫احلديثــة مبهنــة منــدوب مبيعــات بتاريــخ ‪2003/1/1‬م براتــب شــهري‬\n      ‫وقــدره ‪ 3000‬ريــال وعمولــة وتنحصــر مهامــه الوظيفيــة يف مقابلــة‬\n      ‫العمــاء باخلــارج ويقــوم بإحضــار الطلبيــات منهــم والقيــام مبتابعتهــا‬\n      ‫وبتنفيذهــا داخــل املطبعــة وتســليمها لهــم واســتالم املبالــغ املاليــة مقابــل‬\n      ‫العمليــات املنفــذة إن كانــت نقــد ًا أو بشــيكات ويقــوم بتوريــد املبالــغ‬\n      ‫احملصلــة أو ًال بــأول إلــى قســم احلســابات باملطبعــة إال انــه يف الفتــرة‬\n      ‫األخيــرة و التــي تبــدأ مــن النصــف األول مــن عــام ‪2011‬م لــم يقــم‬\n      ‫باالنتظــام يف ســداد الفواتيــر احملصلــة مــن العمــاء األمــر الــذي ترتــب‬\n      ‫عليــه عجــوزات يف حســاب عمالئــه وتراكمــت ديــون الزبائــن املنضويــة‬\n      ‫حتــت مســئوليته حيــث ال يوجــد ســداد للفواتيــر التــي ســلمها والتــي مــر‬\n      ‫عليهــا مــدد طويلــة حتــى بلغــت إجمالــي املديونيــة علــى زبائــن املذكــور‬\n      ‫‪ 1198150‬ريــال ( مليــون ومائــة وثمانيــة وتســعون ألــف ومائــة وخمســون‬\n      ‫ريــال ) منهــا ‪ 70570‬ريــال علــى الســادة ‪ /‬البنــك ‪ ...‬وقــد صــدر بذلــك‬\n      ‫تقريــر احملاســب القانونــي محاســبون قانونيــون( مرفــق لفضيلتكــم‬\n      ‫تقريــر احملاســب القانونــي بالفواتيــر واملســتندات وبالبحــث والتحــري‬\n      ‫اكتشــفت إدارة املطبعــة أن املذكــور اخــل بــكل الواجبــات والقيــم‬\n      ‫املطلــوب توافرهــا يف كل مســلم يراعــي ربــه ودينــه حيــث قــام باالتــي ‪:‬‬\n\n\n‫‪321‬‬\n\f‫‪ /1‬اســتالم فواتيــر البيــع املوجهــة مــن املطبعــة للزبائــن واســتالم‬\n‫املطبوعــات لتســلمها ‪ /2 .‬عمــل فواتيــر مطبوعــات مــن مؤسســة كفيلــه‬\n‫املدعــى عليــه الثانــي تقابــل نفــس فواتيــر مطبعتنــا وتســليمها للزبــون‬\n‫بــد ًال مــن فواتيــر ‪ /3 ....‬االتفــاق مــع املدعــى عليــه الثالــث علــى اســتالم‬\n‫املطبوعــات يف مــكان يقــع مبنطقــة الشــرفية بجــدة حيــث يتولــى‬\n‫تســليمها للعمــاء مــع الفواتيــر الغيــر حقيقيــة املســتبدلة بفواتيــر املدعــى‬\n‫عليــه الثانــي‪ /4 .‬اســتالم قيمــة املطبوعــات مــن الزبائــن وعــدم توريدهــا‬\n‫حلســابات املطبعــة ‪ /5 .‬ســداد بعــض دفعــات نقديــة صغيــرة للتمويــه بــأن‬\n‫هنالــك ســداد مــن بعــض الزبائــن ‪ .‬وقــد واجهنــا املدعــى عليــه الثالــث‬\n‫الــذي اقــر بــكل التفاصيــل أمــام شــرطة الكنــدرة مبوجــب احملضــر‬\n‫الرســمي املرفــق باملعاملــة‪ .‬وعلــى الفــور قمنــا باالتصــال علــى املدعــى‬\n‫عليــه الثانــي وحضــر إلــى املطبعــة ومعــه املدعــى عليــه األول وتعهــد بــأن‬\n‫ينهي هذا املوضوع على مســئوليته بشــهادة احلاضرين الســيد ‪ /‬والســيد‬\n‫‪ /‬ووعــد بحــل املوضــوع وكنــا ال نعلــم حقيقــة التعــاون بــن االثنــن ثــم‬\n‫فوجئنــا يف اليــوم الثانــي مــن حضــور الكفيــل والتزامــه بأنــه قــد قــام‬\n‫بعمــل خــروج وعــودة للمذكــور وســاعده بالهــرب حيــث انهــى كل‬\n‫متعلقاتــه الشــخصية يف ســاعات قليلــة لنكشــف ان املدعــى عليــه االول‬\n‫اخلــى ســكنه وســافر الــى مصــر بعــد ان اســتولى علــى امــوال املطبعــة‪.‬‬\n‫وبعــد اكتشــافنا لهــرب املنــدوب قمنــا مبقابلــة املســئولني بالبنــك ‪...‬‬\n‫ملراجعــة حســابنا معهــم فاقــروا بعــدم اســتالمهم ألي فواتيــر بيــع تخــص‬\n‫مطابــع ‪ ...‬وامنــا كانــت الفواتيــر علــى مطبوعــات مؤسســة ‪ ...‬واطلعنــا‬\n‫املســئولني يف البنــك ‪ ...‬علــى عينــات مــن املطبوعــات التــي متــت مبطابعنــا‬\n‫فاكــدوا انهــا نفــس املطبوعــات التــي مت اســتالمها مــن مؤسســة ‪...‬‬\n\n\n                                                                                        ‫‪322‬‬\n\f      ‫والعائــدة ملكيتهــا للمدعــى عليــه الثانــي‪ .‬وحتــى نقطــع الشــك باليقــن‬\n      ‫وللتأكــد مــن ســامة ارصــدة باقــي الزبائــن بدفاترنــا ارســلنا مندوبينــا‬\n      ‫بخطابــات لزبائــن املدعــى عليــه االول للحصــول منهــم علــى مصادقــات‬\n      ‫بصحــة االرصــدة فلــم جنــد ملطابــع ‪ ...‬لدى بعضهم اثر محاســبي واخرون‬\n      ‫افــادوا بســداد مــا عليهــم للمنــدوب ‪ ...‬الهــارب‪ .‬واالن البينــة الصحيحــة‬\n      ‫القاطعــة احلاســمة يف هــذه املطالبــة العادلــة هــي اقــرار املدعــى عليــه‬\n      ‫االول ‪ ...‬بــأن ملوكلــي بذمتــه كامــل املبلــغ املطالــب بــه ‪ 1198150‬ريــال‬\n      ‫مبوجــب اقــراره املرفــق ‪ ،‬ملــا تقــدم اطلــب‪ :‬احلكــم بالــزام املدعــى عليهــم‬\n      ‫الثالثــة مجتمعــن او منفرديــن بدفــع كامــل املبالــغ الــوارد بتقديــر‬\n      ‫احملاســب القانونــي مبليــون ومئــة وثمانيــة وتســعون الــف ومائــة وخمســون‬\n      ‫ريــال احلكــم بإلــزام املدعــى عليهــم الثالثــة بدفــع قيمــة االضــرار املاديــة‬\n      ‫جــراء هــذه القضيــة احالــة املدعــى عليهــم الثالثــة للمدعــي العــام لينالــوا‬\n      ‫عقابهــم الشــرعي جــراء هــذه اجلرميــة ) ا‪.‬ه ـ نقــل نصــا وبســؤال املدعــى‬\n      ‫عليــه ‪ ....‬وكالــة اإلجابــة أجــاب قائــا مــا ذكــره املدعــي وكالــة غيــر‬\n      ‫صحيــح جملــة وتفصيــا وموكلــي يعمــل ناقــا للبضاعــة فقــط وال‬\n      ‫عالقــة لــه بالفواتيــر وأطلــب رد دعــواه وإخــاء ســبيل موكلــي مــن هــذه‬\n      ‫الدعــوى هكــذا أجــاب وقــد قــدم وكيــل املدعــى عليــه األول مذكــرة‬\n      ‫وأرفقــت باملعاملــة ورصــد مضمونهــا وبســؤال املدعــى عليــه الثالــث‬\n      ‫اإلجابــة أجــاب قائــا مــا ذكــره املدعــي غيــر صحيــح جملــة وتفصيــا‬\n      ‫وأطلــب رد دعــواه وإخــاء ســبيل موكلــي مــن هــذه الدعــوى هكــذا‬\n      ‫أجــاب وقــدم املدعــى عليــه الثالــث مذكــرة وأرفقــت باملعاملــة ورصــد‬\n      ‫مضمونهــا والنتهــاء وقــت اجللســة رفعــت اجللســة واختتمــت اجللســة ثــم يف‬\n      ‫يــوم الثالثــاء ‪1434/02/05‬ه ـ افتتحــت اجللســة يف الســاعة العاشــرة‬\n\n\n‫‪323‬‬\n\f‫والربــع فيهــا حضــر املدعــي وكالــة املثبتــة هويتــه ووكالتــه كمــا‬\n‫حضــر حلضــوره املدعــى عليــه أصالــة املثبتــة هويتــه ســابقا كمــا حضــر‬\n‫املدعــى عليــه وكالــة ‪ ...‬املثبتــة هويتــه ووكالتــه ســابقا كمــا حضــر‬\n‫مصــري اجلنســية مســلم الديانــة مبوجــب رخصــة اإلقامــة رقــم وبســؤال‬\n‫املدعــى عليــه الثانــي عــن دعــوى املدعــي أجــاب قائــا إجابتــي مكتوبــة‬\n‫علــى ذاكــرة إلكترونيــة أطلــب رصــد نصهــا لــذا أجيــب لطلبــه ونصهــا‪:‬‬\n‫(نفيــد فضيلتكــم بــأن مــا أدعــت بــه املدعيــة مطابــع ‪ ...‬ليــس بصحيــح‬\n‫والصحيــح اآلتــي ذكــره ‪ -:‬أو ًال ‪ :‬أن موكلــي يف األصــل ليــس علــى‬\n‫كفالــة املدعيــة وأن تعاملــه كان مــن خــال اتفــاق شــفهي بــأن يكــون‬\n‫مندوب ـ ًا عــن املدعيــة لبعــض عمالئهــا وذلــك بعلــم وموافقــة كفيلــه ‪.‬‬\n‫ثاني ـ ًا ‪ :‬أن عمــل موكلــي كان ينحصــر يف إحضــار أوامــر التنفيــذ‬\n‫خلمســة عمــاء علــى ســبيل احلصــر وهــم البنــك ‪ ...‬وبنــك ‪ ...‬وشــركة‪)...‬‬\n‫وشــركة ‪ ...‬لألدويــة وشــركة ‪ ...‬ويتــم تســليمها للمدعيــة وأمــا عــن‬\n‫طريقــة الســداد فيتــم إمــا عــن طريــق حتويــل مــن حســاب العميــل بنــك ‪...‬‬\n‫وبنــك ‪ ...‬إلــى حســاب املدعيــة وأمــا باقــي العمــاء عــن طريــق شــيكات‬\n‫محــررة باســم املدعيــة ولــم يكــن هنــاك اســتالم مبالــغ نقديــة اســتلمها‬\n‫موكلــي ‪ ،‬إلــى أن تــرك موكلــي العمــل‪ .‬ثالث ـ ًا ‪ :‬لقــد قــام موكلــي‬\n‫مبراجعــة العمــاء املذكوريــن لالستفســار عــن أي مديونيــات متأخــرة‬\n‫للمدعيــة وذلــك فيمــا يتعلــق باألوامــر املنفــذة خــال فتــرة عمــل موكلــي‬\n‫يف ذلــك الوقــت فأفــادوا بــأن املدعيــة قــد اســتلمت جميــع مســتحقاتها (‬\n‫مرفــق بيــان للبنــك ‪ ) ...‬وبعــض العمــاء كبنــك ‪ ...‬الزالــوا يف اســتمرارية‬\n‫التعامــل مــع املدعيــة مــن خــال مندوبهــا ويدعــى ‪ /‬مصــري اجلنســية (‬\n‫مرفــق ) ولفضيلتكــم مخاطبتهــم للتأكــد من صحة ذلك أو إحضارهم‬\n\n\n                                                                                   ‫‪324‬‬\n\f      ‫لســماع أقوالهــم مبــا يؤكــد بــراءة ذمــة موكلــي فيمــا يتعلــق باألوامــر‬\n      ‫املنفــذة خــال فتــرة عملــه‪ .‬رابع ـ ًا ‪ :‬عندمــا تــرك موكلــي العمــل لــدى‬\n      ‫املدعيــة قــام بالعمــل لــدى كفيلــه صاحــب مؤسســة ‪ ....‬ألدوات الدعايــة‬\n      ‫واإلعــان والتــي مــن خاللهــا مت التعامــل مــع بنــك ‪ ...‬يف أمــور فنيــة‬\n      ‫وبأوامــر مســتقلة ليــس لهــا عالقــة مبطابــع املدعيــة ولفضيلتكــم‬\n      ‫مخاطبــة البنــك ‪ ....‬للتأكــد مــن أن البنــك ‪ ...‬يتعامــل مــع جميــع املطابــع‬\n      ‫وشــركات الدعايــة واإلعــان دون حكــر علــى أحــد الشــركات ومــن‬\n      ‫ضمنهــا تعاملهــا مــع مؤسســة كفيلــي ‪ ....‬للدعايــة واإلعــان‪ .‬خامس ـ ًا ‪:‬‬\n      ‫اإلقــرار املذيــل بتوقيــع موكلــي ال ميثــل حقيقــة التعامــل وذلــك إلرغامــه‬\n      ‫وإكراهــه بكتابتــه وتوقيعــه مــن قبــل املدعيــة مبقرهــا ( مطابــع ‪...‬‬\n      ‫احلديثــة ) والدليــل علــى ذلــك مــا ذكــر يف مــن اإلقــرار بــأن مــدة عملــه‬\n      ‫عشــرة ســنني والصحيــح ثمانيــة أعــوام كمــا أن طبيعــة عمــل موكلــي‬\n      ‫إحضــار أوامــر تنفيــذ وليــس بيــع وحتصيــل كمــا هــو مذكــور يف‬\n      ‫اإلقــرار كمــا أن املبلــغ املذكــور يف اإلقــرار هــو مــن صنــع املدعيــة ألن‬\n      ‫جميــع املبالــغ املســتحقة للمدعيــة للعمــاء املذكوريــن قــد مت ســدادها‬\n      ‫كمــا أن التاريــخ املذكــور يف اإلقــرار يف ‪1423/9/5‬ه ـ أي منــذ مــا‬\n      ‫يقــارب عشــرة أعــوام أي قبــل تعامــل موكلــي مــع املدعيــة بعامــن تقريبـ ًا‬\n      ‫وهــذه املعلومــات املغلوطــة دليــل قاطــع علــى عــدم صحتــه سادس ـ ًا ‪:‬‬\n      ‫ذكــرت املدعيــة يف دعواهــا بــأن ‪ ....‬للتنميــة قــد حــول علــى حســاب‬\n      ‫مؤسســة كفيــل موكلــي مبلــغ وقــدره ‪ 750000‬ريــال يف عــام ‪ 2011‬م‬\n      ‫وهــذا ليــس بصحيــح حيــث أن التعامــل الفعلــي الــذي مت بــن مؤسســة‬\n      ‫كفيــل موكلــي والبنــك ‪ ...‬لعــام ‪2011‬م مبلــغ وقــدره ‪ 200000‬ريــال‬\n      ‫لعمــل لوحــات ومطبوعــات ليســت لهــا عالقــة مبطابــع املدعيــة ( مرفــق )‪.‬‬\n\n\n‫‪325‬‬\n\f‫ســابع ًا ‪ :‬نــود أن نوضــح لفضيلتكــم مــا ذكرتــه املدعيــة يف دعواهــا بــأن‬\n‫كفيــل موكلــي قــد هــرب موكلــي بتأشــيرة خــروج وعــودة وســاعده‬\n‫بالهــرب بعــد أن أنهــى كل متعلقاتــه الشــخصية يف ســاعات قليلــة وبــأن‬\n‫موكلــي قــد أخلــى ســكنه وســافر إلــى مصــر بعــد أن اســتولى علــى‬\n‫أمــوال املطبعــة وهــذا ليــس بصحيــح حيــث أن موكلــي قــد تــرك تعاملــه‬\n‫مــع املدعيــة بتاريــخ ‪ 2011/4/1‬م وســافر إلــى مصــر بتاريــخ‬\n‫‪2011/5/25‬م ثــم عــاد إلــى اململكــة بتاريــخ ‪2011/10/1‬م مبــا يؤكــد‬\n‫إخــاء طرفــه مــن املدعيــة وبأنــه لــم يكــن لديــه نيــة الهــروب كمــا‬\n‫زعمــت بــه املدعيــة‪ .‬ثامن ـ ًا ‪ :‬قامــت شــرطة الكنــدرة بإيقــاف خدمــات‬\n‫موكلــي وخدمــات كفيلــه املدعــى عليــه الثانــي يف هــذه الدعــوى ‪...‬‬\n‫والــذي ليــس لــه عالقــة مبوضــوع املطالبــة واملدعــى عليــه الثالــث ‪-‬‬\n‫مصــري اجلنســية ‪ -‬الــذي ليــس علــى كفالــة املدعيــة‪ .‬وبســؤال موكلــي‬\n‫شــرطة الكنــدرة عــن ســبب إيقــاف خدماتهــم أفــادوا بــأن هــذا اإلجــراء‬\n‫ـاء علــى أمــر القاضــي ‪ .‬وحيــث ال يخفــى علــى فضيلتكــم بــأن هــذا‬       ‫بنـ ً‬\n‫اإلجــراء الــذي مت مــن قبــل شــرطة الكنــدرة إذا لــم يكــن بأمــر‬\n‫فضيلتكــم يعــد إجــراء باطــل حيــث أن هذا اإلجراء ليس من اختصاص‬\n‫اجلهــات التنفيذيــة إذا كانــت املطالبــة متعلقــة بحقــوق ماليــة عليهــا نــزاع‬\n‫فتختــص بــه احملاكــم العامــة صاحبــة الواليــة العامــة يف نظــر هــذه‬\n‫القضايــا وفقــا ملقتضــى نــص (املــادة ‪ )32‬مــن نظــام املرافعــات الشــرعية‬\n‫ومــن صالحيــات قاضــي املوضــوع إذا لــم يجــد جتــاوب مــن حضــور‬\n‫املدعــى عليــه فللقاضــي أن يأمــر بوقــف خدماتــه أو بإحضــاره بالقــوة‬\n‫اجلبريــة أو مبنعــه مــن الســفر وحيــث أن إيقــاف خدمــات موكلــي‬\n‫وكفيلــه واملدعــو قــد ترتــب عليــه أضــرار مــن تعطيــل ملصاحلهــم‬\n\n\n                                                                                      ‫‪326‬‬\n\f      ‫الضروريــة مــع اجلهــات احلكوميــة ويف هــذا ضــرر وحيــث ال يخفــى علــى‬\n      ‫فضيلتكــم بــأن ديننــا احلنيــف قــد نهــى عــن الضــرر لقولــه صلــى اهلل‬\n      ‫عليــه وســلم ‪ ( :‬ال ضــرر وال ضــرار ) ومنهــا القاعــدة الشــرعية ( الضــرر‬\n      ‫يــزال ) وملــا ذكــر يتضــح لفضيلتكــم كيديــة دعــوى املدعيــة‪ .‬لــذا‬\n      ‫أطلــب مــن فضيلتكــم اآلتــي ‪ /1 - :‬مخاطبــة شــرطة الكنــدرة برفــع‬\n      ‫اإليقــاف عــن خدمــات موكلــي ورفقــاؤه ‪ /2 .‬رد دعــوى املدعيــة مــع‬\n      ‫إلزامهــا بدفــع أتعــاب محامــاة مبلــغ وقــدره ‪ 30000‬ريــال‪ .‬مــع تعزيــر‬\n      ‫املدعيــة وفق ـ ًا ملــا ورد يف الالئحــة التنفيذيــة لنظــام املرافعــات الشــرعية‬\n      ‫للمــادة (‪)4‬الفقــرة اخلامســة « إذا ثبــت لناظــر القضيــة أن دعــوى املدعــي‬\n      ‫كيديــة حكــم بــرد الدعــوى ولــه احلكــم بتعزيــر املدعــي مبــا يردعــه «‬\n      ‫) ا‪.‬ه ـ نقــل نصــا وبســؤال املدعــي عــن هــذه الدعــوى أجــاب قائــا أنا على‬\n      ‫مــا ذكرتــه هكــذا أجــاب وبســؤال املدعــي وكالــة البينــة علــى دعــواه‬\n      ‫أجــاب قائــا إن املدعــى عليــه ‪ ...‬ملــا قبــض عليــه أقر يف محاضر الشــرطة‬\n      ‫بأنــه اســتلم مــن البضاعــة مــن املدعــي عليــه وهــذه البضاعــة ملوكلــي‬\n      ‫كمــا أن املدعــى عليــه ‪ ...‬قــد وقــع علــى إقــرار بــأن يف ذمتــه ملوكلــي (‬\n      ‫‪) 1198150‬مليونــا ومائــة وثمانيــة وتســعني ألفــا ومائــة وخمســن ريــال‬\n      ‫وأمــا املدعــى عليــه الثالــث ‪ ...‬فقــد ذكــر بــأن األمــوال كانــت تدخــل يف‬\n      ‫حســابه هكــذا أجــاب وبســؤال املدعــي وكالــة عــن ذلــك أجــاب قائــا‬\n      ‫مــا ذكــره املدعــي مــن أن موكلــي قــد اســتلم البضاعــة مــن فصحيــح‬\n      ‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليــه ‪ ...‬أجــاب قائــا صحيــح‬\n      ‫مــا ذكــره املدعــي وكالــة مــن أنــي وقعــت علــى اإلقــرار ولكنــي وقعــت‬\n      ‫علــى اإلقــرار مكرهــا هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليــه‬\n      ‫الثالــث أجــاب قائــا مــا ذكــره املدعــي وكالــة فغيــر صحيــح هكــذا‬\n\n\n‫‪327‬‬\n\f‫أجــاب والنتهــاء وقــت اجللســة رفعــت اجللســة واختتمــت اجللســة ثــم يف يــوم‬\n‫الســبت ‪1434/06/24‬ه ـ افتتحــت اجللســة يف الســاعة التاســعة وفيهــا‬\n‫حضــر املدعــي وكالــة املثبتــة هويتــه ووكالتــه كمــا حضــر حلضــوره‬\n‫املدعــى عليــه أصالــة ‪ ...‬املثبتــة هويتــه ســابقا واملدعــى عليــه وكالــة ‪...‬‬\n‫املثبتــة هويتــه ووكالتــه ســابقا وبســؤال املدعــى عليــه ‪ ...‬عــن توقيعــه‬\n‫علــى اإلقــرار باإلكــراه أجــاب قائــا أنــا قــد ذهبــت إلــى املطبعــة وكان‬\n‫موجــودا املدعــي ‪ ...‬وشــخص آخــر وقالــوا ال بــد لــي مــن التوقيــع علــى‬\n‫اإلكــراه وأجبرونــي هكــذا أجــاب وبســؤال املدعــى عليــه ‪ ......‬مــن‬\n‫بينتــه علــى اإلكــراه أجــاب قائــا ال بينــة لــي إال موكلــي املدعــى عليــه‬\n‫يف هــذه الدعــوى هكــذا أجــاب ورفعــت اجللســة للتأمل واختتمت اجللســة‬\n‫ثــم يف يــوم األربعــاء ‪1434/07/05‬ه ـ افتتحت اجللســة يف الســاعة الثامنة‬\n‫وفيهــا حضــر املدعــي وكالــة املثبتــة هويتــه ووكالتــه كمــا حضــر‬\n‫حلضــوره املدعــى عليــه أصالــة املثبتــة هويتــه ســابقا كمــا حضــر املدعــى‬\n‫عليــه أصالــة املثبتــة هويتــه ســابقا كمــا حضــر ‪ ....‬بصفتــه وكيــا عــن‬\n‫بصــك الوكالــة ذي الرقــم ‪ 33356766‬والتاريــخ ‪1433/11/03‬ه ـ‬\n‫الصــادر مــن كتابــة العــدل الثانيــة بشــمال محافظــة جــدة وللمدعــي‬\n‫وكالــة يف الوكالــة حــق املرافعــة واملدافعــة وحضــور اجللســات وطلــب‬\n‫وتقــدمي البينــات واســتئناف األحــكام ومتييزهــا واالعتــراض عليهــا‬\n‫ولوكيــل املدعــى عليــه ‪ ...‬يف الوكالــة حــق املرافعــة واملدافعة واإلنكار‬\n‫واإلقــرار والصلــح والتنــازل وبعــد االطــاع علــى املعاملــة وجــد بهــا إقــرار‬\n‫املدعــى عليــه علــى لفــة رقــم‪ )81( :‬واملتضمــن أن املدعــى عليــه ‪ ...‬يذكــر‬\n‫أن يف ذمتــه مبلغــا وقــدره ‪ 1198150‬مليــون ومائــة وثمانيــة وتســعون ألفــا‬\n‫ومائــة وخمســون ريــاال وأنــه ســوف يقــوم بســدادها علــى دفعــات حتــى‬\n\n\n                                                                                      ‫‪328‬‬\n\f      ‫انتهــاء املبلــغ ا‪.‬ه ـ فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي واملتضمنــة‬\n      ‫طلــب املدعــي إلــزام املدعــى عليهــم الثالثــة مجتمعــن أو منفرديــن بدفــع‬\n      ‫مبلــغ وقــدره ‪ 1198150‬مليــون ومائــة وثمانيــة وتســعون ألفــا ومائــة‬\n      ‫وخمســون ريــاال ملوكلــه وإلــزام املدعــى عليهــم بدفــع قيمــة األضــرار‬\n      ‫املاديــة وإحالتهــم إلــى جهــات التحقيــق وبنــاء علــى إجابــة املدعــى عليهــم‬\n      ‫واملتضمنــة اإلنــكار وبنــاء علــى إقــرار املدعــى عليــه املرفــق باملعاملــة‬\n      ‫علــى لفــة رقــم‪ )81( :‬ومصادقتــه علــى اإلقــرار وعليــه فقــد ظهــر لــي مــا‬\n      ‫يلــي‪ :‬أوال‪ :‬ثبــوت مبلــغ وقــدره ‪ 1198150‬مليــون ومائــة وخمســون ريــاال‬\n      ‫يف ذمــة املدعــى عليــه األول للمدعــي ثانيــا‪ :‬عــدم ثبــوت مطالبــة املدعــي‬\n      ‫للمدعــى عليهــم الباقــن ثالثــا‪ :‬صــرف النظــر عــن الطلبــات الباقيــة‬\n      ‫رابعــا‪ :‬فقــد ألزمــت املدعــى عليــه بدفــع مبلــغ وقــدره‪ 1198150‬مليــون‬\n      ‫ومائــة وخمســون ريــاال للمدعــي وبــه حكمــت وبإعــان احلكــم اعتــرض‬\n      ‫املدعــى عليــه األول ‪......‬وقنــع البقيــة وأفهــم بــأن عليــه مراجعــة احملكمــة‬\n      ‫يــوم الســبت ‪1434/07/08‬ه ـ الســتالم نســخة احلكــم لتقــدمي الئحتــه‬\n      ‫االعتراضيــة وإذا فــات علــى ميعــاد االعتــراض ثالثــون يومــا ولــم يقــدم‬\n      ‫الئحتــه االعتراضيــة ســقط حقــه يف االعتــراض واكتســب احلكــم‬\n      ‫القطعيــة‪ ،‬واختتمــت اجللســة يف الســاعة الثامنــة والنصــف‪ ،‬وبــاهلل‬\n      ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                                  ‫يف ‪1434/07/05‬هـ‬\n      ‫احلمــد هلل وحــده بعــد ففــي يــوم الســبت ‪1434/07/08‬ه ـ افتتحــت‬\n      ‫اجللســة يف الســاعة الثانيــة والنصــف وفيهــا حضــر املدعــى عليــه أصالــة‬\n      ‫‪ ...‬املثبتــة هويتــه ســابقا واســتلم نســخة احلكــم وأفهــم بتعليمــات التمييــز‬\n      ‫كمــا يف اجللســة املاضيــة فتفهــم ذلــك‪ ،‬واختتمــت اجللســة ثــم يف يــوم‬\n\n\n‫‪329‬‬\n\f‫الثالثــاء ‪1434/08/02‬ه ـ افتتحــت اجللســة يف الســاعة الثانيــة والنصــف‬\n‫وفيهــا حضــر املدعــى عليــه أصالــة ‪ ...‬املثبتــة هويتــه ســابقا وقــدم‬\n‫الئحتــه االعتراضيــة املقيــدة يف احملكمــة برقــم ‪ 341870383‬وتاريــخ‬\n‫‪1434/08/02‬ه ـ واملكونــة مــن ثــاث ورقــات مبرفقاتهــا ورفعــت‬\n‫اجللســة لدراســتها ثــم يف يــوم األحــد ‪1434/08/07‬ه ـ افتتحــت اجللســة‬\n‫يف الســاعة الواحــدة والربــع وقــد مت االطــاع علــى الالئحــة االعتراضيــة‬\n‫املقدمــة مــن املدعــى عليــه املذكــور رقــم قيدهــا وتاريخــه أعــاه ولــم‬\n‫أجــد بهــا مــا يؤثــر علــى مــا حكمــت بــه لــذا قــررت رفعهــا مــع كامــل‬\n‫املعاملــة والصــك وصــورة مصدقــة مــن الضبــط بعــد إحلــاق مــا اســتجد‬\n‫علــى الصــك والســجل حملكمــة االســتئناف‪ ،‬واختتمــت اجللســة يف‬\n‫الســاعة الواحــدة والنصــف‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/08/07‬ه ـ‬\n‫احلمــد هلل وحــده‪ ،‬وبعــد‪ :‬ففــي يــوم األربعــاء ‪1434/10/07‬ه ـ افتتحــت‬\n‫اجللســة يف الســاعة الثامنــة وقــد عــادت املعاملــة مــن محكمة االســتئناف‬\n‫بالرقــم املقيــد يف احملكمــة ‪ 33996387‬وتاريــخ ‪1434/09/15‬ه ـ‬\n‫وبرفقهــا خطــاب فضيلــة رئيــس محكمــة االســتئناف مبنطقــة مكــة‬\n‫املكرمــة املكلــف ذو الرقــم ‪ 33996387‬والتاريــخ ‪1434/09/10‬ه ـ‬\n‫واملتضمــن‪ (:‬نفيدكــم أنــه جــرى تدقيــق احلكــم مــن الدائــرة احلقوقيــة‬\n‫السادســة وصــدر بشــأنه القــرار املرفــق ذو الرقــم ‪ 34307628‬والتاريــخ‬\n‫‪1434/08/28‬ه ـ املــدون علــى ظهــر الصــك نبعثــه لكــم مــع كامــل‬\n‫مشــفوعات املعاملــة إلكمــال الــازم واهلل يحفظكــم‪ .‬والســام‬\n‫عليكــم ورحمــة اهلل وبركاته)ا‪.‬ه ـ كمــا برفقهــا قــرار تصديــق رقــم‬\n‫‪ 34307628‬وتاريــخ ‪1434/08/28‬ه ـ ونصــه‪ (:‬احلمــد هلل‪ ،‬والصــاة‬\n\n\n                                                                                  ‫‪330‬‬\n\f      ‫والســام علــى رســول اهلل‪ ،‬وبعــد‪ :‬فقــد جــرى منــا نحــن رئيــس وأعضــاء‬\n      ‫الدائــرة احلقوقيــة السادســة يف محكمــة االســتئناف مبنطقــة مكــة‬\n      ‫املكرمــة االطــاع علــى هــذا احلكــم الصــادر مــن فضيلــة الشــيخ‪/‬‬\n      ‫القاضــي باحملكمــة العامــة مبحافظــة جدة واملســجل بعــدد ‪34260802‬‬\n      ‫وتاريــخ ‪1434/07/05‬ه ـ املتضمــن دعــوى ‪ ....‬ضــد ‪ ...‬مصــري اجلنســية‬\n      ‫و‪......‬مصــري اجلنســية واحملكــوم فيــه مبــا دون باطــن الصــك‪ ،‬وبدراســة‬\n      ‫احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى‬\n      ‫احلكــم‪ ،‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم‪ ،،،،‬قاضــي اســتئناف توقيعــه وختمــه قاضــي اســتئناف‬\n      ‫توقيعــه وختمــه قاضــي اســتئناف توقيعــه وختمه)ا‪.‬ه ـ لــذا جــرى إحلاقــه‪،‬‬\n      ‫واختتمــت اجللســة يف الســاعة الثامنــة والنصــف‪ ،‬وبــاهلل التوفيــق‪،‬‬\n      ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                                ‫‪1434/10/07‬ه ـ ‪.‬‬\n\n\n\n\n‫‪331‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":319,"source_page_end":331,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"395320cd73717e4a628c736995dc1c2e32140403e2f4ca00ca27ffba2267cff8","normalized_text_hash":"563d704754aa642ab74c9f5e0197d51affd5538fe2eee9e89a6b373fc654bf2a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p319-34260802"},{"id":"d4f7ec66-1150-5591-a092-07261e5f88cf","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مختلس -اختالس مبالغ مالية عن طريق خيانة األمانة -شهادة العامل لرب العمل -غياب املدعى عليه وكفيله رغم تبلغهما - إثبات بالقرائن مع مين املدعي -حلف مين االستظهار -ثبوت الدعوى -حكم حضوري.","document_number":"33474299","case_number":"32524021","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":"الدائرة اجلزائية اخلامسة مبحكمة الاستئناف مبكة املكرمة","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/21","year":"1434","subject":"رد مختلس -اختالس مبالغ مالية عن طريق خيانة األمانة -شهادة العامل لرب العمل -غياب املدعى عليه وكفيله رغم تبلغهما - إثبات بالقرائن مع مين املدعي -حلف مين االستظهار -ثبوت الدعوى -حكم حضوري.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/12/21 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33474299 :‬‬\n                    ‫َر ْق ُم الدعوى‪32524021 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 347777‬تاريخه‪1434/1/11:‬هـ‬\n\n\n ‫رد مختلس ‪ -‬اختالس مبالغ مالية عن طريق خيانة األمانة ‪ -‬شــهادة‬\n ‫العامــل لــرب العمــل ‪ -‬غيــاب املدعــى عليــه وكفيلــه رغــم تبلغهمــا ‪-‬‬\n ‫إثبــات بالقرائــن مــع ميــن املدعــي‪ -‬حلــف ميــن االســتظهار ‪ -‬ثبــوت‬\n                                             ‫الدعــوى ‪ -‬حكــم حضــوري‪.‬‬\n\n\n\n\n ‫‪ -1‬قــول النبــي صلــى اهلل عليــه وســلم‪ ( :‬مــن حلــف علــى ميــن هــو فيهــا‬\n ‫فاجــر ليقتطــع بهــا مــال امــرئ مســلم لقــي اهلل وهــو عليــه غضبــان )‪.‬‬\n                                                                    ‫رواه مســلم‪.‬‬\n   ‫‪ -2‬قول النبي صلى اهلل عليه وسلم‪( :‬ال ضرر وال ضرار )‪ .‬رواه أحمد‪.‬‬\n                               ‫‪ -3‬املادة (‪ )55‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي علــى املدعــى عليــه الغائــب عــن مجلــس احلكــم بأنــه‬\n ‫َّإبــان عملــه يف املؤسســة التــي ميتلكهــا كمنــدوب مبيعــات مت تســليمه‬\n ‫بضاعــة ليقــوم ببيعهــا وحتصيــل ثمنهــا إال أنــه قــام بعــد بيــع البضاعــة‬\n ‫املذكــورة باختــاس ثمنهــا ولــم يســلمه ‪ ،‬طلــب إلزامــه بتســليم قيمــة‬\n ‫البضاعــة املختلســة إليــه‪ -‬قــررت احملكمــة الســير يف نظــر الدعــوى‬\n ‫مــع غيــاب املدعــى عليــه لكونــه تبلــغ بالدعــوى ولــم يحضــر وطلبــت‬\n\n                                                                                   ‫‪332‬‬\n\f      ‫مــن املدعــي بيانتــه ‪ -‬فقــدم املدعــي للمحكمــة عــددا مــن القرائــن التــي‬\n      ‫تعضــد دعــواه منهــا إقــرار منســوب للمدعــى عليــه علــى ورقــة عاديــة‪،‬‬\n      ‫وتقريــر احملاســب القانونــي الــذي يثبــت وجــود العجــز ‪ ،‬كمــا أحضــر‬\n      ‫شــاهد ًا إال أن احملكمــة لــم تقبــل شــهادته لكونــه يعمــل لــدى املدعــي‪-‬‬\n      ‫قــررت احملكمــة توجيــه اليمــن إلــى املدعــي تتميمـ ًا لبينتــه فأداهــا طبق‬\n      ‫مــا طلــب منــه ‪ -‬قضــت احملكمــة حضوريـ ًا بإلــزام املدعــى عليــه بتســليم‬\n      ‫املدعــي املبلــغ املدعــى بــه ‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى‬\n                                                                            ‫احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة مبكــة‬\n      ‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة مبكــة املكرمــة برقــم ‪ 32524021‬وتاريــخ ‪ 1432/11/13‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 321439703‬وتاريــخ ‪ 1432/11/13‬ه ـ ففــي‬\n      ‫يــوم األحــد املوافــق‪ 1433/02/07‬ه ـ افتتحــت اجللســة الســاعة الثانيــة‬\n      ‫عشــرة ظهــر ًا وفيهــا حضــر ســعودي مبوجــب الســجل املدنــي رقــم بصفتــه‬\n      ‫ا عــن ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم بصفتــه‬           ‫وكي ـ ً‬\n      ‫ا عــن باألصالــة عــن نفســه وبصفتــه صاحــب مؤسســة للتجــارة‬            ‫وكي ـ ً‬\n      ‫بالســجل التجــاري رقــم يف ‪1408/6/5‬ه ـ مبوجــب الوكالــة الصــادرة‬\n      ‫مــن كتابــة العــدل الثانيــة بالريــاض برقــم ‪ 8784‬يف ‪1433/2/2‬ه ـ‬\n      ‫اجللــد ‪ 20126‬ولــه فيهــا حــق املطالبــة واملرافعــة واملدافعــة ‪...‬الــخ ولــم‬\n      ‫يحضــر املدعــى عليــه وال مــن ينــوب عنــه وقــد تبلــغ مبوعــد هــذه اجللســة‬\n      ‫حســب خطابنــا املوجــه ملديــر مركــز شــرطة الكعكيــة وقــد وردنــا‬\n\n‫‪333‬‬\n\f‫مــن مديــر شــرطة الكعكيــة اخلطــاب رقــم ‪ 35/2/ 20/287998‬يف‬\n‫‪1432/11/19‬ه ـ واملتضمــن أنــه جــرى إطــاق ســراح املدعــى عليــه‬\n‫بالكفالــة احلضوريــة ومت إفهــام الكفيــل أنــه يف حالــة عــدم إحضــاره‬\n‫ســوف تنقلــب إلــى كفالــة غــرم وأداء كمــا مت إبالغــه باملوعــد احملــدد‬\n‫أه ـ وملخاطبــة شــرطة الكعكيــة إلحضــار املدعــى عليــه أو كفيلــه‬\n‫فقــد رفعــت اجللســة ويف يــوم الثالثــاء املوافــق‪ 1433/07/08‬ه ـ افتتحــت‬\n‫اجللســة الســاعة احلاديــة عشــرة صباحـ ًا وفيهــا حضــر املدعــي وكالــة ولم‬\n‫يحضــر املدعــى عليــه وال مــن ينــوب عنــه وقــد ســبقت الكتابــة لشــرطة‬\n‫الكعكيــة مبوجــب خطابنــا رقم ‪ 331037965‬يف ‪1433/6/3‬هـ وذلك‬\n‫إلحضــار املدعــى عليــه أو كفيلــه يف وقــت مــن أوقــات الــدوام الرســمي‬\n‫فوردنــا منــه اخلطــاب رقــم ‪ 284691‬يف ‪1433/7/1‬ه ـ واملتضمــن ‪ :‬حيــث‬\n‫أنــه مت االتصــال علــى املدعــى عليــه وكفيلــه أكثــر مــن مــرة وألنهــم‬\n‫غيــر متجاوبــن يف احلضــور ومت منــا مخاطبــة البحــث اجلنائــي للقبــض‬\n‫عليهــم أ‪.‬ه ـ وإلعــادة املعاملــة لهــم مــرة أخــرى وإحضــار املدعــى عليــه أو‬\n‫كفيلــه فقــد رفعــت اجللســة ويف يــوم األحــد املوافــق‪ 1433/11/28‬ه ـ‬\n‫افتتحــت اجللســة الســاعة العاشــرة والنصــف وفيهــا حضــر املدعــي أصالة‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ولــم يحضــر املدعــى عليــه‬\n‫وال مــن ينــوب عنــه وقــد جــرى طلبــه عــن طريــق شــرطة الكعكيــة‬\n‫بخطابنــا رقــم ‪ 32439706‬يف ‪1433/7/20‬ه ـ فوردنــا منهــم اخلطــاب‬\n‫رقــم ‪ 287208‬يف ‪1433/11/9‬ه ـ واملتضمــن بأنــه جــرى طلــب كفيــل‬\n‫املذكــور املدعــو مــن قبــل مركــز شــرطة املنصــور مبوجــب كتابنــا رقم‬\n‫‪ 286571‬يف ‪1433/10/9‬ه ـ فوردنــا إفادتهــم بالكتــاب رقــم ‪368595‬‬\n‫يف ‪1433/10/22‬ه ـ املتضمــن بأنــه بالبحــث عــن مقــر ســكنه لــم يعثــر‬\n\n\n                                                                                    ‫‪334‬‬\n\f      ‫عليــه ولــم يتمكنــوا مــن إبالغــه كمــا جــرى إيقــاف خدمــات الكفيــل‬\n      ‫املدعــو واملكفــول املولــي مصــري اجلنســية كمــا يتضــح لفضيلتكــم‬\n      ‫مــن طيــه أه ـ وبنــاء علــى املــادة اخلامســة واخلمســن مــن نظــام املرافعــات‬\n      ‫الشــرعية فقــد قــررت الســير يف الدعــوى فطلبــت مــن املدعــي حتريــر‬\n      ‫ا إن املدعــى عليه أصالــة كان يعمل مندوب مبيعات‬           ‫دعــواه فادعــى قائـ ُ‬\n      ‫لــدي وقــد اســتلم مــن املؤسســة بضاعــة بقيمــة قدرهــا أربعمائــة واثنــان‬\n      ‫وعشــرون ألف وتســعمائة وتســعون ريا ًال وقد طالبت املدعى عليه بإعادة‬\n      ‫البضاعــة أو قيمتهــا فذكــر لــي أنــه قــد بــاع البضاعــة باملبلــغ املذكــور‬\n      ‫وقــد قــام باســتالم املبلــغ واختالســه أطلــب احلكــم علــى املدعــى عليــه‬\n      ‫بإلزامــه بتســليمي املبلــغ املذكــور وقــدره أربعمائــة واثنــان وعشــرون ألف ًا‬\n      ‫وتســعمائة وتســعون ألــف ريــال هــذه دعــواي وبطلــب البينــة مــن املدعــي‬\n      ‫أبــرز ورقــة مكتوبــة بخــط اليــد وباالطــاع عليهــا وجــدت نصهــا كمــا‬\n      ‫يلــي ‪ :‬أقــر أنــا حامــل إقامــة رقــم إننــي اختلســت مــن التحصيــل اخلــاص‬\n      ‫ملؤسســة ‪ .....‬مبلــغ وقــدره (‪ )422990‬أربعمائــة وأثنــان وعشــرون ألــف‬\n      ‫وتســعمائة وتســعون ريــال ســعودي وســوف أقــوم بســدادها خــال فتــرة‬\n      ‫ا ملؤسســة‬  ‫أقصاهــا ثــاث أيــام مــن تاريخــه وأتعهــد بســداد املبلــغ كامـ ً‬\n      ‫‪ ......‬ويف حالــة عــدم الســداد يقــدم هــذا اإلقــرار إلــى اجلهــات القضائيــة‬\n      ‫وهــذا إقــرار منــي بذلــك أه ـ ومذيــل اإلقــرار ببصمــة املقــر مبــا فيــه‬\n      ‫والشــاهد األول والشــاهد الثانــي كمــا أبــرز ورقــة مكتوبــة باحلاســب‬\n      ‫اآللــي علــى ورق مكتــب محاســبون ومراجعــون قانونيــون ونصهــا كمــا‬\n      ‫يلــي ‪ :‬نفيدكــم بأننــا قــد قمنــا مبراجعــة املصادقــات اخلاصــة بعمــاء‬\n      ‫‪ .......‬املنــدوب مصــري اجلنســية مبوجــب إقامــة رقــم ‪ .......‬صــادرة مــن‬\n      ‫الريــاض وتنتهــي بتاريــخ ‪1433/8/5‬ه ـ كمــا يف ‪2011/9/29‬م والــذي‬\n\n\n‫‪335‬‬\n\f‫يعمــل لــدى مؤسســة ‪......‬للتجــارة حيــث تبــن وجــود فروقــات (عجــز)‬\n‫يف بعــض أرصــدة العمــاء مببلــغ (‪ )422,990‬فقــد أربعمائــة واثنــان‬\n‫وعشــرون ألفـ ًا وتســعمائة وتســعون ريــال ســعودي ال غيــر جتــدون مرفقــا‬\n‫طيــه كشــف بأســماء العمــاء والفروقــات اخلاصــة بــكل عميــل علــى‬\n‫حــدة أه ـ ومذيــل اخلطــاب بتوقيــع ‪ ...‬ومختــوم بختــم مكتبــه وبســؤال‬\n‫املدعــي أصالــة هــل لديــك زيــادة بينــة فأجــاب بالنفــي وبســؤاله عــن‬\n‫ا يوجــد لــدي أحــد الشــهود وهــو‬    ‫شــهود اإلقــرار املذكــور أجــاب قائ ـ ً‬\n‫وأمــا الشــاهد الثانــي فليــس موجــود ًا يف الســعودية وقــد ســافر يف إجــازة‬\n‫إلــى مصــر وقــد أحضــرت الشــاهد املذكــور هكــذا أجــاب ويف هــذه‬\n‫اجللســة حضــر الشــاهد ‪.....‬مصــري اجلنســية مبوجــب اإلقامــة رقــم ‪......‬‬\n‫ومــن مواليــد عــام ‪1977‬م ويعمــل لــدى مؤسســة ‪....‬ويســكن يف حــي‬\n‫‪ .......‬مبكــة املكرمــة وبســؤاله عــن عالقتــه باملدعــي واملدعــى عليــه‬\n‫ا أمــا املدعــي فابنــه كفيلــي وأمــا املدعــى عليــه فهــو زميلــي‬‫أجــاب قائـ ً‬\n‫يف العمــل وأعمــل أنــا وهــو مناديــب لــدى مؤسســة‪ .......‬املدعــي وبســؤاله‬\n‫ا أشــهد بــأن املدعــى عليــه قــد أقــر‬  ‫عمــا لديــه مــن شــهادة أجــاب قائ ـ ً‬\n‫أمــام املدعــي باختالســه مبلــغ وقــدره أربعمائــة واثنــان وعشــرون ألــف‬\n‫وتســعمائة وتســعون ريــا ًال وقــد أعــد اقــرار ًا بخــط يــده علــى اختالســه‬\n‫للمبلــغ املذكــور واســتعداده بإعــادة املبلــغ خــال ثالثــة أيــام مــن تاريــخ‬\n‫اإلقــرار وقــد شــهدت علــى هــذا اإلقــرار ووقعــت عليــه هــذا مــا لــدي وبــه‬\n‫أشــهد فجــرى ســؤال املدعــي أصالــة هــل الشــاهد يعمــل لديــك فأجــاب‬\n‫ا نعــم الشــاهد يعمــل لــدي وهــو بكفالــة ابنــي فجــرى إفهامــه بــأن‬    ‫قائـ ً‬\n‫شــهادته ال تقبــل شــرع ًا كمــا جــرى إفهامــه بأنــه يلزمــه حلــف ميــن‬\n‫االســتظهار علــى صحــة دعــواه وعلــى أن املدعــى عليــه لــم يقــم بســداد‬\n\n\n                                                                                      ‫‪336‬‬\n\f      ‫املبلــغ املدعــى بــه أو بعضــه لكــون خصمــه غائب ـ ًا وذلــك بعــد تذكيــره‬\n      ‫بخطرهــا وبحرمــة الزمــان واملــكان وبقولــه صلــى اهلل عليــه وســلم ( مــن‬\n      ‫حلــف علــى ميــن هــو فيهــا فاجــر ليقتطــع بهــا مــال امــرئ مســلم لقــي اهلل‬\n      ‫ا ‪:‬واهلل العظيــم‬  ‫وهــو عليــه غضبــان ) رواه مســلم فاســتعد وحلــف قائ ـ ً‬\n      ‫الــذي ال إلــه إال هــو عالــم الغيــب والشــهادة الرحمــن الرحيــم أن املدعــى‬\n      ‫عليــه ‪ ...‬يعمــل لــدى يف املؤسســة اخلاصــة بــي بوظيفــة منــدوب مبيعــات‬\n      ‫وبعــد جــرد البضاعــة أتضــح أنــه قــد قــام باختــاس املبلــغ املذكــور يف‬\n      ‫دعــواي وقــد أقــر املدعــى عليــه بذلــك وأعــد إقــرارا علــى نفســه بذلــك‬\n      ‫واســتعد بإعــادة املبلــغ خــال ثالثــة أيــام مــن تاريــخ إقــراره ولــم يقــم‬\n      ‫املدعــى عليــه بإعــادة املبلــغ املذكــور وال بعضــه واهلل العظيــم فبنــاء‬\n      ‫علــى مــا تقــدم مــن دعــوى املدعــي وملــا ورد يف املــادة اخلامســة واخلمســن‬\n      ‫املشــار إليهــا بعاليــه وألن املدعــي قــد حلــف ميــن االســتظهار كمــا هــو‬\n      ‫مفصــل أعــاه ولتضــرر املدعــي مــن عــدم حضــور املدعــى عليــه ولكــون‬\n      ‫الشــريعة جــاءت برفــع الضــرر كمــا يف قولــه صلــى اهلل عليــه وســلم (ال‬\n      ‫ضــرر وال ضــرار ) رواه أحمــد ومبــا أن للحاكــم واليــة علــى مــال الغائــب‬\n      ‫وملــا قــرره أهــل العلــم مــن جــواز احلكــم عليــه وعلــى املســتتر واملمتنــع ولــو‬\n      ‫كان يف البلــد ومبــا أن املدعــي قــد أبــرز قرائــن تقــوي جانبــه مــع ضعــف‬\n      ‫جانــب املدعــى عليــه بامتناعــه مــن احلضــور وهــو نــوع نكــول وقــد ترجــح‬\n      ‫أكثــر باليمــن املرجحــة لذلــك كلــه وألن القضــاء يعتمــد علــى غلبــة‬\n      ‫الظــن ورجحانــه فقــد ثبــت لــدي صحــة دعــوى املدعــي وحكمــت علــى‬\n      ‫املدعــى عليــه حضوريـ ًا بــأن يدفــع للمدعــي أصالــة مبلــغ وقــدره أربعمائــة‬\n      ‫واثنــان وعشــرون ألفـ ًا وتســعمائة وتســعون ريــا ًال وبعــد ذلــك يخلــى ســبيله‬\n      ‫مــن هــذه الدعــوى وهــو علــى دعــواه متــى حضــر وبعرضــه علــى املدعــي‬\n\n\n‫‪337‬‬\n\f‫قــرر قناعتــه باحلكــم وقــررت إكمــال مــا يلــزم حيــال إبــاغ املدعــى‬\n‫عليــه الغائــب باحلكــم حســب التعليمــات ثــم رفــع كامــل املعاملــة حــال‬\n‫االقتضــاء إلــى محكمــة االســتئناف لدراســة احلكــم وتدقيقــه حســب‬\n‫املتبــع وانتهــت اجللســة الســاعة احلاديــة عشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى‬\n‫اهلل على نبينا محمد وعلى آله وصحبه وســلم ‪ .‬حرر يف ‪1433/11/28‬‬\n                                                                               ‫هـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم األربعاء املوافق ‪ 1434/1/21‬هـ افتتحت‬\n‫اجللســة وقــد وردتنــا املعاملــة اخلاصــة بدعــوى ‪ ...‬ضــد املدعــى عليــه مــن‬\n‫الدائــرة اجلزائيــة اخلامســة مبحكمــة االســتئناف مبكــة املكرمــة‬\n‫واملتضمــن احلمــد هلل وحــده وبعــد فقــد اطلعنــا علــى هــذا الصــك رقــم‬\n‫‪ 33474299‬يف ‪1433/12/21‬ه ـ الصــادر مــن فضيلة الشــيخ ‪ /‬القاضي‬\n‫باحملكمــة العامــة مبكــة املكرمــة وأصدرنــا القــرار رقــم ‪347777‬‬\n‫يف ‪1434/1/11‬ه ـ املتضمــن املوافقــة علــى احلكــم أه ـ ‪ .‬عضــو ختمــه‬\n‫وتوقيعــه عضــو ختمــه وتوقيعــه رئيــس الدائــرة د‪ /‬ختمــه وتوقيعــه عليــه‬\n‫فقــد أمــرت بضبــط ذلــك وإحلاقــه بصكــه وســجله حتــى ال يخفــى وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                  ‫حــرر يف ‪ 1434/1/21‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                    ‫‪338‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":332,"source_page_end":338,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"95aa667386879f26e14e2dd380af622f26e7d091fbc9c648107540d99ebe0d3c","normalized_text_hash":"6410509359eafdabad54b69be0f2848aa64624222b4e9e97653e51bdb7948e70","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p332-33474299"},{"id":"d0c99b93-e4cb-58f3-b4c7-7a4e1be921f6","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد مختلس -اختاس أجهزة وقطع غيار عن طريق خيانة األمانة -إثبات بالقرائن مع مين املدعي -ثبوت الدعوى -خصم ما سدد من املبلغ -إخراج البضائع بفواتير -املتهم أمن املخزن والبضاعة عهدة لديه .","document_number":"3414912","case_number":"33379091","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/18","year":"1434","subject":"مطالبة برد مختلس -اختاس أجهزة وقطع غيار عن طريق خيانة األمانة -إثبات بالقرائن مع مين املدعي -ثبوت الدعوى -خصم ما سدد من املبلغ -إخراج البضائع بفواتير -املتهم أمن املخزن والبضاعة عهدة لديه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/1/18 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3414912 :‬‬\n                         ‫َر ْق ُم الدعوى‪33379091 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3473031‬تاريخه‪1434/1/25:‬هـ‬\n\n\n      ‫مطالبــة بــرد مختلــس ‪ -‬اختــاس أجهــزة وقطــع غيــار عــن طريق خيانة‬\n      ‫األمانــة ‪ -‬إثبــات بالقرائــن مــع ميــن املدعــي ‪ -‬ثبــوت الدعــوى ‪ -‬خصــم‬\n      ‫مــا ســدد مــن املبلــغ ‪ -‬إخــراج البضائــع بفواتيــر ‪ -‬املتهــم أمــن املخــزن‬\n                                                         ‫والبضاعــة عهــدة لديــه ‪.‬‬\n\n\n\n\n      ‫مــا أســتند إليــه القاضــي مــن املبــادئ العامــة وقواعد العدالة يف تســبيب‬\n                                                                          ‫حكمه ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي علــى احلاضــر معــه بأنــه َّإبــان عملــه يف املؤسســة التــي‬\n      ‫ميلكهــا كأمــن مســتودع قــام باختــاس أجهــزة مضخــات وقطــع غيــار‬\n      ‫مــن املؤسســة وبيعهــا حلســابه اخلــاص‪ ،‬ولــذا فقــد طلــب إلزامــه بتســليم‬\n      ‫ال‬\n      ‫قيمــة األجهــزة املختلســة ‪ -‬أنكــر املدعــى عليــه الدعــوى جملــة وتفصي ً‬\n      ‫‪ -‬قــدم املدعــي للمحكمــة عــددا مــن القرائــن التــي تعضــد دعــواه منهــا‬\n      ‫إقــرار للمدعــى عليــه مصــدق شــرعا بجــزء مــن املبلــغ‪ ،‬وتقريــر جهــات‬\n      ‫التحقيــق املتضمــن إقــراره بــأن جميــع عهــد املســتودع حتــت عهدتــه وأنــه‬\n      ‫كان علــى علــم بحــدوث االختالســات‪ ،‬وتقريــر احملاســب القانونــي‬\n      ‫الــذي يثبــت وجــود العجــز‪ -‬قــررت احملكمــة توجيــه اليمــن املكملــة‬\n‫‪339‬‬\n\f‫للمدعــي فأداهــا طبــق مــا طلــب منــه‪ -‬قضــت احملكمــة بإلــزام املدعــى‬\n‫عليــه بتســليم املدعــي املبلــغ املدعــى بــه ‪ -‬عــارض املدعــى عليــه علــى‬\n‫احلكــم‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم بعــد‬\n                                                           ‫اإلجــراء األخيــر‪.‬‬\n\n\n\n\n‫احلمد هلل وحده وبعد فلدي أنا‪ /‬القاضي يف احملكمة العامة مبحافظة‬\n‫جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫مبحافظــة جــدة ‪ /‬املســاعد برقــم ‪ 33379091‬وتاريــخ ‪1433/06/04‬ه ـ‬\n‫املقيدة باحملكمة برقم ‪ 331021155‬وتاريخ ‪1433/06/01‬هـ حضر‪/‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وادعــى علــى احلاضــر معــه‬\n‫باملجلــس الشــرعي‪ /‬مينــي اجلنســية باإلقامــة رقــم قائــا يف دعــواه عليــه‬\n‫إن املدعــى عليــه كان يعمــل كأمــن مســتودع لــدي‪ /‬مبوجــب العقــد‬\n‫املــؤرخ يف ‪2007/1/1‬م وقــد قــام باختــراق البرنامــج اخلــاص مبؤسســتي‬\n‫وتعديــل وحــذف أرصــدة حيــث اســتولى علــى مضخــات وقطــع غيــار‬\n‫ومعــدات أخــرى لبيعهــا حلســابه وتبلــغ قيمــة املضخــات وقطــع الغيــار التي‬\n‫اختلســها املدعــى عليــه ثالثمائــة وثالثــة وســتون ألــف وثالثمائــة وواحــد‬\n‫وثمانــون ريــاال أطلــب احلكــم عليــه بدفعهــا وبســؤال املدعــى عليــه قــال‬\n‫مــا ذكــره املدعــي مــن أننــي كنــت أعمــل لديــه صحيــح ولكــن مــا‬\n‫ذكــر مــن اختــراق برنامــج مؤسســة املدعــي واســتيالئي علــى املضخــات‬\n‫وقطــع الغيــار غيــر صحيــح وليــس يف ذمتــي للمدعــي أي شــيء هــذا‬\n‫وبســؤال املدعــي عــن بينتــه قــال ‪ :‬إنــه ســبق التحقيــق مــع املدعــى عليــه‬\n‫وســجن للحــق العــام ومذكــور ذلــك يف أوراق املعاملــة وعليــه رفعــت‬\n                                                                                        ‫‪340‬‬\n\f      ‫اجللســة ويف جلســة أخــرى حضــر املدعــي كمــا جــرى إحضــار املدعــى‬\n      ‫عليــه هــذا وباالطــاع علــى أوراق املعاملــة ظهــر القــرار رقــم ‪/13/124‬ج‬\n      ‫يف ‪1432/11/21‬ه ـ مــن احملكمــة اجلزئيــة بجــدة املتضمــن مصادقــة‬\n      ‫املدعــى عليــه علــى مــا ذكــر يف دعــوى املدعــي العــام مــن اختالســه مبلــغ‬\n      ‫عشــرة آالف ريــال وأنــه قــام بإرجاعهــا أمــا بقيــة املبالــغ فليــس مســئوال‬\n      ‫عنهــا واملســئول عنهــا هــو مديــر التســويق املدعــو‪ ، /‬كمــا تضمــن‬\n      ‫القــرار املذكــور اإلشــارة إلــى اعتــراف املدعــى عليــه املصــدق شــرعا‬\n      ‫املتضمــن قولــه ‪ :‬إنــه يف عــام ‪2010‬م وبصفتــي أمــن املســتودع مبؤسســة‬\n      ‫‪ ....‬للمضخــات الزراعيــة وأدوات احلفــر والتكســير قمــت بأخــذ غطــاس‬\n      ‫لوبــي ارتــوازي قيمتــه مــا بــن خمســة آالف إلــى ســتة آالف ريــال وقمــت‬\n      ‫ببيعــه بنفــس القيمــة وأخــذت املبلــغ حلســابي اخلــاص دون علــم املؤسســة‬\n      ‫وكذلــك قمــت ببيــع عــدد مــن قطــع الغيــار وال أذكر أنواعهــا بالتحديد‬\n      ‫واملبالــغ املســئول عنهــا والتــي تصرفــت بهــا مــن أمــوال الشــركة تقــدر‬\n      ‫بحوالــي عشــرة آالف ريــال وبالنســبة للمبالــغ التــي حصــل عليهــا عجــز‬\n      ‫باملؤسســة فاملســئول عنهــا هــو املدعــو‪ /‬ســوري اجلنســية والــذي يعمــل‬\n      ‫باملؤسســة بوظيفــة مديــر فنــي أه ـ وقــد مت احلكــم عليــه بســجنه ســنة‬\n      ‫أه ـ كمــا ظهــر يف اللفــة ‪ 3‬مــن املعاملــة تقريــر يتضمــن نتيجــة احلقيــق‬\n      ‫توجيــه االتهــام للمدعــى عليــه باالشــتراك مــع املدعــو‪ /‬باختــاس مبالــغ‬\n      ‫ماليــة مــن مؤسســة العلــم الدوليــة العائــدة للمدعــو ‪ /‬تقــدر بحوالــي‬\n      ‫ثالثمائــة ألــف ريــال عــن طريــق بيــع بعــض املعدات حلســاباتهم الشــخصية‬\n      ‫واختــراق برنامــج املؤسســة وتعديــل بعــض األصنــاف واصــدار فواتيــر‬\n      ‫ملســميات وهميــه وتعديــل وحــذف وشــطب بعــض العمليــات املتعلقــة‬\n      ‫بأرصــدة املســتودع الــذي حتــت عهدتــه وذلــك ملــا جــاء يف أقــوال املدعــى‬\n\n\n‫‪341‬‬\n\f‫عليــه بأنــه املســئول عــن جميــع عهــد املســتودع وأنــه اختلــس مبالــغ ماليــة‬\n‫ببيــع بعــض املعــدات ومصادقتــه علــى ذلــك شــرعا وملــا جــاء يف التقريريــن‬\n‫مــن احملاســب القانونــي التــي توضــح وجــود عجــز مالــي بذلــك املبلــغ مــن‬\n‫عهــدة املذكــور واعتــراف املدعــى عليــه بعملــه مبــا كان يحــدث مــن‬\n‫عمليــات اختــاس يف عهــدة املســتودع ويف برنامــج املؤسســة مــن تعديــل‬\n‫وحــذف وشــطب أه ـ وبعــرض ذلــك علــى املدعــى عليــه قــال ‪ :‬إن إقــراري‬\n‫باختــاس عشــرة آالف ريــال صحيــح وقــد قمــت بســداد هــذا املبلــغ أمــا‬\n‫بقيــة املبلــغ فــا أعلــم عنــه حيــث إن ‪ ....‬املذكــور أخــذ الرقــم الســري‬\n‫مــن املدعــي ‪ ،‬أمــا مــا ذكــر مــن مســئوليتي علــى املســتودع فصحيــح‬\n‫وقــد قمــت بإخــراج البضاعــة بحكــم الثقــة مــع املدعــي ‪ ....‬املذكــور‬\n‫أمــا بشــأن أننــي كنــت أعلــم بعمليــات االختــاس فغيــر صحيــح وبعــرض‬\n‫ذلــك علــى املدعــي قــال ال أذكــر أن املدعــى عليــه دفــع عشــرة آالف ريال‬\n‫ولكــن إبــراء للذمــة ال مانــع لــدي مــن خصمهــا مــن املبلــغ املدعــى بــه ثــم‬\n‫أبــرز محضــر تســليم مســتودع يف ‪2011/2/3‬م يتضمــن وجــود عجــز‬\n‫مالــي بحوالــي مائــة وأربعــة آالف وأربعمائــة وواحــد وتســعني ألــف ريــال‬\n‫وموقــع عليــه مــن املدعــى عليــه ‪ ،‬كمــا أبــرز تقريــر محاســبي صــادر مــن‬\n‫مكتــب الدكتــور ‪ ....‬لألعــوام ‪2007‬م إلــى ‪2010‬م مببلــغ عجــز قــدره‬\n‫مائتــان وتســعون ألــف وتســعمائة وســتة وأربعــون ريــاال والثانــي لعــام‬\n‫‪2011‬م مببلــغ اثنــن وســبعني ألــف وأربعمائــة وخمســة وثمانــن ريــاال أه ـ‬\n‫ثــم أضــاف املدعــي قائــا ‪ :‬إن املجمــوع هــو ثالثمائــة وثالثــة وســتون ألــف‬\n‫وثالثمائــة وواحــد وثمانــون ريــاال وبعــد خصــم مــا ذكــر يكــون املبلــغ‬\n‫املدعــى بــه ثالثمائــة وثالثــة وخمســون ألــف وثالثمائــة وواحــد وثمانــون‬\n‫ريــاال أطلــب احلكــم بــه وبعــرض ذلــك علــى املدعــى عليــه قــال ‪ :‬إنني غير‬\n\n\n                                                                                       ‫‪342‬‬\n\f      ‫مســئول عن ما ذكر يف االختالســات املذكورة ‪ ،‬هذا وبســؤال املدعي‬\n      ‫هــل يحلــف اليمــن زيــادة علــى مــا تقــدم قــال أنــا مســتعد بحلــف اليمــن‬\n      ‫وبطلبهــا بعــد وعظــه بعظــم اليمــن حلــف قائــا ‪ :‬أقســم بــاهلل العظيــم‬\n      ‫الــذي ال إلــه إال هــو ان هــذه الدعــوى صحيحــة وأن املدعــى عليــه هــو‬\n      ‫املســئول عــن املبلــغ املختلــس ثالثمائــة وثالثــة وخمســون ألــف وثالثمائــة‬\n      ‫وواحــد وثمانــون ريــال وحــده عــن ذلــك واهلل العظيــم فبنــاء علــى الدعــوى‬\n      ‫وجــواب املدعــى عليــه وحيــث حلــف املدعــي اليمــن زيــادة علــى مــا تقــدم‬\n      ‫مــن إقــرار املدعــى عليــه باختــاس جــزء مــن املبلــغ وبنــاء علــى محضــر‬\n      ‫التحقيــق لــذا حكمــت علــى أن يدفــع للمدعــي ‪ ..........‬املبلــغ املدعــى‬\n      ‫بــه وقــدره ثالثمائــة وثالثــة وخمســون ألــف وثالثمائــة وواحــد وثمانــون‬\n      ‫ريــال وبتالوتــه علــى املدعــى عليــه قــرر عــدم القناعــة وأن لديــه الئحــة‬\n      ‫اعتراضيــة فأفهــم بــأن موعــد اســتالم صــورة صــك احلكــم بعــد خمســة‬\n      ‫أيــام لتقــدمي الئحــة خــال ثالثــن يومــا وإال اكتســب احلكــم القطعيــة‬\n      ‫وأمــرت بتنظيــم صــك بذلــك وتســجيله وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/7/28‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ :‬حيــث عــادت إلينــا املعاملــة مــن محكمــة‬\n      ‫االســتئناف بالقــرار رقــم ‪ 33457257‬يف ‪1433/11/17‬ه املتضمــن‬\n      ‫مالحظــة مــا يلــي ‪ :‬أن فضيلتــه لــم يســبب احلكــم مــن الثبــوت وعدمــه وال‬\n      ‫بــد مــن ذلــك ملالحظــة مــا ذكــر وإجراء مــا يلزم أهـ وعليــه حضر املدعي‬\n      ‫كمــا جــرى إحضــار املدعــى عليــه حيــث قــرر قائــا إننــي كنــت أعمــل‬\n      ‫لــدى املدعــي كأمــن مســتودع ولــم يوجــد مســئول غيــري عــن املســتودع‬\n      ‫كمــا أنــه ال يتــم إخــراج أي بضاعــة مــن املســتودع إال بفاتــورة وقــد قمــت‬\n      ‫بإخــراج بضائــع بــدون فواتيــر بنــاء علــى طلــب ‪ ....‬الــذي يعمــل منــدوب‬\n\n\n‫‪343‬‬\n\f‫مبيعــات لــدى املدعــي وقــد عرضــت ذلــك علــى املدعــي فوافــق علــى مــا‬\n‫طلبــه ‪ ....‬املذكــور وبعــرض ذلــك علــى املدعــي قــال مــا ذكــره املدعــى‬\n‫عليــه غيــر صحيــح فلــم آذن للمدعــى عليــه وال ‪ ....‬املذكــور بإخــراج أي‬\n‫بضاعــة بــدون فاتــورة مقيــدة وبعــرض ذلــك علــى املدعــى عليــه وســؤاله‬\n‫هــل لديــه بينــة علــى مــا ذكــر مــن موافقــة املدعــي إلخــراج بضائــع مــن‬\n‫املســتودع بــدون فواتيــر قــال ال بينــة لــدي ‪ ،‬كمــا أنــي قــد عملــت لــدى‬\n‫املدعــي ســبع ســنوات ويف كل عــام ال يظهــر أي اختالســات ولــم تظهــر‬\n‫االختالســات ســوى يف العــام األخيــر وبســؤاله أيضــا هــل يطلــب ميــن‬\n‫املدعــي علــى مــا أنكــر قــال ال أطلــب ميينــه ‪ .‬وعليــه وحيــث إن املدعــى‬\n‫عليــه قــد أقــر مبســئوليته عــن البضاعــة املوجــودة باملســتودع ولــم يثبــت‬\n‫مــا ادعــاه لــذا فــا زلــت علــى مــا حكمــت بــه وأجريتــه وأمــرت بإحلــاق‬\n‫ذلــك بالصــك وســجله ورفــع أوراق املعاملــة حملكمــة االســتئناف وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                  ‫حــرر يف ‪1433/12/29‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد حيــث عــادت إلينــا املعاملــة بخطــاب فضيلــة‬\n‫رئيــس محكمــة االســتئناف مبكــة املكرمــة املكلــف رقــم ‪3440822‬‬\n‫يف ‪ 1434/1/26‬ه ـ املتضمــن أنــه جــرى تدقيــق احلكــم مــن الدائــرة‬\n‫اجلزائيــة األولــى وصــدر بحقــه القرار رقــم ‪ 3473031‬يف ‪1434/1/25‬هـ‬\n‫املــدون علــى ظهــر الصــك واملتضمــن أنــه باالطــاع علــى الصــك رقــم‬\n‫‪ 3414912‬وتاريخ‪1434/1/18‬هـ ـ الصــادر مــن فضيلــة الشــيخ ‪/‬‬\n‫القاضــي باحملكمــة العامــة مبحافظــة جــدة املتضمــن دعــوى ‪.........‬‬\n‫ضــد‪ /‬مينــي اجلنســية املتهــم بقضيــة اختــاس احملكــوم فيــه مبــا دون‬\n‫باطنــه وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة بعــد‬\n\n\n                                                                                   ‫‪344‬‬\n\f      ‫اإلجــراء األخيــر تقــررت املوافقــة علــى احلكــم قاضــي اســتئناف ختمــه‬\n      ‫وتوقيعــه قاضــي اســتئناف ختمــه وتوقيعــه رئيــس الدائــرة ختمــه وتوقيعــه‬\n      ‫وعليــه أمــرت بإحلــاق ذلــك يف ضبطــه وســجله وبــاهلل التوفيــق وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪ 1434/2/6‬ه ـ ‪.‬‬\n\n\n\n\n‫‪345‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":339,"source_page_end":345,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cabf1d48977b99c4e288e85ba778f48ea470afd665ac7f9b4e5ce821ecc5f2b9","normalized_text_hash":"be35b501927bbba2dae9f76b93dc138167de71815bc9d2264bc3b44ce0a2fa87","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p339-3414912"},{"id":"62e02b9d-05dc-5c4f-ad0b-346e9e9f1095","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مختلس -اختاس بضاعة عن طريق خيانة األمانة -بينات غير موصلة -استحقاق املدعي ليمن املدعى عليه على نفي الدعوى متى طلبها -احلكم برد دعوى.","document_number":"34239280","case_number":"33572978","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/12","year":"1434","subject":"رد مختلس -اختاس بضاعة عن طريق خيانة األمانة -بينات غير موصلة -استحقاق املدعي ليمن املدعى عليه على نفي الدعوى متى طلبها -احلكم برد دعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/6/12 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34239280 :‬‬\n                   ‫َر ْق ُم الدعوى‪33572978 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34341119‬تاريخه‪1434/10/26:‬هـ‬\n\n\n‫رد مختلــس ‪ -‬اختــاس بضاعــة عــن طريــق خيانــة األمانــة ‪ -‬بينــات غير‬\n‫موصلــة ‪ -‬اســتحقاق املدعــي ليمــن املدعــى عليــه علــى نفــي الدعــوى‬\n                                        ‫متــى طلبهــا ‪ -‬احلكــم بــرد دعــوى‪.‬‬\n\n\n\n\n‫مــا اســتند إليــه القاضــي مــن القواعــد العامــة ومبــادئ العدالــة الــواردة‬\n                                                          ‫يف تســبيب حكمــه ‪.‬‬\n\n\n\n‫ادعــى وكيــل املدعــي علــى احلاضــر معــه بأنــه َّإبــان عملــه لــدى موكلــه‬\n‫قــام باختــاس بضاعــة مــن املســتودع الــذي يعمــل فيــه والعائــد ملوكلــه‪،‬‬\n‫طلــب إلزامــه بــرد البضاعــة املختلســة أو تســليم قيمتهــا إلــى موكلــه‬\n‫‪ -‬أنكــر املدعــى عليــه الدعــوى جملــة وتفصيــا ســوى أنــه يعمــل لــدى‬\n‫املدعــي ‪ -‬أحضــر املدعــي عــددا مــن الشــهود فأدلــوا بشــهادتهم أمــام‬\n‫احملكمــة إال أن شــهادة أي منهــم لــم تكــن موصلــة إلثبــات دعــواه ‪-‬‬\n‫أفهمــت احملكمــة املدعــي بــأن لــه ميــن املدعــى عليــه علــى نفــي دعــواه‬\n‫فلــم يقبلهــا ‪ -‬قضــت احملكمــة بصــرف النظــر عــن دعــوى املدعــي لعــدم‬\n‫ثبوتهــا وأفهمتــه بــأن لــه ميــن املدعــى عليــه علــى نفــي دعــواه متــى طلبهــا‬\n‫‪ -‬قنــع املدعــى عليــه باحلكــم وعــارض عليــه املدعــي ‪ -‬قــررت محكمــة‬\n                                           ‫االســتئناف املصادقــة علــى احلكــم‪.‬‬\n                                                                                        ‫‪346‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض ‪ /‬املســاعد برقــم ‪ 33572978‬وتاريــخ ‪1433/09/12‬هـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331674178‬وتاريــخ ‪ 1433/09/09‬ه ـ ففــي‬\n      ‫يــوم الســبت املوافق‪1434/01/24‬ه ـ حضــر ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم عــن مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n      ‫الثانية بشرق الرياض رقم ‪ 33180690‬وتاريخ ‪1433/7/19‬هـ واملخول‬\n      ‫لــه فيهــا حــق املرافعــة واملدافعــة وحــق اإلقــرار والصلــح وحضــر حلضــوره‬\n      ‫مصــري اجلنســية مبوجــب رخصــة إقامــة رقــم وادعــى األول قائــا يف‬\n      ‫دعــواه ان هــذا احلاضــر معــي يعمــل لــدى موكلــي يف مســتودعه الواقــع‬\n      ‫بحــي ‪ .....‬بالريــاض بشــارع ‪ ......‬وطبيعــة عملــه جتهيــز طلبــات للموزعــن‬\n      ‫واملســتودع بــه بضاعــة نظــارات وعدســات الصقــة وقــد قــام باختــاس‬\n      ‫بضاعــة علــى مــدى عــدة أيام وتفصيل هذه البضاعة كالتالي عدد ‪288‬‬\n      ‫علبــة ‪ ...‬ثمــن العلبــة ‪160‬ريــال ومجموعهــا ســتة وأربعــون ألــف وثمانــون‬\n      ‫ريــ‪ 46.080‬ــاال وعــدد ‪ 400‬نظــارة شمســية وطبيــة يقــدر قيمتهــا مببلــغ‬\n      ‫ريــ‪ 105.250‬ــاال وكذلــك عــدد ‪ 188‬علبــة اكيــو فيــو ‪ 2‬وثمــن العلبــة‬\n      ‫الواحــدة ‪ 120‬فيكــون املجمــوع ريـ‪ 22.560‬ــاال ليصبــح إجمالــي املبالــغ‬\n      ‫املختلســة مــن النظــارات والعدســات الالصقــة مائــة وثالثــة وســبعون‬\n      ‫ألفــا وثمامنائــة وتســعون ريــ‪ 173.890‬ــاال اطلــب إلزامــه بــرد البضاعــة‬\n      ‫املختلســة أو إعــادة قيمتهــا هــذه دعــواي وبســؤال املدعــى عليــه أجــاب‬\n      ‫بقولــه مــا ذكــره املدعــي وكالــة يف دعــواه أننــي اعمــل لــدى موكلــه‬\n\n‫‪347‬‬\n\f‫يف املســتودع الــذي ذكــره صحيــح ومــا ذكــره مــن اختالســات فكلهــا‬\n‫غيــر صحيحــة فلــم اختلــس مــن املســتودع شــيئا وليــس لــه يف ذمتــي شــيء‬\n‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــي وكالــة قــال الصحيــح مــا‬\n‫ذكــرت ولــدي البينــة ويف يــوم األحــد املوافق‪1434/06/11‬ه ـ حضــر‬\n‫املدعــي اصالــة ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وحضــر‬\n‫حلضــوره املدعــى عليــه ‪ ...‬وبطلــب البينــة مــن املدعــي احضــر معــه مصــري‬\n‫اجلنســية مبوجــب رخصــة إقامــة رقــم وطلــب ســماع مــا لديــه وبســؤاله‬\n‫قــال أننــي اعمــل أخصائــي بصريــات لــدى كفيلــي املدعــي وانــا مــن‬\n‫مواليــد ‪1987‬م واشــهد أن احملاســب الــذي يعمــل لــدى كفيلــي اطلعنــي‬\n‫علــى صــورة اكيــاس عاديــة ال اعلــم مــا يف داخلهــا هــذا مــا لــدي مــن‬\n‫شــهادة كمــا احضــر معــه هنــدي اجلنســية مبوجــب رخصــة إقامــة رقــم‬\n‫وطلــب ســماع مــا لديــه وبســؤاله بواســطة مترجــم احملكمــة قــال أننــي‬\n‫مــن مواليــد عــام ‪1954‬م واعمــل فنــي بصريــات لــدى كفيلــي املدعــي‬\n‫اصالــة واشــهد أن املدعــى عليــه يعمــل ســواق ومنــدوب مبيعــات ورايتــه‬\n‫حــط كرتونــن ال اعلــم مــا بداخلهــا عنــد الســلم وســألته ملــاذا فقــال‬\n‫للبلديــة هــذا مــا لــدي وبــه اشــهد كمــا احضــر معــه وطلــب ســماع مــا‬\n‫لديــه وبســؤاله بواســطة املترجــم املذكــور قــال أننــي مــن مواليــد عــام‬\n‫‪ 1984‬م واعمــل فنــي بصريــات لــدى كفيلــي املدعــي اصالــة واشــهد‬\n‫أن املدعــى عليــه أخــذ كرتــون مــن املســتودع ال اعلــم مــا يف داخلــه مــن‬\n‫مســتودع كفيلــي هــذا مــا لــدي مــن شــهادة وبطلب زيادة بينــة من املدعي‬\n‫قــال ليــس لــدي ســوى مــن أحضــرت فأفهمتــه بــأن لــه ميــن املدعــى عليــه‬\n‫علــى نفــي دعــواه فقــال ال أطلــب ميينــه فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة املتضمنــة إنــكار املدعــى عليــه ملــا جــاء يف دعــوى املدعــي‬\n\n\n                                                                                       ‫‪348‬‬\n\f      ‫ولعــدم البينــة املوصلــة مــن املدعــي وعــدم طلبــه ميــن املدعــى عليــه لــذا‬\n      ‫صرفــت النظــر عــن دعــوى املدعــي لعــدم ثبوتهــا وأخليــت ســبيل املدعــى‬\n      ‫عليــه وبذلــك حكمــت وأفهمــت املدعــي بــان لــه ميــن املدعــى عليــه متــى‬\n      ‫مــا طلبهــا وبعــرض احلكــم علــى الطرفــن قــرر املدعــي عــدم القناعــة‬\n      ‫وافهــم بــان لــه مــدة ثالثــن يومــا لتقــدمي اعتراضــه عليــه واذا مضــت هــذه‬\n      ‫املــدة ســقط حقــه يف االعتــراض وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                   ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/06/11‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي باحملكمــة العامــة بالريــاض‬\n      ‫خلــف فضيلــة القاضــي ويف يــوم األحــد املوافق‪1434/12/01‬ه ـ افتتحت‬\n      ‫اجللســة بنــاء علــى مــا وردنــا مــن فضيلــة الرئيــس برقــم ‪342067071‬‬\n      ‫وتاريــخ ‪1434/11/23‬ه ـ شــرحا علــى خطــاب محكمــة االســتئناف‬\n      ‫برقــم ‪ 331674178‬وتاريــخ ‪1434/11/12‬ه ـ وبرفقــه قــرار دائــرة‬\n      ‫االســتئناف اجلزائيــة الثانيــة املســجل برقــم ‪ 34341119‬وتاريــخ‬\n      ‫‪1434/10/26‬ه ـ املتضمــن املصادقــة علــى احلكــم قاضــي االســتئناف‬\n      ‫ختمــه وتوقيعــه وقاضــي االســتئناف ختمــه وتوقيعــه وقاضــي االســتئناف‬\n      ‫ختمــه وتوقيعــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                  ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/12/1‬هــ‪.‬‬\n\n\n\n\n‫‪349‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":346,"source_page_end":349,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9b3cc16cab40dfe6d5bf4c0b87c7d0da61b32f32d5599b38e57ca1cd3713d007","normalized_text_hash":"ae43e6a4abcd0b447c2902e401dc419f3f5d5e2d3308214ffc785fb67baae529","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p346-34239280"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"3a67be2f-d09a-55c2-8377-0644990cf7c4","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مختلس -اختاس مبلغ مالي عن طريق خيانة األمانة - اختاس عن طريق عملية إلكترونية -شهادة الشهود -اختصاص- إثبات الدفع بالبراءة -مين على نفي الدعوى -احلكم برد الدعوى","document_number":"3414283","case_number":"3314349","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بأبها","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/17","year":"1434","subject":"رد مختلس -اختاس مبلغ مالي عن طريق خيانة األمانة - اختاس عن طريق عملية إلكترونية -شهادة الشهود -اختصاص- إثبات الدفع بالبراءة -مين على نفي الدعوى -احلكم برد الدعوى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/1/17 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3414283 :‬‬\n                         ‫َر ْق ُم الدعوى‪3314349 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34313675‬تاريخه‪1434/9/7:‬هـ‬\n\n\n      ‫رد مختلــس ‪ -‬اختــاس مبلــغ مالــي عــن طريــق خيانــة األمانــة ‪-‬‬\n      ‫اختــاس عــن طريــق عمليــة إلكترونيــة ‪ -‬شــهادة الشــهود ‪ -‬اختصــاص‪-‬‬\n      ‫إثبــات الدفــع بالبــراءة ‪ -‬ميــن علــى نفــي الدعــوى‪ -‬احلكــم بــرد الدعــوى‬\n                                                              ‫‪ -‬حكــم حضــوري ‪.‬‬\n\n\n\n\n      ‫مــا أســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                               ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل الشــركة املدعيــة علــى املدعــى عليهمــا بــأن األول َّإبــان‬\n      ‫عملــه لــدى موكلتــه كمنــدوب مبيعــات أصــدر أمــر شــراء بضاعــة‬\n      ‫مــن مســتودعاتها ثــم باعهــا بنفــس الرقــم الســري اخلــاص بــه ولــم يقــم‬\n      ‫بإيــداع قيمــة البضاعــة لصالــح الشــركة وبعــد مواجهــة احملاســب لــه‬\n      ‫بهــذا االختــاس أنكــره وذكــر أن املدعــى عليــه الثانــي هــو مــن قــام‬\n      ‫بذلــك فأنكــر الثانــي أيض ـ ًا عالقتــه بعمليــة االختــاس‪ ،‬ولــذا فقــد‬\n      ‫طلــب إلزامهمــا بتســليم موكلتــه املبلــغ الــذي مت اختالســه‪ -‬أنكــر‬\n      ‫املدعــى عليهمــا مــا جــاء يف الدعــوى ودفــع األول بأنــه أثنــاء حصــول‬\n      ‫عمليــة الشــراء والبيــع لــم يكــن موجــود ًا يف مقــر الشــركة ولديــه شــهود‬\n\n‫‪303‬‬\n\f‫يشــهدون بذلــك كمــا دفــع بــأن مــن عادة الشــركة إعداد محضر تســلم‬\n‫البضاعــة‪ -‬قــررت احملكمــة ســماع شــهادة الشــهود علــى إثبــات مــا دفــع‬\n‫بــه األول فشــهدوا مبــا يثبــت ذلــك‪ ،‬كمــا قــررت توجيــه اليمــن إليه على‬\n‫نفــي الدعــوى فأداهــا طبــق مــا طلــب منــه‪ -‬املدعــى عليــه الثانــي أقــر بــأن‬\n‫اجلهــاز الــذي متــت مــن خاللــه عمليــة االختــاس يقــع يف مقــر عملــه الدائــم‬\n‫كمــا أنــه تناقــض يف أقوالــه أمــام احملكمــة‪ -‬لذلــك قضــت احملكمــة‬\n‫بإلــزام املدعــى عليــه الثانــي بتســليم الشــركة املدعيــة املبلــغ املدعــى‬\n‫بــه كمــا قضــت بصــرف النظــر عــن دعــوى املدعــي ضــد املدعــى عليــه‬\n‫األول ‪ -‬عــارض املدعــي وكالــة واملدعــى عليــه الثانــي علــى احلكــم‪-‬‬\n                         ‫قــررت محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد فلــدي‬\n‫أنــا‪ ........./‬القاضــي يف احملكمــة العامــة بأبهــا وبنــاء علــى املعاملــة‬\n‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بأبهــا املســاعد برقــم‬\n‫‪ 3314349‬وتاريخ ‪1433/01/05‬هـ املقيدة باحملكمة برقم ‪3335893‬‬\n‫وتاريــخ ‪1433/01/05‬ه ـ ففــي يــوم االثنــن املوافــق ‪ 1433/02/29‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 12 : 11‬وفيهــا حضــر‪ ........... /‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬بصفتــه وكيــا عــن الشــركة‬\n‫املدعيــة شــركة ‪ ...‬مبوجــب صــك الوكالــة الصــادر مــن كتابــة العــدل‬\n‫الثانيــة بجنــوب جــدة برقــم ‪ 3059‬وتاريــخ ‪1432/1/23‬ه ـ وبســؤال‬\n‫املدعــي وكالــة عــن دعــواه أجــاب قائــا ان املدعــى عليــه هــذا احلاضــر‬\n‫هنــدي اجلنســية مبوجــب اإلقامــة رقــم يعمــل لــدى شــركة ‪ ...‬لالتصــاالت‬\n\n                                                                                       ‫‪304‬‬\n\f      ‫موكلتــي بوظيفــة منــدوب مبيعــات مهمــة عملــه التســوق للشــركة ببيــع‬\n      ‫بطاقــات الشــحن وشــرائح ومــن طبيعــة عمــل الشــركة أن كل موظــف‬\n      ‫لــه رقــم ســري خــاص بــه يســتطيع مــن خاللــه إصــدار أمــر شــراء مــن‬\n      ‫مســتودع الشــركة وكذلــك تســلم البضائــع مــن املســتودع وبنــاء علــى‬\n      ‫ذلــك فقــد قــام املدعــى عليــه بإصــدار أمــر شــراء بضاعــة بطاقــات شــحن‬\n      ‫مــن مســتودع الشــركة مببلــغ وقــدره مائتــان وســبعة وعشــرون ألــف ريال‬\n      ‫قــام بتســليمها بنفــس الرقــم الســري اخلــاص بــه وبــاع البضاعــة يف الســوق‬\n      ‫بنفــس مبلــغ الشــراء ولــم يقــم بإيــداع لهــذا املبلغ لدى الشــركة موكلتي‬\n      ‫وقــام محاســب الشــركة بالتدقيــق وســأل املدعــى عليــه عــن ذلــك‬\n      ‫فأجابــه بأنــه لــم يقــرر أمــر شــراء وال تســلم وإمنــا كان ذلــك عــن طريــق‬\n      ‫زميلــه يف العمــل يف نفــس املكتــب بتواجــده ويدعــى مينــي اجلنســية وقــد‬\n      ‫أنكــر ‪ ...‬املذكــور أمــام احملاســب لذلــك أطــب احلكــم علــى املدعــى‬\n      ‫عليهمــا بإلزامهمــا بتســليمي مبلــغ وقــدره مائتــان وســبعة وعشــرون ألــف‬\n      ‫ريــال هــذه دعــواي وبســؤال املدعــى عليــه عــن دعــوى املدعــي وكالــة‬\n      ‫أجــاب قائــا مــا ذكــره املدعــي وكالــة كلــه غيــر صحيــح مــا عــدا‬\n      ‫مســألة طبيعــة عمــل الشــركة فصحيــح والــذي قــام بهــذه العمليــة هــو‬\n      ‫عامــل لــدى الشــركة هــو هكــذا أجــاب ثــم جــرى رفــع اجللســة إلحضــار‬\n      ‫ويف جلســة أخــرى يــوم الســبت املوافق‪1433/05/22‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 11 : 50‬وفيهــا حضــر الطرفــان وحضــر حلضورهمــا مينــي‬\n      ‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم وبســؤال احلاضــر عمــا ذكــره‬\n      ‫املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــى عليــه يف جوابــه علــى‬\n      ‫الدعــوى كلــه صحيــح مــا عــدا مســألة إصــدار أمــر الشــراء والتســلم‬\n      ‫فغيــر صحيــح علمــا أن هــذا املكتــب هــو عبــارة عــن غرفــة بهــا مكتــب‬\n\n\n‫‪305‬‬\n\f‫واحــد عليــه جهــاز حاســب آلــي يتنــاوب اســتخدامه أنــا واملدعــى عليــه إال‬\n‫أننــي مســتقر فيــه دائمــا بينمــا املدعــى عليــه ميــر بــه ألجــل إصــدار أمــر‬\n‫شــراء وتســلم وعندمــا وقعــت هــذه القضيــة يف ‪2010/1/8‬م أصــدر‬\n‫املدعــى عليــه أمــر شــراء وتســلم بضاعــة بطاقــة شــحن وقــد تســلمت أمــر‬\n‫تســليم البضاعــة بنــاء علــى أمــر املركــز الرئيســي للشــركة يف جــدة‬\n‫وقمــت ببيعهــا هكــذا أجــاب ثــم أضــاف قائــا إننــي لــم أبعهــا وإمنــا قمــت‬\n‫بتســليم البضاعــة إلــى املدعــى عليــه عــن طريــق اجلهــاز هكــذا أجــاب‬\n‫وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا الصحيــح مــا ذكــرت‬\n‫علمــا أن مــن عــادة الشــركة هــو إعــداد محضــر تســلم البضاعــة ولــدي‬\n‫شــاهدان علــى أنــه ليــس لــي عالقــة باملدعــى بــه هكــذا قــرر ورفعــت‬\n‫اجللســة مــن أجــل ذلــك ويف جلســة أخــرى يــوم األربعــاء‬\n‫املوافق‪1433/06/18‬ه ـ افتتحــت اجللســة الســاعة ‪ 12 : 58‬وفيهــا حضــر‬\n‫املدعــى عليــه وحضــر حلضــوره هنــدي اجلنســية مبوجــب رخصــة اإلقامــة‬\n‫بصفتــه شــاهدا يف هــذه القضيــة وبســؤاله عمــا لديــه مــن شــهادة أجــاب‬\n‫قائال كنت أعمل يف شركة ‪ ....‬فرع أبها وقد كنت يوم ‪2010/1/8‬م‬\n‫كنــت مــع املدعــى عليــه مــن الســاعة الثالثــة والنصــف عصــرا وقــد‬\n‫ذهبنــا يف ســيارة املدعــى عليــه بعــد صــاة العصــر لتوزيــع بطاقــات‬\n‫اتصــاالت وحتصيــل مبالــغ إلــى صــاة املغــرب وصلينــا املغرب يف مســجد‬\n‫احلواشــي وقــد ذهبنــا بعــد الصــاة إلــى حــي اخلالديــة لتحصيــل مبلــغ مــن‬\n‫محــل جــواالت إلــى أذان العشــاء وبعــد ذلــك رجعنــا ألخــذ ابنائنــا مــن‬\n‫املدرســة ثــم قــام املدعــى عليــه بتوصيلــي إلــى بيتــي وأخبرنــي بأنــه‬\n‫ســيذهب إلــى أبهــا وبعــد ذلــك قمــت بالذهــاب إلى أبها بســيارة الشــركة‬\n‫إلجــراء صيانــة يف مدينــة أبهــا وقــد قابلــت املدعــى عليــه عنــد ســوق‬\n\n\n                                                                                       ‫‪306‬‬\n\f      ‫الســمك الســاعة الثامنــة والنصــف تقريبــا وكان الغــرض لذهابــي‬\n      ‫لســوق الســمك أخــذ زميلــي الفنــي الــذي يعمــل يف الشــركة هكــذا‬\n      ‫شــهد وقــد مت رفــع اجللســة لســماع أقــوال الشــاهد الثانــي ويف جلســة‬\n      ‫أخــرى يــوم االثنــن املوافــق ‪1433/07/07‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫الثانيــة عشــرة ظهــرا وفيهــا حضــر أطــراف الدعــوى وقــد طلــب مــن‬\n      ‫املدعــي وكالــة إحضــار وكالــة أخــرى غيــر الوكالــة الســابقة فأحضر‬\n      ‫صــك وكالــة صــادر مــن كتابــة العــدل الثانيــة بجنــوب جــدة برقــم‬\n      ‫‪ 28433‬وتاريــخ ‪1433/7/1‬ه ـ وبســؤال املدعــى عليــه ‪ ....‬عــن البينــة التي‬\n      ‫وعــد بإحضارهــا فأجــاب قائــا بان بينتي هو هذا الشــاهد احلاضر‪....../‬‬\n      ‫ســوداني اجلنســية مبوجــب رخصــة اإلقامــة رقــم وأطلــب ســماع مــا لــدى‬\n      ‫هــذا الشــاهد هكــذا قــرر وبســؤال الشــاهد احلاضــر عــن ســنه ومهنتــه‬\n      ‫ومحــل إقامتــه وعالقتــه باملدعــى عليــه أجــاب قائــا إننــي مــن مواليــد‬\n      ‫عــام ‪1978‬م ومهنتــي مهنــدس إلكترونــي وإقامتــي يف محافظــة خميــس‬\n      ‫مشــيط وال توجــد لــي عالقــة باملدعــى عليــه وبســؤاله عمــا لديــه مــن‬\n      ‫شــهادة قــال أشــهد هلل تعالــى أن وقــت صــاة العشــاء يف ‪2010/4/1‬م‬\n      ‫قــام بشــحن ماكينــة ‪ ...‬اخلاصــة ببطاقــات شــحن ‪ ...‬مببلــغ وقــدره ألــف‬\n      ‫ريــال يف محــل ‪ ...‬يف حــي ‪ ......‬بخميــس مشــيط هكــذا شــهد وبعــرض‬\n      ‫الشــاهد وشــهادته علــى املدعــى عليــه قــال أمــا الشــاهد فــا أعلــم عــن‬\n      ‫حالــه شــيئا وأمــا الشــهادة فغيــر صحيحــة هكــذا قــرر ثــم جــرى ســؤال‬\n      ‫املدعــي وكالــة عمــا لديــه بخصــوص هــذه الشــهادة أجــاب قائــا ال علــم‬\n      ‫لــي بذلــك وإمنــا الــذي أعلــم عنــه أن عمليــة الطلــب متــت يف ‪2010/4/1‬م‬\n      ‫الســاعة الســابعة وثمــان وعشــرين دقيقــة مســاء وعمليــة التحويــل متــت يف‬\n      ‫يــوم ‪2010/4/1‬م الســاعة الســابعة والنصــف مســاء وعمليــة التســلم متــت‬\n\n\n‫‪307‬‬\n\f‫يف يــوم ‪2010/4/1‬م الســاعة الســابعة وواحــد وثالثــن دقيقــة مســاء‬\n‫واملســافة بــن شــركة ‪ ...‬ومحــل ‪ ...‬ربــع ســاعة ثــم أبــرز املدعــي وكالــة‬\n‫ورقــة العمليــات التــي ذكرهــا بأوقاتهــا وجــرى االطــاع عليهــا فوجدتهــا‬\n‫مطابقــة ملــا ذكــر كمــا أبــرز الشــاهد ورقــة تتضمــن التأكيــد لصحــة‬\n‫مــا ذكــر ورفعــت اجللســة إلحضــار البينــة علــى عدالــة الشــهود ويف‬\n‫جلســة أخــرى يــوم االثنــن بتاريخ‪1433/12/20‬ه ـ افتتحــت اجللســة‬\n‫الســاعة الثامنــة صباحــا وفيهــا حضــر املدعــي وكالــة وحضــر حلضــوره‬\n‫املدعــى عليــه وبســؤال املدعــى عليــه عــن املزكيــة للشــهود أحضــر كل‬\n‫مــن ‪......‬ســوداني اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪......‬و ‪ ......‬هنــدي‬\n‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ .....‬وقــد جــرى ســؤالهم عمــا‬\n‫لديهــم مــن تزكيــة فأجــاب كل واحــد منهمــا قائــا أشــهد هلل تعالــى‬\n‫بــأن املدعــو هــذا احلاضــر عــدل ثقــة هكــذا شــهدا فبنــاء علــى مــا تقــدم‬\n‫فقــد جــرى طلــب اليمــن مــن املدعــى عليــه احلاضــر علــى نفــي أخــذه املبلغ‬\n‫املدعــى بــه بنــاء علــى قاعــدة الشــاهد واليمــن لكــون التزكيــة وردت‬\n‫علــى شــاهد واحــد فاســتعد ببذلهــا وجــرى تخويفــه بخطــر اليمــن‬\n‫الغمــوس ثــم طلــب منــه اليمــن فحلــف وفــق مــا طلــب منــه بــاهلل تعالــى‬\n‫قائــا واهلل العظيــم الــذي ال إلــه إال هــو أننــي لــم آخــذ املبلــغ املدعــى بــه‬\n‫ومقــداره مائتــان وســبعة وعشــرون ألــف ريــال وال شــيء منــه واهلل العظيم‬\n‫هكــذا حلــف فبنــاء علــى مــا تقــدم من الدعــوى واإلجابة ونظــرا إلنكار‬\n‫املدعــى عليــه صحــة الدعــوى وإلقــرار املدعــى عليــه بــأن املــكان الــذي‬\n‫هــو مقــر املبلــغ املدعــى بــه هــو املقــر الدائــم لعملــه وأن املدعــى عليــه‬\n‫يأتيــه أحيانــا ممــا يقــوي معــه توجــه التهمــة إلــى بأخــذه املبلــغ وإلقامــة‬\n‫املدعــى عليــه الشــاهد املعــدل شــرعا علــى نفــي تواجــد املدعــى عليــه‬\n\n\n                                                                                          ‫‪308‬‬\n\f      ‫وقــت أخــذ املبلــغ املدعــى بــه يف احملــل ولتناقــض إجابــة املدعــى عليــه يف‬\n      ‫مســألة تســلم البضاعــة وبيعهــا ممــا يقــوي معــه جانــب التهمــة يف أخــذ‬\n      ‫املبلــغ املدعــى بــه فقــد قــررت اآلتــي أوال صــرف النظر عن دعــوى املدعي‬\n      ‫ضــد املدعــى عليــه ‪ ...‬هنــدي اجلنســية مبوجــب رخصــة اإلقامــة رقــم ثانيــا‬\n      ‫إلــزام املدعــى عليــه مينــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم بدفــع‬\n      ‫مبلــغ وقــدره مائتــان وســبعة وعشــرون ألــف ريــال ومبــا تقــدم حكمــت‬\n      ‫ويعــد هــذا احلكــم حضوريــا وبعــرض احلكــم علــى املدعــي وكالــة قــرر‬\n      ‫عــدم القناعــة وطلــب االســتئناف بــدون تقــدمي الئحــة اعتراضيــة وســوف‬\n      ‫يجــري بــإذن اهلل بعــث نســخة مــن احلكــم إلــى املدعــى عليــه لتقــدمي‬\n      ‫اعتراضــه عليــه خــال ثالثــن يومــا مــن تاريــخ التســلم إذا لــم يقــدم‬\n      ‫اعتراضــه خاللهــا يســقط حقــه يف االعتــراض وبــاهلل التوفيــق وصلــى‬\n      ‫اهلل على نبينا محمد وعلى آله وصحبه وسلم حرر يف ‪1433/12/20‬هـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد ففــي‬\n      ‫هــذا اليــوم الثالثــاء بتاريــخ ‪1434/2/26‬ه ـ الســاعة العاشــرة وخمــس‬\n      ‫وأربعــون دقيقــة صباحــا افتتحــت اجللســة وقــد جــرى منــا بعــث نســخة مــن‬\n      ‫احلكــم عــن طريــق قســم اإلحضــار بهــذه احملكمــة للمدعــى عليــه‬\n      ‫لتقــدمي اعتراضــه علــى احلكــم باخلطــاب رقــم ‪ 34/204844‬وتاريــخ‬\n      ‫‪1434/1/25‬ه ـ فوردنــا الــرد مــن قســم اإلحضــار واملتضمــن « نفيدكــم‬\n      ‫بأنــه مت الذهــاب إلــى مجمــع األســواق قــرب مســجد النملــة ولــم جنــد‬\n      ‫أحــدا بهــذا االســم كمــا أن األرقــام املوضحــة بعاليــه ال يــرد عيهــا أحــد‬\n      ‫لــذا تعــذر علينــا تســليم صــورة صــك احلكــم « ولكــون احلــال مــا ذكــر‬\n      ‫فقــد قــررت بعــث كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق‬\n      ‫احلكــم ورفعــت اجللســة لذلــك حتــى ورود املعاملــة وبــاهلل التوفيــق وصلــى‬\n\n\n‫‪309‬‬\n\f‫اهلل علــى نبينــا محمــد وعلــى آلــه وصبــه وســلم حــرر يف ‪1434/2/26‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد ففــي‬\n‫هــذا اليــوم األحــد بتأريــخ ‪1434/5/26‬ه ـ الســاعة احلاديــة عشــرة‬\n‫والنصــف صباحــا افتتحــت اجللســة وقــد عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة برقــم ‪ 34783138‬وتاريــخ‬\n‫‪1434/5/15‬ه ـ برفقهــا قــرار املالحظــة الصــادر مــن الدائــرة اجلزائيــة‬\n‫الثالثــة برقــم ‪ 34210977‬وتاريــخ ‪1434/5/12‬ه ـ واملتضمــن « وبدراســة‬\n‫املعاملــة تقــرر باألكثريــة أن هــذه القضيــة مــن اختصــاص محكمــة‬\n‫االســتئناف مبنطقــة عســير ومــا أشــير إليــه بقرارهــم املرفــق رقــم‬\n‫‪ 3463967‬يف ‪1434/3/16‬ه ـ محــل نظــر حيــث لــم يطــرأ علــى احلكــم‬\n‫الســابق أي إشــكال بــل جــاء احلكــم جديــدا يف احلــق اخلــاص فــا واليــة‬\n‫حملكمــة االســتئناف مبكــة املكرمــة واحلــال مــا ذكــر ملالحظــة ذلــك‬\n‫واهلل املوفــق « وعليــه فقــد أمــرت بإحلــاق مــا تقــدم بالصــك وســجله ثــم‬\n‫بعــث كامــل أوراق املعاملــة إلــى محكمــة االســتئناف مبنطقــة عســير‬\n‫إلكمــال الــازم ورفعــت اجللســة لذلــك حتــى ورود املعاملــة وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n‫‪1434/5/26‬ه ـ احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي‬\n‫بعــده أمــا بعــد ففــي هــذا اليــوم األحــد بتأريــخ ‪1434/08/07‬ه ـ الســاعة‬\n‫العاشــرة صباحــا افتتحــت اجللســة وقــد عــادت املعاملــة مــن محكمــة‬\n‫االستئناف مبنطقة عسير برقم ‪ 341435142‬وتأريخ ‪1434/07/09‬هـ‬\n‫برفقهــا قــرار املالحظــة الصــادر مــن الدائــرة اجلزائيــة الرابعــة برقــم‬\n‫‪ 34254372‬وتأريــخ ‪1434/06/28‬ه ـ واملتضمــن « وبدراســة الصــك‬\n‫وصــورة ضبطــه وأوراق املعاملــة تقــرر إعادتهــا لفضيلــة حاكمهــا‬\n\n\n                                                                                    ‫‪310‬‬\n\f      ‫ملالحظــة مــا يلــي أوال أن فضيلتــه قــد أصــدر احلكــم بحــق املدعــى عليــه‬\n      ‫حضوريــا مــع أنــه لــم يبلــغ باحلكــم فيراعــى ذلــك وفــق النظــام ثانيــا‬\n      ‫حكــم فضيلتــه علــى املدعــى عليــه بدفــع مبلــغ مائتــن وســبعة وعشــرين‬\n      ‫ألفــا ولــم يبــن اجلهــة احملكــوم لهــا فيبــن ذلــك وعلــى فضيلتــه مالحظــة‬\n      ‫مــا ذكــر وإكمــال الــازم واهلل املوفــق « عليــه أجيــب أصحــاب الفضيلة‬\n      ‫باآلتــي بالنســبة إلــى الفقــرة أوال فقــد جــرى منــا تبليــغ املدعــى عليــه‬\n      ‫للحضــور إلــى هــذه احملكمــة عــن طريــق قســم اإلحضــار لتزويــده‬\n      ‫بنســخة مــن احلكــم لتقــدمي اعتراضــه عليــه خــال املــدة النظاميــة‬\n      ‫وبالنســبة للفقــرة ثانيــا فــإن املبلــغ احملكــوم بــه ومقــداره مائتــان وســبعة‬\n      ‫وعشــرون ألــف ريــال يســلم إلــى شــركة ‪ ...‬لالتصــاالت هــذا مــا لــدي‬\n      ‫وأمــرت بإحلــاق مــا تقــدم بالصــك وســجله وســوف يجــري بــإذن اهلل تعالــى‬\n      ‫إعــادة كامــل أوراق املعاملــة إلــى محكمــة االســتئناف إلكمــال الــازم‬\n      ‫ورفعــت اجللســة لذلــك حتــى ورود اجلــواب وبــاهلل التوفيــق وصلــى اهلل‬\n              ‫على نبينا محمد وعلى آله وصحبه وسلم حرر يف ‪1434/8/7‬هـ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد‬\n      ‫ففــي هــذا اليــوم الثالثــاء بتاريــخ ‪1434/9/22‬ه ـ حســب تقــومي أم‬\n      ‫القــرى الســاعة الثانيــة ظهــرا افتتحــت اجللســة وقــد عــادت املعاملــة‬\n      ‫مــن محكمــة االســتئناف مبنطقــة عســير برقــم ‪ 341435142‬وتاريــخ‬\n      ‫‪1434/09/17‬ه ـ برفقهــا قــرار املصادقــة الصــادر مــن الدائــرة اجلزائيــة‬\n      ‫الرابعــة برقــم ‪ 34313675‬وتاريــخ ‪1434/9/7‬ه ـ واملتضمــن « وحيــث‬\n      ‫ســبق دراســة الصــك وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى‬\n      ‫مــا أجــاب بــه فضيلتــه وأحلقــه بالضبــط والصــك وســجله بنــاء علــى‬\n      ‫قرارنــا رقــم ‪ 34254372‬وتاريــخ ‪1434/06/28‬ه ـ تقــررت املوافقــة‬\n\n\n‫‪311‬‬\n\f‫علــى احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق « وحتــى ال يخفــى جــرى‬\n‫التهميــش مبوجبــه وأمــرت بإحلــاق مــا تقــدم بالصــك وســجله وبــاهلل تعالى‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                          ‫‪1434/09/22‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                  ‫‪312‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":303,"source_page_end":312,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"80bfb613577072ea9765ab10f348904184ba2e19cc65cf5e780b065d41096882","normalized_text_hash":"37031939fdc392b2d93c4761ea951378bd4da39888273e449e76c7d160857b02","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p303-3414283"},{"id":"be0d7b07-cbdc-5267-b60d-c5a889b7be94","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مختلس -اختاس مبلغ مالي عن طريق خيانة األمانة -عجز عن إثبات الدفع -قرائن إدانه -أقوال املتهم تخالف املألوف واملعمول به -ثبوت الدعوى -احلكم باإللزام برد املبلغ .","document_number":"34167155","case_number":"32308699","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/21","year":"1434","subject":"رد مختلس -اختاس مبلغ مالي عن طريق خيانة األمانة -عجز عن إثبات الدفع -قرائن إدانه -أقوال املتهم تخالف املألوف واملعمول به -ثبوت الدعوى -احلكم باإللزام برد املبلغ .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/3/21 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34167155 :‬‬\n                         ‫َر ْق ُم الدعوى‪32308699 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34343519‬تاريخه‪1434/1/11 :‬هـ‬\n\n\n      ‫رد مختلــس ‪ -‬اختــاس مبلــغ مالــي عــن طريــق خيانــة األمانــة ‪ -‬عجــز‬\n      ‫عــن إثبــات الدفــع ‪ -‬قرائــن إدانــه ‪ -‬أقــوال املتهــم تخالــف املألــوف‬\n              ‫واملعمــول بــه ‪ -‬ثبــوت الدعــوى ‪ -‬احلكــم باإللــزام بــرد املبلــغ ‪.‬‬\n\n\n\n\n      ‫ق ــول ال ــنبي صلــى اهلل عليــه وســلم ‪ ( :‬عـ ــلى الـي ــد مــا أخــذت حتــى‬\n                                                                       ‫ت ــؤديـ ــه ) ‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل الشــركة املدعيــة بــأن املدعــى عليــه احلاضــر َّإبــان عملــه‬\n      ‫لديهــا كقائــد طاقــم نقــل أمــوال خاصــة باملصــارف اســتلم مــن موكلتــه‬\n      ‫ثمانيــة أكيــاس بهــا مبالــغ ماليــة لكــي يقــوم بتوصيلهــا إلــى أحــد‬\n      ‫املصــارف‪ ،‬وقــد قــام بتســليم املصــرف ســبعة أكيــاس أمــا الكيــس‬\n      ‫الثامــن ومــا فيــه مــن مبلــغ مالــي فقــد ادعــى أنــه ســلمه للمصــرف وتبــن‬\n      ‫كذبــه مــن خــال التحقيقــات اجلنائيــة‪ ،‬ولــذا فقــد طلــب إلزامــه بإعــادة‬\n      ‫املبلــغ املختلــس إلــى الشــركة موكلتــه‪ -‬أقــر املدعــى عليــه باســتالم‬\n      ‫األكيــاس الثمانيــة احملتويــة علــى األمــوال ودفــع بأنــه ســلمها ملوظــف‬\n      ‫بخزينــة املصــرف مبــا فيهــا الكيــس الثامــن احملتــوي علــى املبلــغ املالــي‬\n      ‫محــل الدعــوى إال أن املوظــف املذكــور لــم يســلمه ســندا باســتالمه‬\n\n‫‪313‬‬\n\f‫ولذلــك فهــو غيــر مســتعد بتســليم املدعيــة أي شــيء مــن املبلــغ املدعــى‬\n‫بــه ‪ -‬طلبــت احملكمــة مــن املدعــى عليــه تقــدمي بينــة علــى مــا دفــع بــه مــن‬\n‫تســليم الكيــس الثامــن مبــا فيــه مــن مبلــغ مالــي إلــى املصــرف فعجز عن‬\n‫إثبــات ذلــك الدفــع ‪ -‬املدعــى عليــه أقــر باســتالم املبالــغ املاليــة ودخولهــا‬\n‫يف عهدتــه وعجــز عــن إثبــات تســليم املبلــغ محــل الدعــوى إلــى املصــرف‪-‬‬\n‫قضــت احملكمــة بإلــزام املدعــى عليــه بتســليم الشــركة املدعيــة املبلــغ‬\n‫املدعــى بــه‪ -‬قنــع وكيــل املدعيــة باحلكــم وعــارض عليــه املدعــى عليــه‪-‬‬\n                      ‫قــررت محكمــة االســتئناف املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي‪ ...‬يف احملكمــة العامــة‬\n‫بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالدمــام برقــم ‪ 32308699‬وتاريــخ ‪ 1432/07/25‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 32944147‬وتاريــخ ‪ 1432/07/25‬ه ـ ففــي يــوم‬\n‫االثنــن املوافــق‪ 1433/01/17‬ه ـ حضــر‪ ...‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم بالوكالــة الصــادرة مــن كتابــة عــدل اخلبــر الثانيــة‬\n‫برقــم ‪ 19367‬يف ‪1432/6/11‬ه ـ جلــد ‪ 2843‬عــن‪ ...‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم بصفتــه شــريكا يف شــركة ‪ ...‬ملعــدات‬\n‫األمــن والســامة والتجــارة احملــدودة وبصفتــه وكيــا عــن شــريكه‬\n‫‪ ...‬وحضــر حلضــوره‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫ويف هــذه اجللســة قــال محــررا دعــواه لقــد كان املدعــى عليــه يعمــل يف‬\n‫شــركة موكلــي قائــد طاقــم نقــل أمــوال خاصــة بالبنــوك ويف تاريــخ‬\n‫‪1428/12/23‬ه ـ كلــف ومعــه زميلــن همــا الســائق وناقــل األكيــاس‬\n\n                                                                                         ‫‪314‬‬\n\f      ‫بنقــل ثمانيــة أكيــاس ســلمت بعهــدة املدعــى عليــه إليصالهــا إلــى‬\n      ‫اخلزينــة الرئيســية ملصــرف ‪ ...‬بالدمــام وقــد قــام املدعــى عليــه وزمــاءه‬\n      ‫وســلموا ســبعة أكيــاس كاملــه وادعــى املدعــى عليــه أنــه ســلم الكيس‬\n      ‫الثامــن للموظــف ويعمــل يف اخلزينــة الرئيســية ملصــرف ‪ ...‬وأنــه جحــده‬\n      ‫وقــد كان يف هــذا الكيــس ثالثــة ماليــن وثالثمائــة وخمســون ألــف‬\n      ‫ريــال ( ‪ ) 3.350.000‬كمــا يدعــي املدعــى عليــه أن قبــض منــه هــذا‬\n      ‫املبلــغ ورفــض تســليمه ســندا بذلــك وقــد حقــق يف هــذا األمــر بتحقيــق‬\n      ‫جنائــي ثبــت مــن خاللــه كــذب املدعــى عليــه وأن املبلــغ املفقــود حتــت‬\n      ‫مســؤوليته وال يــزال يف عهدتــه وقــد ســجن بســبب هــذه القضيــة أكثــر‬\n      ‫مــن أربــع ســنوات وال يــزال فيــه وألن شــركة موكلــي مؤمتنــه علــى هــذا‬\n      ‫املبلــغ وقــد غرمتــه ملصــرف ‪ ...‬وســددته لهــا فإنــا نطلــب إلــزام املدعــى‬\n      ‫عليــه بتســليم ثالثــة ماليــن وثالثمائــة وخمســن ألــف ريــال دون تأخيــر‬\n      ‫هــذه دعــواي وبســؤال املدعــى عليــه عــن هــذه الدعــوى قــال مــا ذكــره‬\n      ‫املدعــي مــن أنــي أعمــل يف شــركة موكليــه قائــد طقــم نقــل أمــوال وأن‬\n      ‫معــي الزميلــن املذكوريــن واســتلمنا ثمانيــة أكيــاس نقــود مــن فــروع‬\n      ‫مصــرف ‪ ...‬لتســليمها إلــى اخلزينــة الرئيســية فصحيــح ولقــد ســلمناها‬\n      ‫كاملــة إال أن القائمــن علــى اخلزينــة أعطونــا مــا يثبــت اســتالم ســبعة‬\n      ‫أكيــاس أمــا الكيــس الثامــن واحملتــوي علــى ثالثــة ماليــن وثالثمائــة‬\n      ‫وخمســن ألف ريال فقد اســتلموه وســألوني عن ســنده فذكرت أنه يف‬\n      ‫ســيارة نقــل األمــوال وبعــد إحضــار الســند أنكــروا اســتالمهم للكيــس‬\n      ‫الثامــن املذكــور وأنهــم فتحــوه ولــذا علــى املدعــي مطالبتــه املســؤولني‬\n      ‫عــن اخلزانــة وقــد بلغنــا الســلطات وكان املتعــن علــى ‪ ...‬مســؤول اخلزينــة‬\n      ‫أن ال يتــرك املوقــع حتــى يتحقــق منــه ولعلــه اســتولى علــى املبالــغ التــي‬\n\n\n‫‪315‬‬\n\f‫يف الكيــس الثامــن وتصــرف فيهــا ولذلــك ال أوافــق علــى طلــب املدعــي‬\n‫ألنــي لــم أفــرط وأنــا ســجني بســبب هــذه القضيــة مــدة أربــع ســنوات هــذه‬\n‫إجابتــي ثــم يف جلســة ثانيــة ســألت املدعــى عليــه عمــا ذكــره املدعــي مــن‬\n‫أن الشــركة التــي ميثلهــا ســلمت املبلــغ محــل الدعــوى لشــركة ‪ ...‬وهــل‬\n‫كان مؤمنــا عليــه مــن إحــدى شــركات التأمــن فقــال ال أعلــم عــن ذلــك‬\n‫شــيئا وأطلــب التأكــد مــن اجلهــة املختصــة أمــا املدعــي وكالــة فقــال‬\n‫لقــد حســم هــذا املبلــغ محــل الدعــوى مــن مســتحقاتنا التــي لــدى شــركة‬\n‫‪ ...‬وهنــاك بوليصــة تأمــن مــن الشــركة ‪ .....‬للتأمــن ‪ ....‬علــى األمــوال‬\n‫التــي ننقلهــا ولــم نســتلم مــن الشــركة املذكــورة شــيئا عــن املبلــغ محــل‬\n‫الدعــوى ألســباب تتعلــق بحجــم املطالبــة الســنوية التــي تضمــن بحدودهــا‬\n‫الشــركة املذكــورة هكــذا أفــاد الطرفــان ثــم يف جلســة ثالثــة ســألت‬\n‫املدعــي إن كانــت الشــركة التــي ميثلهــا قــد اســتلمت أي تعويــض مــن‬\n‫شــركة التأمــن عــن املبالــغ املختلســة فقــال لــم نســتلم أي تعويــض ال‬\n‫مــن شــركة التأمــن وال مــن غيرهــا ونطلــب احلكــم علــى املدعــى عليــه‬\n‫مكتفــن مبــا يف املعاملــة مــن بينــات وليــس لدينــا إضافــة هكــذا قــرر‬\n‫املدعــي وكالــة أمــا املدعــى عليــه فقــال أطلــب كــف املدعــي عنــي فأنــا‬\n‫ســجني مظلــوم ولــم أســرق أو اختلــس شــيئا هكــذا أجــاب املدعــى عليــه‬\n‫ثــم يف يــوم األربعــاء ‪1434 /3 /18‬ه ـ حضــر املدعــي وكالــه الســعودي‬\n‫بالســجل املدنــي رقــم بالوكالــة الصــادرة مــن كتابــة عــدل اخلبــر الثانيــة‬\n‫برقــم ‪ 35070‬يف ‪1432 /11 /4‬ه ـ جلــد ‪ 3000‬عــن ‪.....‬بصفتــه شــريك‬\n‫يف شــركة ‪ ...‬ملعــدات األمــن والســامة والتجــارة وبصفتــه وكيــا عــن‬\n‫شــريكه وحضــر حلضــوره املدعــى عليــه فتــم االطــاع ســعادة وكيــل‬\n‫أمــارة املنطقــة الشــرقية رقــم ‪ 28755‬يف ‪1433 /6 /14‬ه ـ ويتضمــن أن‬\n\n\n                                                                                    ‫‪316‬‬\n\f      ‫شــركة التأمــن لــم تعــوض الشــركة املدعيــة بــأي تعويــض ألنهــم لــم‬\n      ‫يتقدمــوا بــأي مطالبــة بهــذا الشــأن انتهــى وبتأمــل اوراق املعاملــة وجــد‬\n      ‫منهــا القــرار الصــادر مــن احملكمــة اجلزئيــة بالدمــام برقــم ‪ /3 /1‬يف‬\n      ‫‪1430 /1 /3‬ه ـ ومضمونــه احلكــم بتوجيــه التهمــة يف حــق املدعــى عليــه‬\n      ‫يف التفريــط بحفــظ األمانــة املوكلــة إليــه واالكتفــاء مبــا أمضــاه مــن‬\n      ‫مــدة إيقــاف بســبب هــذه القضيــة وهــي ســنتان وتســعة أشــهر وســبعه‬\n      ‫وعشــرون يومــا للحــق العــام وقــد قنــع املدعــى عليــه بهــذا احلكــم وكان‬\n      ‫ممــا جــاء يف احلكــم أن كاميــرات التصويــر يف اخلزانــة لــم ترصد ســوى‬\n      ‫ســبعة أكيــاس كمــا جــاء فيــه شــهادات للعاملــن تبــن اختــاف إفــادة‬\n      ‫املدعــى عليــه وزميليــه وبعــرض ذلــك علــى املدعــى عليــه قــال الظاهــر‬\n      ‫أن العاملــن يف اخلزينــة الرئيســية حرفــوا يف الكاميــرات لتوريطــي‬\n      ‫وأمــا اتهــام زميلــي لــي بســبب وعــد احملقــق لهمــا بإطــاق ســراحهما‬\n      ‫إذا شــهدا ضــدي فطلبــت مــن املدعــى عليــه تقــدمي بينــة علــى أنــه ســلم‬\n      ‫الكيــس الثامــن مبــا فيــه مــن مبالــغ مذكــورة يف الدعــوى إلــى اخلزينــة‬\n      ‫الرئيســية فقــال النظــام مينــع أن يدخــل معــي اخلزينــة أحــد حتــى زمالئــي‬\n      ‫بــل أدخــل أنــا قائــد الطاقــم ومعــي األمــوال واســلمها واســتلم وصــا بهــا‬\n      ‫وقــد ســلمت جميــع األكيــاس مبــا فيهــا الكيــس الثامــن ولــم يســلم‬\n      ‫لــي إال ســندا باســتالم ســبعة أكيــاس فقــط وليــس لــدي بينــة علــى‬\n      ‫ذلــك وبتأمــل مــا ســبق ضبطــه تبــن أن املدعــى عليــه أقــر مبــا جــاء يف‬\n      ‫الدعــوى مــن أنــه يعمــل يف شــركة ‪ ...‬وأنــه قائــد طقــم نقــل األمــوال‬\n      ‫وأنــه اســتلم ومعــه زميلــن لــه ثمانيــة أكيــاس نقــود مــن فــرع مصــرف‬\n      ‫‪ ...‬لتســليمها إلــى اخلزينــة الرئيســية وأنــه ســلم األكيــاس للقائمــن علــى‬\n      ‫اخلزينــة وأنهــم لــم يســلموه إال ســند اســتالم ســبعة أكيــاس كمــا أقــر‬\n\n\n‫‪317‬‬\n\f‫بــأن الكيــس الثامــن الــذي لــم يســتلم مــن القائمــن ســندا باســتالمه‬\n‫كان يحتــوي علــى ثالثــة ماليــن وثالثمائــة وخمســن ألــف ريــال وقــد‬\n‫قــرر املدعــى عليــه صراحــة أنــه اســتلم هــذا الكيــس مبــا فيــه مــن مبالــغ‬\n‫مــن مصــرف ‪ ...‬وســلمه للخزينــة الرئيســية ولــم يســتلم ســندا بذلــك وألن‬\n‫تصرفــه هــذا وهــو قائــد الطاقــم مخالــف ملــا جــرى عليــه العمــل يف عــدم‬\n‫تســليم النقــود ولــو كانــت قليلــة إال بســند اســتالم ولقــول النبــي صلــى‬\n‫اهلل عليــه وســلم ( علــى اليــد مــا أخــذت حتــى تؤديــه ) وألن املتعــن علــى‬\n‫املدعــى عليــه أن يســلم جميــع املبالــغ التــي اســتلمها إلــى مــن طلــب منــه‬\n‫تســليمها إليــه ويحصــل علــى مــا يثبــت ذلــك ولذلــك ثبــت لــدي بإقــرار‬\n‫املدعــى عليــه اســتالمه للكيــس الثامــن احملتــوي علــى ثالثــة ماليــن‬\n‫وثالثمائــة وخمســن ألــف ريــال مــن فــرع مصــرف ‪ ...‬ولــم يثبــت لــي أنــه‬\n‫ســلمه للخزينــة الرئيســية وحكمــت عليــه أن يســلم للشــركة املدعيــة‬\n‫ثالثــة ماليــن وثالثمائــة وخمســن ألــف ريــال وبعــرض احلكــم علــى‬\n‫الطرفــن قنــع بــه املدعــي واعتــرض عليــه املدعــى عليــه فأفهــم بأنــه‬\n‫سيســلم صــورة مــن احلكــم وميكــن مــن االعتــراض عليــه وان مــدة‬\n‫االعتــراض ثالثــون يومــا ســتبدأ بعــد تســلمه لصــورة احلكــم وأن عليــه‬\n‫أن يقــدم الئحتــه االعتراضيــة خــال تلــك املــدة وأنــه ان مضــت دون أن‬\n‫يقــدم الئحتــه االعتراضيــة فــإن حقــه يف االســتئناف والتمييــز يســقط‬\n‫ويصبــح احلكــم قطعيــا يف حقــه دون متييــز ففهــم ذلــك وصلــى اهلل علــى‬\n   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434 /03 /18‬ه ـ ‪.‬‬\n\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34343519‬وتاريــخ‬\n                                                ‫‪1434/1/11‬هـ‪.‬‬\n\n\n                                                                                     ‫‪318‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":313,"source_page_end":318,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0ae26d635d989bbace3448446b84a8c09dd9e16614d82da9f6e3dc840ad23d7b","normalized_text_hash":"cf68e21e379f55e8219f89406da83f17630f218a410e7618955bc4b375b29e9b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p313-34167155"},{"id":"dd89a9c7-84c8-507b-8aa0-438fff82826c","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مختلس -مطالبة برد مختلس -اختاس مبلغ مالي عن طريق خيانة األمانة -جواز وقف خدمات املدعى عليه لعدم احلضور للمحكمة -عدم قبول الرجوع عن اإلقرار بحق آلدمي -ثبوت","document_number":"34260802","case_number":"32385413","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/5","year":"1434","subject":"رد مختلس -مطالبة برد مختلس -اختاس مبلغ مالي عن طريق خيانة األمانة -جواز وقف خدمات املدعى عليه لعدم احلضور للمحكمة -عدم قبول الرجوع عن اإلقرار بحق آلدمي -ثبوت","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/7/5 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34260802 :‬‬\n                         ‫َر ْق ُم الدعوى‪32385413 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34307628‬تاريخه‪1434/8/28:‬هـ‬\n\n\n      ‫رد مختلــس ‪ -‬مطالبــة بــرد مختلــس‪ -‬اختــاس مبلــغ مالــي عــن طريــق‬\n      ‫خيانــة األمانــة ‪ -‬جــواز وقــف خدمــات املدعــى عليــه لعــدم احلضــور‬\n      ‫للمحكمــة ‪ -‬عــدم قبــول الرجــوع عــن اإلقــرار بحــق آلدمــي ‪ -‬ثبــوت‬\n                                                                    ‫الدعــوى ‪.‬‬\n\n\n\n      ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعد العدالة يف تســبيب‬\n                                                                          ‫حكمه ‪.‬‬\n\n\n\n      ‫ادعــى وكيــل املدعيــة بــأن املدعــى عليــه األول قــام بالتعــاون مــع الثانــي‬\n      ‫والثالــث باختــاس مبالــغ ماليــة من موكلته َّإبان عمله لديها كمندوب‬\n      ‫مبيعــات ؛ وطلــب إلزامهــم بدفــع املبالــغ املختلســة إلــى موكلتــه ‪ -‬أنكــر‬\n      ‫املدعــى عليهــم الدعــوى جملــة وتفصيــا ‪ -‬إال أن املدعــى عليــه األول لــه‬\n      ‫إقــرار بثبــوت املبلــغ املدعــى بــه يف ذمتــه وقــد أقــر بصــدوره منــه إال أنــه‬\n      ‫رجــع عنــه أمــام احملكمــة بدعــوى اإلكــراه ‪ -‬قضــت احملكمــة بإلــزام‬\n      ‫املدعــى عليــه األول بتســليم املدعيــة املبلــغ املدعــى بــه وصرفــت النظــر‬\n      ‫عــن باقــي طلبــات املدعيــة ‪ -‬قنعــت املدعيــة واملدعــى عليهمــا الثانــي‬\n      ‫والثالــث باحلكــم وعــارض عليــه املدعــى عليــه األول ‪ -‬قــررت محكمــة‬\n                                                  ‫االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n‫‪319‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضي يف احملكمــة العامة مبحافظة‬\n‫جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫مبحافظة جدة‪ ... /‬املساعد برقم ‪ 32385413‬وتاريخ ‪1432/08/30‬هـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 321104744‬وتاريــخ ‪1432/08/25‬ه ـ ففــي‬\n‫يــوم االثنــن ‪1433/11/08‬ه ـ افتتحــت اجللســة يف الســاعة احلادية عشــرة‬\n‫والنصــف وفيهــا حضــر‪ ........./‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪.....‬بصفتــه وكيــا عــن ‪ ...‬بصــك الوكالــة ذي الرقــم ‪61968‬‬\n‫والتاريــخ ‪1432/07/05‬ه ـ اجللــد ‪10811‬الصــادر مــن كتابــة العــدل‬\n‫الثانيــة شــمال محافظــة جــدة كمــا حضــر حلضــوره ‪.....‬مصــري اجلنســية‬\n‫مســلم الديانــة مبوجــب رخصــة اإلقامــة رقــم‪ .....‬كمــا حضــر ‪.....‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم‪ .....‬بصفتــه وكيــا عــن‪ .....‬بصــك‬\n‫الوكالــة ذي الرقــم ‪ 33359134‬والتاريــخ ‪1433/11/08‬ه ـ الصادر من‬\n‫كتابــة العــدل الثانيــة شــمال محافظــة جــدة كمــا حضــر ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم وقــد حــرر املدعــي دعــواه وقدمهــا‬\n‫مــن ثــاث ورقــات وهــي حتتــاج إلــى رصــد وأرفقــت باملعاملــة وبعرضــه‬\n‫علــى املدعــى عليهــم أجابــوا قائلــن نطلــب اإلمهــال إلحضــار إجابتنــا لــذا‬\n‫أجيبــوا لطلبهــم وأمهلــوا واختتمــت اجللســة ثــم يف يــوم األحــد‬\n‫‪1433/12/26‬ه ـ افتتحــت اجللســة يف الســاعة التاســعة والربــع فيهــا‬\n‫حضــر املدعــي وكالــة املثبتــة هويتــه ووكالتــه كمــا حضــر حلضــوره‬\n‫املدعــى عليــه أصالــة املثبتــة هويتــه ســابقا كمــا حضــر ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم بصفتــه وكيــا عــن بصــك الوكالــة ذي‬\n\n                                                                                        ‫‪320‬‬\n\f      ‫الرقــم ‪ 33356766‬والتاريــخ ‪1433/11/03‬ه ـ الصــادر مــن كتابــة‬\n      ‫العــدل الثانيــة شــمال محافظــة جــدة ولــم يحضــر املدعــى عليــه الثانــي‬\n      ‫ونــص دعــوى املدعــي ‪ ( :‬اقــدم دعــواي هــذه ضــد التاليــة أســماءهم‬\n      ‫مجتمعــن ومنفرديــن وهــم ‪ /1:‬املدعــى عليــه األول ‪ /2‬املدعــى عليــه‬\n      ‫الثانــي ‪ /3‬املدعــى عليــه الثالــث وموضــوع الدعــوى بتفصيــل مــا يلــي ‪:‬‬\n      ‫ســبق وان عمــل املدعــى عليــه األول ‪ ....‬لــدى مؤسســة موكلــي مطابــع ‪....‬‬\n      ‫احلديثــة مبهنــة منــدوب مبيعــات بتاريــخ ‪2003/1/1‬م براتــب شــهري‬\n      ‫وقــدره ‪ 3000‬ريــال وعمولــة وتنحصــر مهامــه الوظيفيــة يف مقابلــة‬\n      ‫العمــاء باخلــارج ويقــوم بإحضــار الطلبيــات منهــم والقيــام مبتابعتهــا‬\n      ‫وبتنفيذهــا داخــل املطبعــة وتســليمها لهــم واســتالم املبالــغ املاليــة مقابــل‬\n      ‫العمليــات املنفــذة إن كانــت نقــد ًا أو بشــيكات ويقــوم بتوريــد املبالــغ‬\n      ‫احملصلــة أو ًال بــأول إلــى قســم احلســابات باملطبعــة إال انــه يف الفتــرة‬\n      ‫األخيــرة و التــي تبــدأ مــن النصــف األول مــن عــام ‪2011‬م لــم يقــم‬\n      ‫باالنتظــام يف ســداد الفواتيــر احملصلــة مــن العمــاء األمــر الــذي ترتــب‬\n      ‫عليــه عجــوزات يف حســاب عمالئــه وتراكمــت ديــون الزبائــن املنضويــة‬\n      ‫حتــت مســئوليته حيــث ال يوجــد ســداد للفواتيــر التــي ســلمها والتــي مــر‬\n      ‫عليهــا مــدد طويلــة حتــى بلغــت إجمالــي املديونيــة علــى زبائــن املذكــور‬\n      ‫‪ 1198150‬ريــال ( مليــون ومائــة وثمانيــة وتســعون ألــف ومائــة وخمســون‬\n      ‫ريــال ) منهــا ‪ 70570‬ريــال علــى الســادة ‪ /‬البنــك ‪ ...‬وقــد صــدر بذلــك‬\n      ‫تقريــر احملاســب القانونــي محاســبون قانونيــون( مرفــق لفضيلتكــم‬\n      ‫تقريــر احملاســب القانونــي بالفواتيــر واملســتندات وبالبحــث والتحــري‬\n      ‫اكتشــفت إدارة املطبعــة أن املذكــور اخــل بــكل الواجبــات والقيــم‬\n      ‫املطلــوب توافرهــا يف كل مســلم يراعــي ربــه ودينــه حيــث قــام باالتــي ‪:‬‬\n\n\n‫‪321‬‬\n\f‫‪ /1‬اســتالم فواتيــر البيــع املوجهــة مــن املطبعــة للزبائــن واســتالم‬\n‫املطبوعــات لتســلمها ‪ /2 .‬عمــل فواتيــر مطبوعــات مــن مؤسســة كفيلــه‬\n‫املدعــى عليــه الثانــي تقابــل نفــس فواتيــر مطبعتنــا وتســليمها للزبــون‬\n‫بــد ًال مــن فواتيــر ‪ /3 ....‬االتفــاق مــع املدعــى عليــه الثالــث علــى اســتالم‬\n‫املطبوعــات يف مــكان يقــع مبنطقــة الشــرفية بجــدة حيــث يتولــى‬\n‫تســليمها للعمــاء مــع الفواتيــر الغيــر حقيقيــة املســتبدلة بفواتيــر املدعــى‬\n‫عليــه الثانــي‪ /4 .‬اســتالم قيمــة املطبوعــات مــن الزبائــن وعــدم توريدهــا‬\n‫حلســابات املطبعــة ‪ /5 .‬ســداد بعــض دفعــات نقديــة صغيــرة للتمويــه بــأن‬\n‫هنالــك ســداد مــن بعــض الزبائــن ‪ .‬وقــد واجهنــا املدعــى عليــه الثالــث‬\n‫الــذي اقــر بــكل التفاصيــل أمــام شــرطة الكنــدرة مبوجــب احملضــر‬\n‫الرســمي املرفــق باملعاملــة‪ .‬وعلــى الفــور قمنــا باالتصــال علــى املدعــى‬\n‫عليــه الثانــي وحضــر إلــى املطبعــة ومعــه املدعــى عليــه األول وتعهــد بــأن‬\n‫ينهي هذا املوضوع على مســئوليته بشــهادة احلاضرين الســيد ‪ /‬والســيد‬\n‫‪ /‬ووعــد بحــل املوضــوع وكنــا ال نعلــم حقيقــة التعــاون بــن االثنــن ثــم‬\n‫فوجئنــا يف اليــوم الثانــي مــن حضــور الكفيــل والتزامــه بأنــه قــد قــام‬\n‫بعمــل خــروج وعــودة للمذكــور وســاعده بالهــرب حيــث انهــى كل‬\n‫متعلقاتــه الشــخصية يف ســاعات قليلــة لنكشــف ان املدعــى عليــه االول‬\n‫اخلــى ســكنه وســافر الــى مصــر بعــد ان اســتولى علــى امــوال املطبعــة‪.‬‬\n‫وبعــد اكتشــافنا لهــرب املنــدوب قمنــا مبقابلــة املســئولني بالبنــك ‪...‬‬\n‫ملراجعــة حســابنا معهــم فاقــروا بعــدم اســتالمهم ألي فواتيــر بيــع تخــص‬\n‫مطابــع ‪ ...‬وامنــا كانــت الفواتيــر علــى مطبوعــات مؤسســة ‪ ...‬واطلعنــا‬\n‫املســئولني يف البنــك ‪ ...‬علــى عينــات مــن املطبوعــات التــي متــت مبطابعنــا‬\n‫فاكــدوا انهــا نفــس املطبوعــات التــي مت اســتالمها مــن مؤسســة ‪...‬‬\n\n\n                                                                                        ‫‪322‬‬\n\f      ‫والعائــدة ملكيتهــا للمدعــى عليــه الثانــي‪ .‬وحتــى نقطــع الشــك باليقــن‬\n      ‫وللتأكــد مــن ســامة ارصــدة باقــي الزبائــن بدفاترنــا ارســلنا مندوبينــا‬\n      ‫بخطابــات لزبائــن املدعــى عليــه االول للحصــول منهــم علــى مصادقــات‬\n      ‫بصحــة االرصــدة فلــم جنــد ملطابــع ‪ ...‬لدى بعضهم اثر محاســبي واخرون‬\n      ‫افــادوا بســداد مــا عليهــم للمنــدوب ‪ ...‬الهــارب‪ .‬واالن البينــة الصحيحــة‬\n      ‫القاطعــة احلاســمة يف هــذه املطالبــة العادلــة هــي اقــرار املدعــى عليــه‬\n      ‫االول ‪ ...‬بــأن ملوكلــي بذمتــه كامــل املبلــغ املطالــب بــه ‪ 1198150‬ريــال‬\n      ‫مبوجــب اقــراره املرفــق ‪ ،‬ملــا تقــدم اطلــب‪ :‬احلكــم بالــزام املدعــى عليهــم‬\n      ‫الثالثــة مجتمعــن او منفرديــن بدفــع كامــل املبالــغ الــوارد بتقديــر‬\n      ‫احملاســب القانونــي مبليــون ومئــة وثمانيــة وتســعون الــف ومائــة وخمســون‬\n      ‫ريــال احلكــم بإلــزام املدعــى عليهــم الثالثــة بدفــع قيمــة االضــرار املاديــة‬\n      ‫جــراء هــذه القضيــة احالــة املدعــى عليهــم الثالثــة للمدعــي العــام لينالــوا‬\n      ‫عقابهــم الشــرعي جــراء هــذه اجلرميــة ) ا‪.‬ه ـ نقــل نصــا وبســؤال املدعــى‬\n      ‫عليــه ‪ ....‬وكالــة اإلجابــة أجــاب قائــا مــا ذكــره املدعــي وكالــة غيــر‬\n      ‫صحيــح جملــة وتفصيــا وموكلــي يعمــل ناقــا للبضاعــة فقــط وال‬\n      ‫عالقــة لــه بالفواتيــر وأطلــب رد دعــواه وإخــاء ســبيل موكلــي مــن هــذه‬\n      ‫الدعــوى هكــذا أجــاب وقــد قــدم وكيــل املدعــى عليــه األول مذكــرة‬\n      ‫وأرفقــت باملعاملــة ورصــد مضمونهــا وبســؤال املدعــى عليــه الثالــث‬\n      ‫اإلجابــة أجــاب قائــا مــا ذكــره املدعــي غيــر صحيــح جملــة وتفصيــا‬\n      ‫وأطلــب رد دعــواه وإخــاء ســبيل موكلــي مــن هــذه الدعــوى هكــذا‬\n      ‫أجــاب وقــدم املدعــى عليــه الثالــث مذكــرة وأرفقــت باملعاملــة ورصــد‬\n      ‫مضمونهــا والنتهــاء وقــت اجللســة رفعــت اجللســة واختتمــت اجللســة ثــم يف‬\n      ‫يــوم الثالثــاء ‪1434/02/05‬ه ـ افتتحــت اجللســة يف الســاعة العاشــرة‬\n\n\n‫‪323‬‬\n\f‫والربــع فيهــا حضــر املدعــي وكالــة املثبتــة هويتــه ووكالتــه كمــا‬\n‫حضــر حلضــوره املدعــى عليــه أصالــة املثبتــة هويتــه ســابقا كمــا حضــر‬\n‫املدعــى عليــه وكالــة ‪ ...‬املثبتــة هويتــه ووكالتــه ســابقا كمــا حضــر‬\n‫مصــري اجلنســية مســلم الديانــة مبوجــب رخصــة اإلقامــة رقــم وبســؤال‬\n‫املدعــى عليــه الثانــي عــن دعــوى املدعــي أجــاب قائــا إجابتــي مكتوبــة‬\n‫علــى ذاكــرة إلكترونيــة أطلــب رصــد نصهــا لــذا أجيــب لطلبــه ونصهــا‪:‬‬\n‫(نفيــد فضيلتكــم بــأن مــا أدعــت بــه املدعيــة مطابــع ‪ ...‬ليــس بصحيــح‬\n‫والصحيــح اآلتــي ذكــره ‪ -:‬أو ًال ‪ :‬أن موكلــي يف األصــل ليــس علــى‬\n‫كفالــة املدعيــة وأن تعاملــه كان مــن خــال اتفــاق شــفهي بــأن يكــون‬\n‫مندوب ـ ًا عــن املدعيــة لبعــض عمالئهــا وذلــك بعلــم وموافقــة كفيلــه ‪.‬‬\n‫ثاني ـ ًا ‪ :‬أن عمــل موكلــي كان ينحصــر يف إحضــار أوامــر التنفيــذ‬\n‫خلمســة عمــاء علــى ســبيل احلصــر وهــم البنــك ‪ ...‬وبنــك ‪ ...‬وشــركة‪)...‬‬\n‫وشــركة ‪ ...‬لألدويــة وشــركة ‪ ...‬ويتــم تســليمها للمدعيــة وأمــا عــن‬\n‫طريقــة الســداد فيتــم إمــا عــن طريــق حتويــل مــن حســاب العميــل بنــك ‪...‬‬\n‫وبنــك ‪ ...‬إلــى حســاب املدعيــة وأمــا باقــي العمــاء عــن طريــق شــيكات‬\n‫محــررة باســم املدعيــة ولــم يكــن هنــاك اســتالم مبالــغ نقديــة اســتلمها‬\n‫موكلــي ‪ ،‬إلــى أن تــرك موكلــي العمــل‪ .‬ثالث ـ ًا ‪ :‬لقــد قــام موكلــي‬\n‫مبراجعــة العمــاء املذكوريــن لالستفســار عــن أي مديونيــات متأخــرة‬\n‫للمدعيــة وذلــك فيمــا يتعلــق باألوامــر املنفــذة خــال فتــرة عمــل موكلــي‬\n‫يف ذلــك الوقــت فأفــادوا بــأن املدعيــة قــد اســتلمت جميــع مســتحقاتها (‬\n‫مرفــق بيــان للبنــك ‪ ) ...‬وبعــض العمــاء كبنــك ‪ ...‬الزالــوا يف اســتمرارية‬\n‫التعامــل مــع املدعيــة مــن خــال مندوبهــا ويدعــى ‪ /‬مصــري اجلنســية (‬\n‫مرفــق ) ولفضيلتكــم مخاطبتهــم للتأكــد من صحة ذلك أو إحضارهم‬\n\n\n                                                                                   ‫‪324‬‬\n\f      ‫لســماع أقوالهــم مبــا يؤكــد بــراءة ذمــة موكلــي فيمــا يتعلــق باألوامــر‬\n      ‫املنفــذة خــال فتــرة عملــه‪ .‬رابع ـ ًا ‪ :‬عندمــا تــرك موكلــي العمــل لــدى‬\n      ‫املدعيــة قــام بالعمــل لــدى كفيلــه صاحــب مؤسســة ‪ ....‬ألدوات الدعايــة‬\n      ‫واإلعــان والتــي مــن خاللهــا مت التعامــل مــع بنــك ‪ ...‬يف أمــور فنيــة‬\n      ‫وبأوامــر مســتقلة ليــس لهــا عالقــة مبطابــع املدعيــة ولفضيلتكــم‬\n      ‫مخاطبــة البنــك ‪ ....‬للتأكــد مــن أن البنــك ‪ ...‬يتعامــل مــع جميــع املطابــع‬\n      ‫وشــركات الدعايــة واإلعــان دون حكــر علــى أحــد الشــركات ومــن‬\n      ‫ضمنهــا تعاملهــا مــع مؤسســة كفيلــي ‪ ....‬للدعايــة واإلعــان‪ .‬خامس ـ ًا ‪:‬‬\n      ‫اإلقــرار املذيــل بتوقيــع موكلــي ال ميثــل حقيقــة التعامــل وذلــك إلرغامــه‬\n      ‫وإكراهــه بكتابتــه وتوقيعــه مــن قبــل املدعيــة مبقرهــا ( مطابــع ‪...‬‬\n      ‫احلديثــة ) والدليــل علــى ذلــك مــا ذكــر يف مــن اإلقــرار بــأن مــدة عملــه‬\n      ‫عشــرة ســنني والصحيــح ثمانيــة أعــوام كمــا أن طبيعــة عمــل موكلــي‬\n      ‫إحضــار أوامــر تنفيــذ وليــس بيــع وحتصيــل كمــا هــو مذكــور يف‬\n      ‫اإلقــرار كمــا أن املبلــغ املذكــور يف اإلقــرار هــو مــن صنــع املدعيــة ألن‬\n      ‫جميــع املبالــغ املســتحقة للمدعيــة للعمــاء املذكوريــن قــد مت ســدادها‬\n      ‫كمــا أن التاريــخ املذكــور يف اإلقــرار يف ‪1423/9/5‬ه ـ أي منــذ مــا‬\n      ‫يقــارب عشــرة أعــوام أي قبــل تعامــل موكلــي مــع املدعيــة بعامــن تقريبـ ًا‬\n      ‫وهــذه املعلومــات املغلوطــة دليــل قاطــع علــى عــدم صحتــه سادس ـ ًا ‪:‬‬\n      ‫ذكــرت املدعيــة يف دعواهــا بــأن ‪ ....‬للتنميــة قــد حــول علــى حســاب‬\n      ‫مؤسســة كفيــل موكلــي مبلــغ وقــدره ‪ 750000‬ريــال يف عــام ‪ 2011‬م‬\n      ‫وهــذا ليــس بصحيــح حيــث أن التعامــل الفعلــي الــذي مت بــن مؤسســة‬\n      ‫كفيــل موكلــي والبنــك ‪ ...‬لعــام ‪2011‬م مبلــغ وقــدره ‪ 200000‬ريــال‬\n      ‫لعمــل لوحــات ومطبوعــات ليســت لهــا عالقــة مبطابــع املدعيــة ( مرفــق )‪.‬‬\n\n\n‫‪325‬‬\n\f‫ســابع ًا ‪ :‬نــود أن نوضــح لفضيلتكــم مــا ذكرتــه املدعيــة يف دعواهــا بــأن‬\n‫كفيــل موكلــي قــد هــرب موكلــي بتأشــيرة خــروج وعــودة وســاعده‬\n‫بالهــرب بعــد أن أنهــى كل متعلقاتــه الشــخصية يف ســاعات قليلــة وبــأن‬\n‫موكلــي قــد أخلــى ســكنه وســافر إلــى مصــر بعــد أن اســتولى علــى‬\n‫أمــوال املطبعــة وهــذا ليــس بصحيــح حيــث أن موكلــي قــد تــرك تعاملــه‬\n‫مــع املدعيــة بتاريــخ ‪ 2011/4/1‬م وســافر إلــى مصــر بتاريــخ‬\n‫‪2011/5/25‬م ثــم عــاد إلــى اململكــة بتاريــخ ‪2011/10/1‬م مبــا يؤكــد‬\n‫إخــاء طرفــه مــن املدعيــة وبأنــه لــم يكــن لديــه نيــة الهــروب كمــا‬\n‫زعمــت بــه املدعيــة‪ .‬ثامن ـ ًا ‪ :‬قامــت شــرطة الكنــدرة بإيقــاف خدمــات‬\n‫موكلــي وخدمــات كفيلــه املدعــى عليــه الثانــي يف هــذه الدعــوى ‪...‬‬\n‫والــذي ليــس لــه عالقــة مبوضــوع املطالبــة واملدعــى عليــه الثالــث ‪-‬‬\n‫مصــري اجلنســية ‪ -‬الــذي ليــس علــى كفالــة املدعيــة‪ .‬وبســؤال موكلــي‬\n‫شــرطة الكنــدرة عــن ســبب إيقــاف خدماتهــم أفــادوا بــأن هــذا اإلجــراء‬\n‫ـاء علــى أمــر القاضــي ‪ .‬وحيــث ال يخفــى علــى فضيلتكــم بــأن هــذا‬       ‫بنـ ً‬\n‫اإلجــراء الــذي مت مــن قبــل شــرطة الكنــدرة إذا لــم يكــن بأمــر‬\n‫فضيلتكــم يعــد إجــراء باطــل حيــث أن هذا اإلجراء ليس من اختصاص‬\n‫اجلهــات التنفيذيــة إذا كانــت املطالبــة متعلقــة بحقــوق ماليــة عليهــا نــزاع‬\n‫فتختــص بــه احملاكــم العامــة صاحبــة الواليــة العامــة يف نظــر هــذه‬\n‫القضايــا وفقــا ملقتضــى نــص (املــادة ‪ )32‬مــن نظــام املرافعــات الشــرعية‬\n‫ومــن صالحيــات قاضــي املوضــوع إذا لــم يجــد جتــاوب مــن حضــور‬\n‫املدعــى عليــه فللقاضــي أن يأمــر بوقــف خدماتــه أو بإحضــاره بالقــوة‬\n‫اجلبريــة أو مبنعــه مــن الســفر وحيــث أن إيقــاف خدمــات موكلــي‬\n‫وكفيلــه واملدعــو قــد ترتــب عليــه أضــرار مــن تعطيــل ملصاحلهــم‬\n\n\n                                                                                      ‫‪326‬‬\n\f      ‫الضروريــة مــع اجلهــات احلكوميــة ويف هــذا ضــرر وحيــث ال يخفــى علــى‬\n      ‫فضيلتكــم بــأن ديننــا احلنيــف قــد نهــى عــن الضــرر لقولــه صلــى اهلل‬\n      ‫عليــه وســلم ‪ ( :‬ال ضــرر وال ضــرار ) ومنهــا القاعــدة الشــرعية ( الضــرر‬\n      ‫يــزال ) وملــا ذكــر يتضــح لفضيلتكــم كيديــة دعــوى املدعيــة‪ .‬لــذا‬\n      ‫أطلــب مــن فضيلتكــم اآلتــي ‪ /1 - :‬مخاطبــة شــرطة الكنــدرة برفــع‬\n      ‫اإليقــاف عــن خدمــات موكلــي ورفقــاؤه ‪ /2 .‬رد دعــوى املدعيــة مــع‬\n      ‫إلزامهــا بدفــع أتعــاب محامــاة مبلــغ وقــدره ‪ 30000‬ريــال‪ .‬مــع تعزيــر‬\n      ‫املدعيــة وفق ـ ًا ملــا ورد يف الالئحــة التنفيذيــة لنظــام املرافعــات الشــرعية‬\n      ‫للمــادة (‪)4‬الفقــرة اخلامســة « إذا ثبــت لناظــر القضيــة أن دعــوى املدعــي‬\n      ‫كيديــة حكــم بــرد الدعــوى ولــه احلكــم بتعزيــر املدعــي مبــا يردعــه «‬\n      ‫) ا‪.‬ه ـ نقــل نصــا وبســؤال املدعــي عــن هــذه الدعــوى أجــاب قائــا أنا على‬\n      ‫مــا ذكرتــه هكــذا أجــاب وبســؤال املدعــي وكالــة البينــة علــى دعــواه‬\n      ‫أجــاب قائــا إن املدعــى عليــه ‪ ...‬ملــا قبــض عليــه أقر يف محاضر الشــرطة‬\n      ‫بأنــه اســتلم مــن البضاعــة مــن املدعــي عليــه وهــذه البضاعــة ملوكلــي‬\n      ‫كمــا أن املدعــى عليــه ‪ ...‬قــد وقــع علــى إقــرار بــأن يف ذمتــه ملوكلــي (‬\n      ‫‪) 1198150‬مليونــا ومائــة وثمانيــة وتســعني ألفــا ومائــة وخمســن ريــال‬\n      ‫وأمــا املدعــى عليــه الثالــث ‪ ...‬فقــد ذكــر بــأن األمــوال كانــت تدخــل يف‬\n      ‫حســابه هكــذا أجــاب وبســؤال املدعــي وكالــة عــن ذلــك أجــاب قائــا‬\n      ‫مــا ذكــره املدعــي مــن أن موكلــي قــد اســتلم البضاعــة مــن فصحيــح‬\n      ‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليــه ‪ ...‬أجــاب قائــا صحيــح‬\n      ‫مــا ذكــره املدعــي وكالــة مــن أنــي وقعــت علــى اإلقــرار ولكنــي وقعــت‬\n      ‫علــى اإلقــرار مكرهــا هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليــه‬\n      ‫الثالــث أجــاب قائــا مــا ذكــره املدعــي وكالــة فغيــر صحيــح هكــذا‬\n\n\n‫‪327‬‬\n\f‫أجــاب والنتهــاء وقــت اجللســة رفعــت اجللســة واختتمــت اجللســة ثــم يف يــوم‬\n‫الســبت ‪1434/06/24‬ه ـ افتتحــت اجللســة يف الســاعة التاســعة وفيهــا‬\n‫حضــر املدعــي وكالــة املثبتــة هويتــه ووكالتــه كمــا حضــر حلضــوره‬\n‫املدعــى عليــه أصالــة ‪ ...‬املثبتــة هويتــه ســابقا واملدعــى عليــه وكالــة ‪...‬‬\n‫املثبتــة هويتــه ووكالتــه ســابقا وبســؤال املدعــى عليــه ‪ ...‬عــن توقيعــه‬\n‫علــى اإلقــرار باإلكــراه أجــاب قائــا أنــا قــد ذهبــت إلــى املطبعــة وكان‬\n‫موجــودا املدعــي ‪ ...‬وشــخص آخــر وقالــوا ال بــد لــي مــن التوقيــع علــى‬\n‫اإلكــراه وأجبرونــي هكــذا أجــاب وبســؤال املدعــى عليــه ‪ ......‬مــن‬\n‫بينتــه علــى اإلكــراه أجــاب قائــا ال بينــة لــي إال موكلــي املدعــى عليــه‬\n‫يف هــذه الدعــوى هكــذا أجــاب ورفعــت اجللســة للتأمل واختتمت اجللســة‬\n‫ثــم يف يــوم األربعــاء ‪1434/07/05‬ه ـ افتتحت اجللســة يف الســاعة الثامنة‬\n‫وفيهــا حضــر املدعــي وكالــة املثبتــة هويتــه ووكالتــه كمــا حضــر‬\n‫حلضــوره املدعــى عليــه أصالــة املثبتــة هويتــه ســابقا كمــا حضــر املدعــى‬\n‫عليــه أصالــة املثبتــة هويتــه ســابقا كمــا حضــر ‪ ....‬بصفتــه وكيــا عــن‬\n‫بصــك الوكالــة ذي الرقــم ‪ 33356766‬والتاريــخ ‪1433/11/03‬ه ـ‬\n‫الصــادر مــن كتابــة العــدل الثانيــة بشــمال محافظــة جــدة وللمدعــي‬\n‫وكالــة يف الوكالــة حــق املرافعــة واملدافعــة وحضــور اجللســات وطلــب‬\n‫وتقــدمي البينــات واســتئناف األحــكام ومتييزهــا واالعتــراض عليهــا‬\n‫ولوكيــل املدعــى عليــه ‪ ...‬يف الوكالــة حــق املرافعــة واملدافعة واإلنكار‬\n‫واإلقــرار والصلــح والتنــازل وبعــد االطــاع علــى املعاملــة وجــد بهــا إقــرار‬\n‫املدعــى عليــه علــى لفــة رقــم‪ )81( :‬واملتضمــن أن املدعــى عليــه ‪ ...‬يذكــر‬\n‫أن يف ذمتــه مبلغــا وقــدره ‪ 1198150‬مليــون ومائــة وثمانيــة وتســعون ألفــا‬\n‫ومائــة وخمســون ريــاال وأنــه ســوف يقــوم بســدادها علــى دفعــات حتــى‬\n\n\n                                                                                      ‫‪328‬‬\n\f      ‫انتهــاء املبلــغ ا‪.‬ه ـ فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي واملتضمنــة‬\n      ‫طلــب املدعــي إلــزام املدعــى عليهــم الثالثــة مجتمعــن أو منفرديــن بدفــع‬\n      ‫مبلــغ وقــدره ‪ 1198150‬مليــون ومائــة وثمانيــة وتســعون ألفــا ومائــة‬\n      ‫وخمســون ريــاال ملوكلــه وإلــزام املدعــى عليهــم بدفــع قيمــة األضــرار‬\n      ‫املاديــة وإحالتهــم إلــى جهــات التحقيــق وبنــاء علــى إجابــة املدعــى عليهــم‬\n      ‫واملتضمنــة اإلنــكار وبنــاء علــى إقــرار املدعــى عليــه املرفــق باملعاملــة‬\n      ‫علــى لفــة رقــم‪ )81( :‬ومصادقتــه علــى اإلقــرار وعليــه فقــد ظهــر لــي مــا‬\n      ‫يلــي‪ :‬أوال‪ :‬ثبــوت مبلــغ وقــدره ‪ 1198150‬مليــون ومائــة وخمســون ريــاال‬\n      ‫يف ذمــة املدعــى عليــه األول للمدعــي ثانيــا‪ :‬عــدم ثبــوت مطالبــة املدعــي‬\n      ‫للمدعــى عليهــم الباقــن ثالثــا‪ :‬صــرف النظــر عــن الطلبــات الباقيــة‬\n      ‫رابعــا‪ :‬فقــد ألزمــت املدعــى عليــه بدفــع مبلــغ وقــدره‪ 1198150‬مليــون‬\n      ‫ومائــة وخمســون ريــاال للمدعــي وبــه حكمــت وبإعــان احلكــم اعتــرض‬\n      ‫املدعــى عليــه األول ‪......‬وقنــع البقيــة وأفهــم بــأن عليــه مراجعــة احملكمــة‬\n      ‫يــوم الســبت ‪1434/07/08‬ه ـ الســتالم نســخة احلكــم لتقــدمي الئحتــه‬\n      ‫االعتراضيــة وإذا فــات علــى ميعــاد االعتــراض ثالثــون يومــا ولــم يقــدم‬\n      ‫الئحتــه االعتراضيــة ســقط حقــه يف االعتــراض واكتســب احلكــم‬\n      ‫القطعيــة‪ ،‬واختتمــت اجللســة يف الســاعة الثامنــة والنصــف‪ ،‬وبــاهلل‬\n      ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                                  ‫يف ‪1434/07/05‬هـ‬\n      ‫احلمــد هلل وحــده بعــد ففــي يــوم الســبت ‪1434/07/08‬ه ـ افتتحــت‬\n      ‫اجللســة يف الســاعة الثانيــة والنصــف وفيهــا حضــر املدعــى عليــه أصالــة‬\n      ‫‪ ...‬املثبتــة هويتــه ســابقا واســتلم نســخة احلكــم وأفهــم بتعليمــات التمييــز‬\n      ‫كمــا يف اجللســة املاضيــة فتفهــم ذلــك‪ ،‬واختتمــت اجللســة ثــم يف يــوم‬\n\n\n‫‪329‬‬\n\f‫الثالثــاء ‪1434/08/02‬ه ـ افتتحــت اجللســة يف الســاعة الثانيــة والنصــف‬\n‫وفيهــا حضــر املدعــى عليــه أصالــة ‪ ...‬املثبتــة هويتــه ســابقا وقــدم‬\n‫الئحتــه االعتراضيــة املقيــدة يف احملكمــة برقــم ‪ 341870383‬وتاريــخ‬\n‫‪1434/08/02‬ه ـ واملكونــة مــن ثــاث ورقــات مبرفقاتهــا ورفعــت‬\n‫اجللســة لدراســتها ثــم يف يــوم األحــد ‪1434/08/07‬ه ـ افتتحــت اجللســة‬\n‫يف الســاعة الواحــدة والربــع وقــد مت االطــاع علــى الالئحــة االعتراضيــة‬\n‫املقدمــة مــن املدعــى عليــه املذكــور رقــم قيدهــا وتاريخــه أعــاه ولــم‬\n‫أجــد بهــا مــا يؤثــر علــى مــا حكمــت بــه لــذا قــررت رفعهــا مــع كامــل‬\n‫املعاملــة والصــك وصــورة مصدقــة مــن الضبــط بعــد إحلــاق مــا اســتجد‬\n‫علــى الصــك والســجل حملكمــة االســتئناف‪ ،‬واختتمــت اجللســة يف‬\n‫الســاعة الواحــدة والنصــف‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/08/07‬ه ـ‬\n‫احلمــد هلل وحــده‪ ،‬وبعــد‪ :‬ففــي يــوم األربعــاء ‪1434/10/07‬ه ـ افتتحــت‬\n‫اجللســة يف الســاعة الثامنــة وقــد عــادت املعاملــة مــن محكمة االســتئناف‬\n‫بالرقــم املقيــد يف احملكمــة ‪ 33996387‬وتاريــخ ‪1434/09/15‬ه ـ‬\n‫وبرفقهــا خطــاب فضيلــة رئيــس محكمــة االســتئناف مبنطقــة مكــة‬\n‫املكرمــة املكلــف ذو الرقــم ‪ 33996387‬والتاريــخ ‪1434/09/10‬ه ـ‬\n‫واملتضمــن‪ (:‬نفيدكــم أنــه جــرى تدقيــق احلكــم مــن الدائــرة احلقوقيــة‬\n‫السادســة وصــدر بشــأنه القــرار املرفــق ذو الرقــم ‪ 34307628‬والتاريــخ‬\n‫‪1434/08/28‬ه ـ املــدون علــى ظهــر الصــك نبعثــه لكــم مــع كامــل‬\n‫مشــفوعات املعاملــة إلكمــال الــازم واهلل يحفظكــم‪ .‬والســام‬\n‫عليكــم ورحمــة اهلل وبركاته)ا‪.‬ه ـ كمــا برفقهــا قــرار تصديــق رقــم‬\n‫‪ 34307628‬وتاريــخ ‪1434/08/28‬ه ـ ونصــه‪ (:‬احلمــد هلل‪ ،‬والصــاة‬\n\n\n                                                                                  ‫‪330‬‬\n\f      ‫والســام علــى رســول اهلل‪ ،‬وبعــد‪ :‬فقــد جــرى منــا نحــن رئيــس وأعضــاء‬\n      ‫الدائــرة احلقوقيــة السادســة يف محكمــة االســتئناف مبنطقــة مكــة‬\n      ‫املكرمــة االطــاع علــى هــذا احلكــم الصــادر مــن فضيلــة الشــيخ‪/‬‬\n      ‫القاضــي باحملكمــة العامــة مبحافظــة جدة واملســجل بعــدد ‪34260802‬‬\n      ‫وتاريــخ ‪1434/07/05‬ه ـ املتضمــن دعــوى ‪ ....‬ضــد ‪ ...‬مصــري اجلنســية‬\n      ‫و‪......‬مصــري اجلنســية واحملكــوم فيــه مبــا دون باطــن الصــك‪ ،‬وبدراســة‬\n      ‫احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى‬\n      ‫احلكــم‪ ،‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم‪ ،،،،‬قاضــي اســتئناف توقيعــه وختمــه قاضــي اســتئناف‬\n      ‫توقيعــه وختمــه قاضــي اســتئناف توقيعــه وختمه)ا‪.‬ه ـ لــذا جــرى إحلاقــه‪،‬‬\n      ‫واختتمــت اجللســة يف الســاعة الثامنــة والنصــف‪ ،‬وبــاهلل التوفيــق‪،‬‬\n      ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                                ‫‪1434/10/07‬ه ـ ‪.‬‬\n\n\n\n\n‫‪331‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":319,"source_page_end":331,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"395320cd73717e4a628c736995dc1c2e32140403e2f4ca00ca27ffba2267cff8","normalized_text_hash":"563d704754aa642ab74c9f5e0197d51affd5538fe2eee9e89a6b373fc654bf2a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p319-34260802"},{"id":"d4f7ec66-1150-5591-a092-07261e5f88cf","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مختلس -اختالس مبالغ مالية عن طريق خيانة األمانة -شهادة العامل لرب العمل -غياب املدعى عليه وكفيله رغم تبلغهما - إثبات بالقرائن مع مين املدعي -حلف مين االستظهار -ثبوت الدعوى -حكم حضوري.","document_number":"33474299","case_number":"32524021","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":"الدائرة اجلزائية اخلامسة مبحكمة الاستئناف مبكة املكرمة","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/21","year":"1434","subject":"رد مختلس -اختالس مبالغ مالية عن طريق خيانة األمانة -شهادة العامل لرب العمل -غياب املدعى عليه وكفيله رغم تبلغهما - إثبات بالقرائن مع مين املدعي -حلف مين االستظهار -ثبوت الدعوى -حكم حضوري.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/12/21 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33474299 :‬‬\n                    ‫َر ْق ُم الدعوى‪32524021 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 347777‬تاريخه‪1434/1/11:‬هـ‬\n\n\n ‫رد مختلس ‪ -‬اختالس مبالغ مالية عن طريق خيانة األمانة ‪ -‬شــهادة‬\n ‫العامــل لــرب العمــل ‪ -‬غيــاب املدعــى عليــه وكفيلــه رغــم تبلغهمــا ‪-‬‬\n ‫إثبــات بالقرائــن مــع ميــن املدعــي‪ -‬حلــف ميــن االســتظهار ‪ -‬ثبــوت‬\n                                             ‫الدعــوى ‪ -‬حكــم حضــوري‪.‬‬\n\n\n\n\n ‫‪ -1‬قــول النبــي صلــى اهلل عليــه وســلم‪ ( :‬مــن حلــف علــى ميــن هــو فيهــا‬\n ‫فاجــر ليقتطــع بهــا مــال امــرئ مســلم لقــي اهلل وهــو عليــه غضبــان )‪.‬‬\n                                                                    ‫رواه مســلم‪.‬‬\n   ‫‪ -2‬قول النبي صلى اهلل عليه وسلم‪( :‬ال ضرر وال ضرار )‪ .‬رواه أحمد‪.‬‬\n                               ‫‪ -3‬املادة (‪ )55‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي علــى املدعــى عليــه الغائــب عــن مجلــس احلكــم بأنــه‬\n ‫َّإبــان عملــه يف املؤسســة التــي ميتلكهــا كمنــدوب مبيعــات مت تســليمه‬\n ‫بضاعــة ليقــوم ببيعهــا وحتصيــل ثمنهــا إال أنــه قــام بعــد بيــع البضاعــة‬\n ‫املذكــورة باختــاس ثمنهــا ولــم يســلمه ‪ ،‬طلــب إلزامــه بتســليم قيمــة‬\n ‫البضاعــة املختلســة إليــه‪ -‬قــررت احملكمــة الســير يف نظــر الدعــوى‬\n ‫مــع غيــاب املدعــى عليــه لكونــه تبلــغ بالدعــوى ولــم يحضــر وطلبــت‬\n\n                                                                                   ‫‪332‬‬\n\f      ‫مــن املدعــي بيانتــه ‪ -‬فقــدم املدعــي للمحكمــة عــددا مــن القرائــن التــي‬\n      ‫تعضــد دعــواه منهــا إقــرار منســوب للمدعــى عليــه علــى ورقــة عاديــة‪،‬‬\n      ‫وتقريــر احملاســب القانونــي الــذي يثبــت وجــود العجــز ‪ ،‬كمــا أحضــر‬\n      ‫شــاهد ًا إال أن احملكمــة لــم تقبــل شــهادته لكونــه يعمــل لــدى املدعــي‪-‬‬\n      ‫قــررت احملكمــة توجيــه اليمــن إلــى املدعــي تتميمـ ًا لبينتــه فأداهــا طبق‬\n      ‫مــا طلــب منــه ‪ -‬قضــت احملكمــة حضوريـ ًا بإلــزام املدعــى عليــه بتســليم‬\n      ‫املدعــي املبلــغ املدعــى بــه ‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى‬\n                                                                            ‫احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة مبكــة‬\n      ‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة مبكــة املكرمــة برقــم ‪ 32524021‬وتاريــخ ‪ 1432/11/13‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 321439703‬وتاريــخ ‪ 1432/11/13‬ه ـ ففــي‬\n      ‫يــوم األحــد املوافــق‪ 1433/02/07‬ه ـ افتتحــت اجللســة الســاعة الثانيــة‬\n      ‫عشــرة ظهــر ًا وفيهــا حضــر ســعودي مبوجــب الســجل املدنــي رقــم بصفتــه‬\n      ‫ا عــن ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم بصفتــه‬           ‫وكي ـ ً‬\n      ‫ا عــن باألصالــة عــن نفســه وبصفتــه صاحــب مؤسســة للتجــارة‬            ‫وكي ـ ً‬\n      ‫بالســجل التجــاري رقــم يف ‪1408/6/5‬ه ـ مبوجــب الوكالــة الصــادرة‬\n      ‫مــن كتابــة العــدل الثانيــة بالريــاض برقــم ‪ 8784‬يف ‪1433/2/2‬ه ـ‬\n      ‫اجللــد ‪ 20126‬ولــه فيهــا حــق املطالبــة واملرافعــة واملدافعــة ‪...‬الــخ ولــم‬\n      ‫يحضــر املدعــى عليــه وال مــن ينــوب عنــه وقــد تبلــغ مبوعــد هــذه اجللســة‬\n      ‫حســب خطابنــا املوجــه ملديــر مركــز شــرطة الكعكيــة وقــد وردنــا‬\n\n‫‪333‬‬\n\f‫مــن مديــر شــرطة الكعكيــة اخلطــاب رقــم ‪ 35/2/ 20/287998‬يف‬\n‫‪1432/11/19‬ه ـ واملتضمــن أنــه جــرى إطــاق ســراح املدعــى عليــه‬\n‫بالكفالــة احلضوريــة ومت إفهــام الكفيــل أنــه يف حالــة عــدم إحضــاره‬\n‫ســوف تنقلــب إلــى كفالــة غــرم وأداء كمــا مت إبالغــه باملوعــد احملــدد‬\n‫أه ـ وملخاطبــة شــرطة الكعكيــة إلحضــار املدعــى عليــه أو كفيلــه‬\n‫فقــد رفعــت اجللســة ويف يــوم الثالثــاء املوافــق‪ 1433/07/08‬ه ـ افتتحــت‬\n‫اجللســة الســاعة احلاديــة عشــرة صباحـ ًا وفيهــا حضــر املدعــي وكالــة ولم‬\n‫يحضــر املدعــى عليــه وال مــن ينــوب عنــه وقــد ســبقت الكتابــة لشــرطة‬\n‫الكعكيــة مبوجــب خطابنــا رقم ‪ 331037965‬يف ‪1433/6/3‬هـ وذلك‬\n‫إلحضــار املدعــى عليــه أو كفيلــه يف وقــت مــن أوقــات الــدوام الرســمي‬\n‫فوردنــا منــه اخلطــاب رقــم ‪ 284691‬يف ‪1433/7/1‬ه ـ واملتضمــن ‪ :‬حيــث‬\n‫أنــه مت االتصــال علــى املدعــى عليــه وكفيلــه أكثــر مــن مــرة وألنهــم‬\n‫غيــر متجاوبــن يف احلضــور ومت منــا مخاطبــة البحــث اجلنائــي للقبــض‬\n‫عليهــم أ‪.‬ه ـ وإلعــادة املعاملــة لهــم مــرة أخــرى وإحضــار املدعــى عليــه أو‬\n‫كفيلــه فقــد رفعــت اجللســة ويف يــوم األحــد املوافــق‪ 1433/11/28‬ه ـ‬\n‫افتتحــت اجللســة الســاعة العاشــرة والنصــف وفيهــا حضــر املدعــي أصالة‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ولــم يحضــر املدعــى عليــه‬\n‫وال مــن ينــوب عنــه وقــد جــرى طلبــه عــن طريــق شــرطة الكعكيــة‬\n‫بخطابنــا رقــم ‪ 32439706‬يف ‪1433/7/20‬ه ـ فوردنــا منهــم اخلطــاب‬\n‫رقــم ‪ 287208‬يف ‪1433/11/9‬ه ـ واملتضمــن بأنــه جــرى طلــب كفيــل‬\n‫املذكــور املدعــو مــن قبــل مركــز شــرطة املنصــور مبوجــب كتابنــا رقم‬\n‫‪ 286571‬يف ‪1433/10/9‬ه ـ فوردنــا إفادتهــم بالكتــاب رقــم ‪368595‬‬\n‫يف ‪1433/10/22‬ه ـ املتضمــن بأنــه بالبحــث عــن مقــر ســكنه لــم يعثــر‬\n\n\n                                                                                    ‫‪334‬‬\n\f      ‫عليــه ولــم يتمكنــوا مــن إبالغــه كمــا جــرى إيقــاف خدمــات الكفيــل‬\n      ‫املدعــو واملكفــول املولــي مصــري اجلنســية كمــا يتضــح لفضيلتكــم‬\n      ‫مــن طيــه أه ـ وبنــاء علــى املــادة اخلامســة واخلمســن مــن نظــام املرافعــات‬\n      ‫الشــرعية فقــد قــررت الســير يف الدعــوى فطلبــت مــن املدعــي حتريــر‬\n      ‫ا إن املدعــى عليه أصالــة كان يعمل مندوب مبيعات‬           ‫دعــواه فادعــى قائـ ُ‬\n      ‫لــدي وقــد اســتلم مــن املؤسســة بضاعــة بقيمــة قدرهــا أربعمائــة واثنــان‬\n      ‫وعشــرون ألف وتســعمائة وتســعون ريا ًال وقد طالبت املدعى عليه بإعادة‬\n      ‫البضاعــة أو قيمتهــا فذكــر لــي أنــه قــد بــاع البضاعــة باملبلــغ املذكــور‬\n      ‫وقــد قــام باســتالم املبلــغ واختالســه أطلــب احلكــم علــى املدعــى عليــه‬\n      ‫بإلزامــه بتســليمي املبلــغ املذكــور وقــدره أربعمائــة واثنــان وعشــرون ألف ًا‬\n      ‫وتســعمائة وتســعون ألــف ريــال هــذه دعــواي وبطلــب البينــة مــن املدعــي‬\n      ‫أبــرز ورقــة مكتوبــة بخــط اليــد وباالطــاع عليهــا وجــدت نصهــا كمــا‬\n      ‫يلــي ‪ :‬أقــر أنــا حامــل إقامــة رقــم إننــي اختلســت مــن التحصيــل اخلــاص‬\n      ‫ملؤسســة ‪ .....‬مبلــغ وقــدره (‪ )422990‬أربعمائــة وأثنــان وعشــرون ألــف‬\n      ‫وتســعمائة وتســعون ريــال ســعودي وســوف أقــوم بســدادها خــال فتــرة‬\n      ‫ا ملؤسســة‬  ‫أقصاهــا ثــاث أيــام مــن تاريخــه وأتعهــد بســداد املبلــغ كامـ ً‬\n      ‫‪ ......‬ويف حالــة عــدم الســداد يقــدم هــذا اإلقــرار إلــى اجلهــات القضائيــة‬\n      ‫وهــذا إقــرار منــي بذلــك أه ـ ومذيــل اإلقــرار ببصمــة املقــر مبــا فيــه‬\n      ‫والشــاهد األول والشــاهد الثانــي كمــا أبــرز ورقــة مكتوبــة باحلاســب‬\n      ‫اآللــي علــى ورق مكتــب محاســبون ومراجعــون قانونيــون ونصهــا كمــا‬\n      ‫يلــي ‪ :‬نفيدكــم بأننــا قــد قمنــا مبراجعــة املصادقــات اخلاصــة بعمــاء‬\n      ‫‪ .......‬املنــدوب مصــري اجلنســية مبوجــب إقامــة رقــم ‪ .......‬صــادرة مــن‬\n      ‫الريــاض وتنتهــي بتاريــخ ‪1433/8/5‬ه ـ كمــا يف ‪2011/9/29‬م والــذي‬\n\n\n‫‪335‬‬\n\f‫يعمــل لــدى مؤسســة ‪......‬للتجــارة حيــث تبــن وجــود فروقــات (عجــز)‬\n‫يف بعــض أرصــدة العمــاء مببلــغ (‪ )422,990‬فقــد أربعمائــة واثنــان‬\n‫وعشــرون ألفـ ًا وتســعمائة وتســعون ريــال ســعودي ال غيــر جتــدون مرفقــا‬\n‫طيــه كشــف بأســماء العمــاء والفروقــات اخلاصــة بــكل عميــل علــى‬\n‫حــدة أه ـ ومذيــل اخلطــاب بتوقيــع ‪ ...‬ومختــوم بختــم مكتبــه وبســؤال‬\n‫املدعــي أصالــة هــل لديــك زيــادة بينــة فأجــاب بالنفــي وبســؤاله عــن‬\n‫ا يوجــد لــدي أحــد الشــهود وهــو‬    ‫شــهود اإلقــرار املذكــور أجــاب قائ ـ ً‬\n‫وأمــا الشــاهد الثانــي فليــس موجــود ًا يف الســعودية وقــد ســافر يف إجــازة‬\n‫إلــى مصــر وقــد أحضــرت الشــاهد املذكــور هكــذا أجــاب ويف هــذه‬\n‫اجللســة حضــر الشــاهد ‪.....‬مصــري اجلنســية مبوجــب اإلقامــة رقــم ‪......‬‬\n‫ومــن مواليــد عــام ‪1977‬م ويعمــل لــدى مؤسســة ‪....‬ويســكن يف حــي‬\n‫‪ .......‬مبكــة املكرمــة وبســؤاله عــن عالقتــه باملدعــي واملدعــى عليــه‬\n‫ا أمــا املدعــي فابنــه كفيلــي وأمــا املدعــى عليــه فهــو زميلــي‬‫أجــاب قائـ ً‬\n‫يف العمــل وأعمــل أنــا وهــو مناديــب لــدى مؤسســة‪ .......‬املدعــي وبســؤاله‬\n‫ا أشــهد بــأن املدعــى عليــه قــد أقــر‬  ‫عمــا لديــه مــن شــهادة أجــاب قائ ـ ً‬\n‫أمــام املدعــي باختالســه مبلــغ وقــدره أربعمائــة واثنــان وعشــرون ألــف‬\n‫وتســعمائة وتســعون ريــا ًال وقــد أعــد اقــرار ًا بخــط يــده علــى اختالســه‬\n‫للمبلــغ املذكــور واســتعداده بإعــادة املبلــغ خــال ثالثــة أيــام مــن تاريــخ‬\n‫اإلقــرار وقــد شــهدت علــى هــذا اإلقــرار ووقعــت عليــه هــذا مــا لــدي وبــه‬\n‫أشــهد فجــرى ســؤال املدعــي أصالــة هــل الشــاهد يعمــل لديــك فأجــاب‬\n‫ا نعــم الشــاهد يعمــل لــدي وهــو بكفالــة ابنــي فجــرى إفهامــه بــأن‬    ‫قائـ ً‬\n‫شــهادته ال تقبــل شــرع ًا كمــا جــرى إفهامــه بأنــه يلزمــه حلــف ميــن‬\n‫االســتظهار علــى صحــة دعــواه وعلــى أن املدعــى عليــه لــم يقــم بســداد‬\n\n\n                                                                                      ‫‪336‬‬\n\f      ‫املبلــغ املدعــى بــه أو بعضــه لكــون خصمــه غائب ـ ًا وذلــك بعــد تذكيــره‬\n      ‫بخطرهــا وبحرمــة الزمــان واملــكان وبقولــه صلــى اهلل عليــه وســلم ( مــن‬\n      ‫حلــف علــى ميــن هــو فيهــا فاجــر ليقتطــع بهــا مــال امــرئ مســلم لقــي اهلل‬\n      ‫ا ‪:‬واهلل العظيــم‬  ‫وهــو عليــه غضبــان ) رواه مســلم فاســتعد وحلــف قائ ـ ً‬\n      ‫الــذي ال إلــه إال هــو عالــم الغيــب والشــهادة الرحمــن الرحيــم أن املدعــى‬\n      ‫عليــه ‪ ...‬يعمــل لــدى يف املؤسســة اخلاصــة بــي بوظيفــة منــدوب مبيعــات‬\n      ‫وبعــد جــرد البضاعــة أتضــح أنــه قــد قــام باختــاس املبلــغ املذكــور يف‬\n      ‫دعــواي وقــد أقــر املدعــى عليــه بذلــك وأعــد إقــرارا علــى نفســه بذلــك‬\n      ‫واســتعد بإعــادة املبلــغ خــال ثالثــة أيــام مــن تاريــخ إقــراره ولــم يقــم‬\n      ‫املدعــى عليــه بإعــادة املبلــغ املذكــور وال بعضــه واهلل العظيــم فبنــاء‬\n      ‫علــى مــا تقــدم مــن دعــوى املدعــي وملــا ورد يف املــادة اخلامســة واخلمســن‬\n      ‫املشــار إليهــا بعاليــه وألن املدعــي قــد حلــف ميــن االســتظهار كمــا هــو‬\n      ‫مفصــل أعــاه ولتضــرر املدعــي مــن عــدم حضــور املدعــى عليــه ولكــون‬\n      ‫الشــريعة جــاءت برفــع الضــرر كمــا يف قولــه صلــى اهلل عليــه وســلم (ال‬\n      ‫ضــرر وال ضــرار ) رواه أحمــد ومبــا أن للحاكــم واليــة علــى مــال الغائــب‬\n      ‫وملــا قــرره أهــل العلــم مــن جــواز احلكــم عليــه وعلــى املســتتر واملمتنــع ولــو‬\n      ‫كان يف البلــد ومبــا أن املدعــي قــد أبــرز قرائــن تقــوي جانبــه مــع ضعــف‬\n      ‫جانــب املدعــى عليــه بامتناعــه مــن احلضــور وهــو نــوع نكــول وقــد ترجــح‬\n      ‫أكثــر باليمــن املرجحــة لذلــك كلــه وألن القضــاء يعتمــد علــى غلبــة‬\n      ‫الظــن ورجحانــه فقــد ثبــت لــدي صحــة دعــوى املدعــي وحكمــت علــى‬\n      ‫املدعــى عليــه حضوريـ ًا بــأن يدفــع للمدعــي أصالــة مبلــغ وقــدره أربعمائــة‬\n      ‫واثنــان وعشــرون ألفـ ًا وتســعمائة وتســعون ريــا ًال وبعــد ذلــك يخلــى ســبيله‬\n      ‫مــن هــذه الدعــوى وهــو علــى دعــواه متــى حضــر وبعرضــه علــى املدعــي‬\n\n\n‫‪337‬‬\n\f‫قــرر قناعتــه باحلكــم وقــررت إكمــال مــا يلــزم حيــال إبــاغ املدعــى‬\n‫عليــه الغائــب باحلكــم حســب التعليمــات ثــم رفــع كامــل املعاملــة حــال‬\n‫االقتضــاء إلــى محكمــة االســتئناف لدراســة احلكــم وتدقيقــه حســب‬\n‫املتبــع وانتهــت اجللســة الســاعة احلاديــة عشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى‬\n‫اهلل على نبينا محمد وعلى آله وصحبه وســلم ‪ .‬حرر يف ‪1433/11/28‬‬\n                                                                               ‫هـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم األربعاء املوافق ‪ 1434/1/21‬هـ افتتحت‬\n‫اجللســة وقــد وردتنــا املعاملــة اخلاصــة بدعــوى ‪ ...‬ضــد املدعــى عليــه مــن‬\n‫الدائــرة اجلزائيــة اخلامســة مبحكمــة االســتئناف مبكــة املكرمــة‬\n‫واملتضمــن احلمــد هلل وحــده وبعــد فقــد اطلعنــا علــى هــذا الصــك رقــم‬\n‫‪ 33474299‬يف ‪1433/12/21‬ه ـ الصــادر مــن فضيلة الشــيخ ‪ /‬القاضي‬\n‫باحملكمــة العامــة مبكــة املكرمــة وأصدرنــا القــرار رقــم ‪347777‬‬\n‫يف ‪1434/1/11‬ه ـ املتضمــن املوافقــة علــى احلكــم أه ـ ‪ .‬عضــو ختمــه‬\n‫وتوقيعــه عضــو ختمــه وتوقيعــه رئيــس الدائــرة د‪ /‬ختمــه وتوقيعــه عليــه‬\n‫فقــد أمــرت بضبــط ذلــك وإحلاقــه بصكــه وســجله حتــى ال يخفــى وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                  ‫حــرر يف ‪ 1434/1/21‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                    ‫‪338‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":332,"source_page_end":338,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"95aa667386879f26e14e2dd380af622f26e7d091fbc9c648107540d99ebe0d3c","normalized_text_hash":"6410509359eafdabad54b69be0f2848aa64624222b4e9e97653e51bdb7948e70","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p332-33474299"},{"id":"d0c99b93-e4cb-58f3-b4c7-7a4e1be921f6","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد مختلس -اختاس أجهزة وقطع غيار عن طريق خيانة األمانة -إثبات بالقرائن مع مين املدعي -ثبوت الدعوى -خصم ما سدد من املبلغ -إخراج البضائع بفواتير -املتهم أمن املخزن والبضاعة عهدة لديه .","document_number":"3414912","case_number":"33379091","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/18","year":"1434","subject":"مطالبة برد مختلس -اختاس أجهزة وقطع غيار عن طريق خيانة األمانة -إثبات بالقرائن مع مين املدعي -ثبوت الدعوى -خصم ما سدد من املبلغ -إخراج البضائع بفواتير -املتهم أمن املخزن والبضاعة عهدة لديه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/1/18 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3414912 :‬‬\n                         ‫َر ْق ُم الدعوى‪33379091 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3473031‬تاريخه‪1434/1/25:‬هـ‬\n\n\n      ‫مطالبــة بــرد مختلــس ‪ -‬اختــاس أجهــزة وقطــع غيــار عــن طريق خيانة‬\n      ‫األمانــة ‪ -‬إثبــات بالقرائــن مــع ميــن املدعــي ‪ -‬ثبــوت الدعــوى ‪ -‬خصــم‬\n      ‫مــا ســدد مــن املبلــغ ‪ -‬إخــراج البضائــع بفواتيــر ‪ -‬املتهــم أمــن املخــزن‬\n                                                         ‫والبضاعــة عهــدة لديــه ‪.‬‬\n\n\n\n\n      ‫مــا أســتند إليــه القاضــي مــن املبــادئ العامــة وقواعد العدالة يف تســبيب‬\n                                                                          ‫حكمه ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي علــى احلاضــر معــه بأنــه َّإبــان عملــه يف املؤسســة التــي‬\n      ‫ميلكهــا كأمــن مســتودع قــام باختــاس أجهــزة مضخــات وقطــع غيــار‬\n      ‫مــن املؤسســة وبيعهــا حلســابه اخلــاص‪ ،‬ولــذا فقــد طلــب إلزامــه بتســليم‬\n      ‫ال‬\n      ‫قيمــة األجهــزة املختلســة ‪ -‬أنكــر املدعــى عليــه الدعــوى جملــة وتفصي ً‬\n      ‫‪ -‬قــدم املدعــي للمحكمــة عــددا مــن القرائــن التــي تعضــد دعــواه منهــا‬\n      ‫إقــرار للمدعــى عليــه مصــدق شــرعا بجــزء مــن املبلــغ‪ ،‬وتقريــر جهــات‬\n      ‫التحقيــق املتضمــن إقــراره بــأن جميــع عهــد املســتودع حتــت عهدتــه وأنــه‬\n      ‫كان علــى علــم بحــدوث االختالســات‪ ،‬وتقريــر احملاســب القانونــي‬\n      ‫الــذي يثبــت وجــود العجــز‪ -‬قــررت احملكمــة توجيــه اليمــن املكملــة‬\n‫‪339‬‬\n\f‫للمدعــي فأداهــا طبــق مــا طلــب منــه‪ -‬قضــت احملكمــة بإلــزام املدعــى‬\n‫عليــه بتســليم املدعــي املبلــغ املدعــى بــه ‪ -‬عــارض املدعــى عليــه علــى‬\n‫احلكــم‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم بعــد‬\n                                                           ‫اإلجــراء األخيــر‪.‬‬\n\n\n\n\n‫احلمد هلل وحده وبعد فلدي أنا‪ /‬القاضي يف احملكمة العامة مبحافظة‬\n‫جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫مبحافظــة جــدة ‪ /‬املســاعد برقــم ‪ 33379091‬وتاريــخ ‪1433/06/04‬ه ـ‬\n‫املقيدة باحملكمة برقم ‪ 331021155‬وتاريخ ‪1433/06/01‬هـ حضر‪/‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وادعــى علــى احلاضــر معــه‬\n‫باملجلــس الشــرعي‪ /‬مينــي اجلنســية باإلقامــة رقــم قائــا يف دعــواه عليــه‬\n‫إن املدعــى عليــه كان يعمــل كأمــن مســتودع لــدي‪ /‬مبوجــب العقــد‬\n‫املــؤرخ يف ‪2007/1/1‬م وقــد قــام باختــراق البرنامــج اخلــاص مبؤسســتي‬\n‫وتعديــل وحــذف أرصــدة حيــث اســتولى علــى مضخــات وقطــع غيــار‬\n‫ومعــدات أخــرى لبيعهــا حلســابه وتبلــغ قيمــة املضخــات وقطــع الغيــار التي‬\n‫اختلســها املدعــى عليــه ثالثمائــة وثالثــة وســتون ألــف وثالثمائــة وواحــد‬\n‫وثمانــون ريــاال أطلــب احلكــم عليــه بدفعهــا وبســؤال املدعــى عليــه قــال‬\n‫مــا ذكــره املدعــي مــن أننــي كنــت أعمــل لديــه صحيــح ولكــن مــا‬\n‫ذكــر مــن اختــراق برنامــج مؤسســة املدعــي واســتيالئي علــى املضخــات‬\n‫وقطــع الغيــار غيــر صحيــح وليــس يف ذمتــي للمدعــي أي شــيء هــذا‬\n‫وبســؤال املدعــي عــن بينتــه قــال ‪ :‬إنــه ســبق التحقيــق مــع املدعــى عليــه‬\n‫وســجن للحــق العــام ومذكــور ذلــك يف أوراق املعاملــة وعليــه رفعــت‬\n                                                                                        ‫‪340‬‬\n\f      ‫اجللســة ويف جلســة أخــرى حضــر املدعــي كمــا جــرى إحضــار املدعــى‬\n      ‫عليــه هــذا وباالطــاع علــى أوراق املعاملــة ظهــر القــرار رقــم ‪/13/124‬ج‬\n      ‫يف ‪1432/11/21‬ه ـ مــن احملكمــة اجلزئيــة بجــدة املتضمــن مصادقــة‬\n      ‫املدعــى عليــه علــى مــا ذكــر يف دعــوى املدعــي العــام مــن اختالســه مبلــغ‬\n      ‫عشــرة آالف ريــال وأنــه قــام بإرجاعهــا أمــا بقيــة املبالــغ فليــس مســئوال‬\n      ‫عنهــا واملســئول عنهــا هــو مديــر التســويق املدعــو‪ ، /‬كمــا تضمــن‬\n      ‫القــرار املذكــور اإلشــارة إلــى اعتــراف املدعــى عليــه املصــدق شــرعا‬\n      ‫املتضمــن قولــه ‪ :‬إنــه يف عــام ‪2010‬م وبصفتــي أمــن املســتودع مبؤسســة‬\n      ‫‪ ....‬للمضخــات الزراعيــة وأدوات احلفــر والتكســير قمــت بأخــذ غطــاس‬\n      ‫لوبــي ارتــوازي قيمتــه مــا بــن خمســة آالف إلــى ســتة آالف ريــال وقمــت‬\n      ‫ببيعــه بنفــس القيمــة وأخــذت املبلــغ حلســابي اخلــاص دون علــم املؤسســة‬\n      ‫وكذلــك قمــت ببيــع عــدد مــن قطــع الغيــار وال أذكر أنواعهــا بالتحديد‬\n      ‫واملبالــغ املســئول عنهــا والتــي تصرفــت بهــا مــن أمــوال الشــركة تقــدر‬\n      ‫بحوالــي عشــرة آالف ريــال وبالنســبة للمبالــغ التــي حصــل عليهــا عجــز‬\n      ‫باملؤسســة فاملســئول عنهــا هــو املدعــو‪ /‬ســوري اجلنســية والــذي يعمــل‬\n      ‫باملؤسســة بوظيفــة مديــر فنــي أه ـ وقــد مت احلكــم عليــه بســجنه ســنة‬\n      ‫أه ـ كمــا ظهــر يف اللفــة ‪ 3‬مــن املعاملــة تقريــر يتضمــن نتيجــة احلقيــق‬\n      ‫توجيــه االتهــام للمدعــى عليــه باالشــتراك مــع املدعــو‪ /‬باختــاس مبالــغ‬\n      ‫ماليــة مــن مؤسســة العلــم الدوليــة العائــدة للمدعــو ‪ /‬تقــدر بحوالــي‬\n      ‫ثالثمائــة ألــف ريــال عــن طريــق بيــع بعــض املعدات حلســاباتهم الشــخصية‬\n      ‫واختــراق برنامــج املؤسســة وتعديــل بعــض األصنــاف واصــدار فواتيــر‬\n      ‫ملســميات وهميــه وتعديــل وحــذف وشــطب بعــض العمليــات املتعلقــة‬\n      ‫بأرصــدة املســتودع الــذي حتــت عهدتــه وذلــك ملــا جــاء يف أقــوال املدعــى‬\n\n\n‫‪341‬‬\n\f‫عليــه بأنــه املســئول عــن جميــع عهــد املســتودع وأنــه اختلــس مبالــغ ماليــة‬\n‫ببيــع بعــض املعــدات ومصادقتــه علــى ذلــك شــرعا وملــا جــاء يف التقريريــن‬\n‫مــن احملاســب القانونــي التــي توضــح وجــود عجــز مالــي بذلــك املبلــغ مــن‬\n‫عهــدة املذكــور واعتــراف املدعــى عليــه بعملــه مبــا كان يحــدث مــن‬\n‫عمليــات اختــاس يف عهــدة املســتودع ويف برنامــج املؤسســة مــن تعديــل‬\n‫وحــذف وشــطب أه ـ وبعــرض ذلــك علــى املدعــى عليــه قــال ‪ :‬إن إقــراري‬\n‫باختــاس عشــرة آالف ريــال صحيــح وقــد قمــت بســداد هــذا املبلــغ أمــا‬\n‫بقيــة املبلــغ فــا أعلــم عنــه حيــث إن ‪ ....‬املذكــور أخــذ الرقــم الســري‬\n‫مــن املدعــي ‪ ،‬أمــا مــا ذكــر مــن مســئوليتي علــى املســتودع فصحيــح‬\n‫وقــد قمــت بإخــراج البضاعــة بحكــم الثقــة مــع املدعــي ‪ ....‬املذكــور‬\n‫أمــا بشــأن أننــي كنــت أعلــم بعمليــات االختــاس فغيــر صحيــح وبعــرض‬\n‫ذلــك علــى املدعــي قــال ال أذكــر أن املدعــى عليــه دفــع عشــرة آالف ريال‬\n‫ولكــن إبــراء للذمــة ال مانــع لــدي مــن خصمهــا مــن املبلــغ املدعــى بــه ثــم‬\n‫أبــرز محضــر تســليم مســتودع يف ‪2011/2/3‬م يتضمــن وجــود عجــز‬\n‫مالــي بحوالــي مائــة وأربعــة آالف وأربعمائــة وواحــد وتســعني ألــف ريــال‬\n‫وموقــع عليــه مــن املدعــى عليــه ‪ ،‬كمــا أبــرز تقريــر محاســبي صــادر مــن‬\n‫مكتــب الدكتــور ‪ ....‬لألعــوام ‪2007‬م إلــى ‪2010‬م مببلــغ عجــز قــدره‬\n‫مائتــان وتســعون ألــف وتســعمائة وســتة وأربعــون ريــاال والثانــي لعــام‬\n‫‪2011‬م مببلــغ اثنــن وســبعني ألــف وأربعمائــة وخمســة وثمانــن ريــاال أه ـ‬\n‫ثــم أضــاف املدعــي قائــا ‪ :‬إن املجمــوع هــو ثالثمائــة وثالثــة وســتون ألــف‬\n‫وثالثمائــة وواحــد وثمانــون ريــاال وبعــد خصــم مــا ذكــر يكــون املبلــغ‬\n‫املدعــى بــه ثالثمائــة وثالثــة وخمســون ألــف وثالثمائــة وواحــد وثمانــون‬\n‫ريــاال أطلــب احلكــم بــه وبعــرض ذلــك علــى املدعــى عليــه قــال ‪ :‬إنني غير‬\n\n\n                                                                                       ‫‪342‬‬\n\f      ‫مســئول عن ما ذكر يف االختالســات املذكورة ‪ ،‬هذا وبســؤال املدعي‬\n      ‫هــل يحلــف اليمــن زيــادة علــى مــا تقــدم قــال أنــا مســتعد بحلــف اليمــن‬\n      ‫وبطلبهــا بعــد وعظــه بعظــم اليمــن حلــف قائــا ‪ :‬أقســم بــاهلل العظيــم‬\n      ‫الــذي ال إلــه إال هــو ان هــذه الدعــوى صحيحــة وأن املدعــى عليــه هــو‬\n      ‫املســئول عــن املبلــغ املختلــس ثالثمائــة وثالثــة وخمســون ألــف وثالثمائــة‬\n      ‫وواحــد وثمانــون ريــال وحــده عــن ذلــك واهلل العظيــم فبنــاء علــى الدعــوى‬\n      ‫وجــواب املدعــى عليــه وحيــث حلــف املدعــي اليمــن زيــادة علــى مــا تقــدم‬\n      ‫مــن إقــرار املدعــى عليــه باختــاس جــزء مــن املبلــغ وبنــاء علــى محضــر‬\n      ‫التحقيــق لــذا حكمــت علــى أن يدفــع للمدعــي ‪ ..........‬املبلــغ املدعــى‬\n      ‫بــه وقــدره ثالثمائــة وثالثــة وخمســون ألــف وثالثمائــة وواحــد وثمانــون‬\n      ‫ريــال وبتالوتــه علــى املدعــى عليــه قــرر عــدم القناعــة وأن لديــه الئحــة‬\n      ‫اعتراضيــة فأفهــم بــأن موعــد اســتالم صــورة صــك احلكــم بعــد خمســة‬\n      ‫أيــام لتقــدمي الئحــة خــال ثالثــن يومــا وإال اكتســب احلكــم القطعيــة‬\n      ‫وأمــرت بتنظيــم صــك بذلــك وتســجيله وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/7/28‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ :‬حيــث عــادت إلينــا املعاملــة مــن محكمــة‬\n      ‫االســتئناف بالقــرار رقــم ‪ 33457257‬يف ‪1433/11/17‬ه املتضمــن‬\n      ‫مالحظــة مــا يلــي ‪ :‬أن فضيلتــه لــم يســبب احلكــم مــن الثبــوت وعدمــه وال‬\n      ‫بــد مــن ذلــك ملالحظــة مــا ذكــر وإجراء مــا يلزم أهـ وعليــه حضر املدعي‬\n      ‫كمــا جــرى إحضــار املدعــى عليــه حيــث قــرر قائــا إننــي كنــت أعمــل‬\n      ‫لــدى املدعــي كأمــن مســتودع ولــم يوجــد مســئول غيــري عــن املســتودع‬\n      ‫كمــا أنــه ال يتــم إخــراج أي بضاعــة مــن املســتودع إال بفاتــورة وقــد قمــت‬\n      ‫بإخــراج بضائــع بــدون فواتيــر بنــاء علــى طلــب ‪ ....‬الــذي يعمــل منــدوب‬\n\n\n‫‪343‬‬\n\f‫مبيعــات لــدى املدعــي وقــد عرضــت ذلــك علــى املدعــي فوافــق علــى مــا‬\n‫طلبــه ‪ ....‬املذكــور وبعــرض ذلــك علــى املدعــي قــال مــا ذكــره املدعــى‬\n‫عليــه غيــر صحيــح فلــم آذن للمدعــى عليــه وال ‪ ....‬املذكــور بإخــراج أي‬\n‫بضاعــة بــدون فاتــورة مقيــدة وبعــرض ذلــك علــى املدعــى عليــه وســؤاله‬\n‫هــل لديــه بينــة علــى مــا ذكــر مــن موافقــة املدعــي إلخــراج بضائــع مــن‬\n‫املســتودع بــدون فواتيــر قــال ال بينــة لــدي ‪ ،‬كمــا أنــي قــد عملــت لــدى‬\n‫املدعــي ســبع ســنوات ويف كل عــام ال يظهــر أي اختالســات ولــم تظهــر‬\n‫االختالســات ســوى يف العــام األخيــر وبســؤاله أيضــا هــل يطلــب ميــن‬\n‫املدعــي علــى مــا أنكــر قــال ال أطلــب ميينــه ‪ .‬وعليــه وحيــث إن املدعــى‬\n‫عليــه قــد أقــر مبســئوليته عــن البضاعــة املوجــودة باملســتودع ولــم يثبــت‬\n‫مــا ادعــاه لــذا فــا زلــت علــى مــا حكمــت بــه وأجريتــه وأمــرت بإحلــاق‬\n‫ذلــك بالصــك وســجله ورفــع أوراق املعاملــة حملكمــة االســتئناف وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                  ‫حــرر يف ‪1433/12/29‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد حيــث عــادت إلينــا املعاملــة بخطــاب فضيلــة‬\n‫رئيــس محكمــة االســتئناف مبكــة املكرمــة املكلــف رقــم ‪3440822‬‬\n‫يف ‪ 1434/1/26‬ه ـ املتضمــن أنــه جــرى تدقيــق احلكــم مــن الدائــرة‬\n‫اجلزائيــة األولــى وصــدر بحقــه القرار رقــم ‪ 3473031‬يف ‪1434/1/25‬هـ‬\n‫املــدون علــى ظهــر الصــك واملتضمــن أنــه باالطــاع علــى الصــك رقــم‬\n‫‪ 3414912‬وتاريخ‪1434/1/18‬هـ ـ الصــادر مــن فضيلــة الشــيخ ‪/‬‬\n‫القاضــي باحملكمــة العامــة مبحافظــة جــدة املتضمــن دعــوى ‪.........‬‬\n‫ضــد‪ /‬مينــي اجلنســية املتهــم بقضيــة اختــاس احملكــوم فيــه مبــا دون‬\n‫باطنــه وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة بعــد‬\n\n\n                                                                                   ‫‪344‬‬\n\f      ‫اإلجــراء األخيــر تقــررت املوافقــة علــى احلكــم قاضــي اســتئناف ختمــه‬\n      ‫وتوقيعــه قاضــي اســتئناف ختمــه وتوقيعــه رئيــس الدائــرة ختمــه وتوقيعــه‬\n      ‫وعليــه أمــرت بإحلــاق ذلــك يف ضبطــه وســجله وبــاهلل التوفيــق وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪ 1434/2/6‬ه ـ ‪.‬‬\n\n\n\n\n‫‪345‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":339,"source_page_end":345,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cabf1d48977b99c4e288e85ba778f48ea470afd665ac7f9b4e5ce821ecc5f2b9","normalized_text_hash":"be35b501927bbba2dae9f76b93dc138167de71815bc9d2264bc3b44ce0a2fa87","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p339-3414912"},{"id":"62e02b9d-05dc-5c4f-ad0b-346e9e9f1095","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مختلس -اختاس بضاعة عن طريق خيانة األمانة -بينات غير موصلة -استحقاق املدعي ليمن املدعى عليه على نفي الدعوى متى طلبها -احلكم برد دعوى.","document_number":"34239280","case_number":"33572978","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/12","year":"1434","subject":"رد مختلس -اختاس بضاعة عن طريق خيانة األمانة -بينات غير موصلة -استحقاق املدعي ليمن املدعى عليه على نفي الدعوى متى طلبها -احلكم برد دعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/6/12 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34239280 :‬‬\n                   ‫َر ْق ُم الدعوى‪33572978 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34341119‬تاريخه‪1434/10/26:‬هـ‬\n\n\n‫رد مختلــس ‪ -‬اختــاس بضاعــة عــن طريــق خيانــة األمانــة ‪ -‬بينــات غير‬\n‫موصلــة ‪ -‬اســتحقاق املدعــي ليمــن املدعــى عليــه علــى نفــي الدعــوى‬\n                                        ‫متــى طلبهــا ‪ -‬احلكــم بــرد دعــوى‪.‬‬\n\n\n\n\n‫مــا اســتند إليــه القاضــي مــن القواعــد العامــة ومبــادئ العدالــة الــواردة‬\n                                                          ‫يف تســبيب حكمــه ‪.‬‬\n\n\n\n‫ادعــى وكيــل املدعــي علــى احلاضــر معــه بأنــه َّإبــان عملــه لــدى موكلــه‬\n‫قــام باختــاس بضاعــة مــن املســتودع الــذي يعمــل فيــه والعائــد ملوكلــه‪،‬‬\n‫طلــب إلزامــه بــرد البضاعــة املختلســة أو تســليم قيمتهــا إلــى موكلــه‬\n‫‪ -‬أنكــر املدعــى عليــه الدعــوى جملــة وتفصيــا ســوى أنــه يعمــل لــدى‬\n‫املدعــي ‪ -‬أحضــر املدعــي عــددا مــن الشــهود فأدلــوا بشــهادتهم أمــام‬\n‫احملكمــة إال أن شــهادة أي منهــم لــم تكــن موصلــة إلثبــات دعــواه ‪-‬‬\n‫أفهمــت احملكمــة املدعــي بــأن لــه ميــن املدعــى عليــه علــى نفــي دعــواه‬\n‫فلــم يقبلهــا ‪ -‬قضــت احملكمــة بصــرف النظــر عــن دعــوى املدعــي لعــدم‬\n‫ثبوتهــا وأفهمتــه بــأن لــه ميــن املدعــى عليــه علــى نفــي دعــواه متــى طلبهــا‬\n‫‪ -‬قنــع املدعــى عليــه باحلكــم وعــارض عليــه املدعــي ‪ -‬قــررت محكمــة‬\n                                           ‫االســتئناف املصادقــة علــى احلكــم‪.‬‬\n                                                                                        ‫‪346‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض ‪ /‬املســاعد برقــم ‪ 33572978‬وتاريــخ ‪1433/09/12‬هـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331674178‬وتاريــخ ‪ 1433/09/09‬ه ـ ففــي‬\n      ‫يــوم الســبت املوافق‪1434/01/24‬ه ـ حضــر ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم عــن مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n      ‫الثانية بشرق الرياض رقم ‪ 33180690‬وتاريخ ‪1433/7/19‬هـ واملخول‬\n      ‫لــه فيهــا حــق املرافعــة واملدافعــة وحــق اإلقــرار والصلــح وحضــر حلضــوره‬\n      ‫مصــري اجلنســية مبوجــب رخصــة إقامــة رقــم وادعــى األول قائــا يف‬\n      ‫دعــواه ان هــذا احلاضــر معــي يعمــل لــدى موكلــي يف مســتودعه الواقــع‬\n      ‫بحــي ‪ .....‬بالريــاض بشــارع ‪ ......‬وطبيعــة عملــه جتهيــز طلبــات للموزعــن‬\n      ‫واملســتودع بــه بضاعــة نظــارات وعدســات الصقــة وقــد قــام باختــاس‬\n      ‫بضاعــة علــى مــدى عــدة أيام وتفصيل هذه البضاعة كالتالي عدد ‪288‬‬\n      ‫علبــة ‪ ...‬ثمــن العلبــة ‪160‬ريــال ومجموعهــا ســتة وأربعــون ألــف وثمانــون‬\n      ‫ريــ‪ 46.080‬ــاال وعــدد ‪ 400‬نظــارة شمســية وطبيــة يقــدر قيمتهــا مببلــغ‬\n      ‫ريــ‪ 105.250‬ــاال وكذلــك عــدد ‪ 188‬علبــة اكيــو فيــو ‪ 2‬وثمــن العلبــة‬\n      ‫الواحــدة ‪ 120‬فيكــون املجمــوع ريـ‪ 22.560‬ــاال ليصبــح إجمالــي املبالــغ‬\n      ‫املختلســة مــن النظــارات والعدســات الالصقــة مائــة وثالثــة وســبعون‬\n      ‫ألفــا وثمامنائــة وتســعون ريــ‪ 173.890‬ــاال اطلــب إلزامــه بــرد البضاعــة‬\n      ‫املختلســة أو إعــادة قيمتهــا هــذه دعــواي وبســؤال املدعــى عليــه أجــاب‬\n      ‫بقولــه مــا ذكــره املدعــي وكالــة يف دعــواه أننــي اعمــل لــدى موكلــه‬\n\n‫‪347‬‬\n\f‫يف املســتودع الــذي ذكــره صحيــح ومــا ذكــره مــن اختالســات فكلهــا‬\n‫غيــر صحيحــة فلــم اختلــس مــن املســتودع شــيئا وليــس لــه يف ذمتــي شــيء‬\n‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــي وكالــة قــال الصحيــح مــا‬\n‫ذكــرت ولــدي البينــة ويف يــوم األحــد املوافق‪1434/06/11‬ه ـ حضــر‬\n‫املدعــي اصالــة ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وحضــر‬\n‫حلضــوره املدعــى عليــه ‪ ...‬وبطلــب البينــة مــن املدعــي احضــر معــه مصــري‬\n‫اجلنســية مبوجــب رخصــة إقامــة رقــم وطلــب ســماع مــا لديــه وبســؤاله‬\n‫قــال أننــي اعمــل أخصائــي بصريــات لــدى كفيلــي املدعــي وانــا مــن‬\n‫مواليــد ‪1987‬م واشــهد أن احملاســب الــذي يعمــل لــدى كفيلــي اطلعنــي‬\n‫علــى صــورة اكيــاس عاديــة ال اعلــم مــا يف داخلهــا هــذا مــا لــدي مــن‬\n‫شــهادة كمــا احضــر معــه هنــدي اجلنســية مبوجــب رخصــة إقامــة رقــم‬\n‫وطلــب ســماع مــا لديــه وبســؤاله بواســطة مترجــم احملكمــة قــال أننــي‬\n‫مــن مواليــد عــام ‪1954‬م واعمــل فنــي بصريــات لــدى كفيلــي املدعــي‬\n‫اصالــة واشــهد أن املدعــى عليــه يعمــل ســواق ومنــدوب مبيعــات ورايتــه‬\n‫حــط كرتونــن ال اعلــم مــا بداخلهــا عنــد الســلم وســألته ملــاذا فقــال‬\n‫للبلديــة هــذا مــا لــدي وبــه اشــهد كمــا احضــر معــه وطلــب ســماع مــا‬\n‫لديــه وبســؤاله بواســطة املترجــم املذكــور قــال أننــي مــن مواليــد عــام‬\n‫‪ 1984‬م واعمــل فنــي بصريــات لــدى كفيلــي املدعــي اصالــة واشــهد‬\n‫أن املدعــى عليــه أخــذ كرتــون مــن املســتودع ال اعلــم مــا يف داخلــه مــن‬\n‫مســتودع كفيلــي هــذا مــا لــدي مــن شــهادة وبطلب زيادة بينــة من املدعي‬\n‫قــال ليــس لــدي ســوى مــن أحضــرت فأفهمتــه بــأن لــه ميــن املدعــى عليــه‬\n‫علــى نفــي دعــواه فقــال ال أطلــب ميينــه فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة املتضمنــة إنــكار املدعــى عليــه ملــا جــاء يف دعــوى املدعــي‬\n\n\n                                                                                       ‫‪348‬‬\n\f      ‫ولعــدم البينــة املوصلــة مــن املدعــي وعــدم طلبــه ميــن املدعــى عليــه لــذا‬\n      ‫صرفــت النظــر عــن دعــوى املدعــي لعــدم ثبوتهــا وأخليــت ســبيل املدعــى‬\n      ‫عليــه وبذلــك حكمــت وأفهمــت املدعــي بــان لــه ميــن املدعــى عليــه متــى‬\n      ‫مــا طلبهــا وبعــرض احلكــم علــى الطرفــن قــرر املدعــي عــدم القناعــة‬\n      ‫وافهــم بــان لــه مــدة ثالثــن يومــا لتقــدمي اعتراضــه عليــه واذا مضــت هــذه‬\n      ‫املــدة ســقط حقــه يف االعتــراض وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                   ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/06/11‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي باحملكمــة العامــة بالريــاض‬\n      ‫خلــف فضيلــة القاضــي ويف يــوم األحــد املوافق‪1434/12/01‬ه ـ افتتحت‬\n      ‫اجللســة بنــاء علــى مــا وردنــا مــن فضيلــة الرئيــس برقــم ‪342067071‬‬\n      ‫وتاريــخ ‪1434/11/23‬ه ـ شــرحا علــى خطــاب محكمــة االســتئناف‬\n      ‫برقــم ‪ 331674178‬وتاريــخ ‪1434/11/12‬ه ـ وبرفقــه قــرار دائــرة‬\n      ‫االســتئناف اجلزائيــة الثانيــة املســجل برقــم ‪ 34341119‬وتاريــخ‬\n      ‫‪1434/10/26‬ه ـ املتضمــن املصادقــة علــى احلكــم قاضــي االســتئناف‬\n      ‫ختمــه وتوقيعــه وقاضــي االســتئناف ختمــه وتوقيعــه وقاضــي االســتئناف‬\n      ‫ختمــه وتوقيعــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                  ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/12/1‬هــ‪.‬‬\n\n\n\n\n‫‪349‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":346,"source_page_end":349,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9b3cc16cab40dfe6d5bf4c0b87c7d0da61b32f32d5599b38e57ca1cd3713d007","normalized_text_hash":"ae43e6a4abcd0b447c2902e401dc419f3f5d5e2d3308214ffc785fb67baae529","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p346-34239280"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
